window.ETSDATA=window.ETSDATA||{};window.ETSDATA[17]={"lc":{"p1":[{"n":1,"opts":["He's digging in a garden.","He's stacking wooden pallets.","He's emptying soil from a pot.","He's examining some plants."],"vi":["Anh ấy đang đào đất trong vườn.","Anh ấy đang xếp chồng các tấm pallet gỗ.","Anh ấy đang đổ đất ra khỏi chậu.","Anh ấy đang xem xét mấy cái cây."],"ans":"D","xp":"Người đàn ông đang đứng cúi nhìn, xem xét các chậu cây bày trên kệ → (D) đúng. (A) anh ấy không đào đất. (B) có pallet gỗ trong ảnh nhưng anh ấy không xếp chồng chúng. (C) anh ấy không đổ đất ra khỏi chậu.","a":"E24-T07-01.mp3","img":"q1.jpg"},{"n":2,"opts":["One of the women is pushing a cart towards an exit.","One of the women is hanging a coat on a hook.","The women are restocking some store shelves.","The women are purchasing some groceries."],"vi":["Một trong hai người phụ nữ đang đẩy xe về phía lối ra.","Một trong hai người phụ nữ đang treo áo khoác lên móc.","Những người phụ nữ đang bày thêm hàng lên kệ cửa hàng.","Những người phụ nữ đang mua thực phẩm."],"ans":"D","xp":"Những người phụ nữ đang thanh toán ở quầy tự tính tiền trong siêu thị, tức là đang mua thực phẩm → (D) đúng (purchase = mua, groceries = thực phẩm, hàng tạp hóa). (A) không ai đẩy xe về phía lối ra. (B) không ai treo áo. (C) họ không xếp hàng lên kệ (restock).","a":"E24-T07-02.mp3","img":"q2.jpg"},{"n":3,"opts":["The man is resting his arm on a counter.","The man is folding his coat.","A cabinet door has been left open.","Some stools are being wiped down."],"vi":["Người đàn ông đang tựa cánh tay lên quầy.","Người đàn ông đang gấp áo khoác.","Một cánh tủ đang bị để mở.","Mấy cái ghế đẩu đang được lau sạch."],"ans":"A","xp":"Người đàn ông ngồi trên ghế đẩu, tựa cánh tay lên mặt quầy (rest his arm on a counter) → (A) đúng. (B) áo khoác đang để trên ghế, anh ấy không gấp áo. (C) cánh tủ phía trên đang đóng. (D) 'are being wiped' = đang được lau → phải có người đang lau, ảnh không có.","a":"E24-T07-03.mp3","img":"q3.jpg"},{"n":4,"opts":["Some balconies are decorated with banners.","Some signs have been posted in front of a building.","A café has been set up on a street corner.","A tour group is standing outside a building."],"vi":["Mấy ban công được trang trí bằng băng rôn.","Một số biển báo đã được dựng trước một tòa nhà.","Một quán cà phê được dựng ở góc phố.","Một đoàn khách du lịch đang đứng bên ngoài tòa nhà."],"ans":"B","xp":"Trước tòa nhà có dựng các tấm biển (signs) → (B) đúng. Ảnh không có băng rôn (A), quán cà phê (C) hay đoàn du lịch (D).","a":"E24-T07-04.mp3","img":"q4.jpg"},{"n":5,"opts":["Some people are waiting at a bus stop.","Bike racks have been placed near a lawn.","Some cars are parked along a sidewalk.","Some people are gathered in a city square."],"vi":["Một số người đang đợi ở trạm xe buýt.","Các giá để xe đạp được đặt gần bãi cỏ.","Một số ô tô đang đỗ dọc vỉa hè.","Một số người đang tụ tập ở quảng trường thành phố."],"ans":"C","xp":"Ô tô đang đỗ dọc theo vỉa hè (parked along a sidewalk) → (C) đúng. Ảnh không có trạm xe buýt (A), giá xe đạp hay bãi cỏ (B); mọi người đang đi bộ chứ không tụ tập ở quảng trường (D).","a":"E24-T07-05.mp3","img":"q5.jpg"},{"n":6,"opts":["The sun is being blocked by some curtains.","There's a large carpet underneath a piano.","There are some windows by a seating area.","Some furniture is being stored in a closet."],"vi":["Ánh nắng đang bị rèm cửa che lại.","Có một tấm thảm lớn dưới cây đàn piano.","Có mấy ô cửa sổ cạnh khu vực ghế ngồi.","Một số đồ đạc đang được cất trong tủ."],"ans":"C","xp":"Ảnh có các ô cửa sổ ngay cạnh chỗ ghế ngồi → (C) đúng. (A) rèm không che nắng. (B) không có đàn piano. (D) đồ đạc không được cất trong tủ (closet).","a":"E24-T07-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"Who's providing the floral arrangements for the party?","qvi":"Ai sẽ cung cấp hoa trang trí cho bữa tiệc?","opts":["The florist on Main Street.","She's had a long career.","Yes, his flight has been arranged."],"vi":["Tiệm hoa trên phố Main.","Cô ấy đã có sự nghiệp lâu năm.","Vâng, chuyến bay của anh ấy đã được sắp xếp."],"ans":"A","xp":"Câu hỏi Who (ai cung cấp hoa) → (A) nêu đơn vị cung cấp: tiệm hoa trên phố Main. (B) 'She' không rõ chỉ ai, lạc đề. (C) câu hỏi Who không trả lời Yes/No; 'arranged' chỉ lặp âm với 'arrangements'.","a":"E24-T07-07.mp3"},{"n":8,"q":"Why didn't you finish the budget report?","qvi":"Sao bạn chưa làm xong báo cáo ngân sách?","opts":["At the finish line.","No, it wasn't expensive.","I was meeting with a client."],"vi":["Ở vạch đích.","Không, nó không đắt.","Tôi bận gặp khách hàng."],"ans":"C","xp":"Câu hỏi Why (tại sao chưa xong) → (C) đưa ra lý do: bận gặp khách hàng. (A) lặp từ 'finish'. (B) câu hỏi Why không trả lời Yes/No; 'expensive' liên tưởng tới 'budget'.","a":"E24-T07-08.mp3"},{"n":9,"q":"What floor are you going to?","qvi":"Bạn lên tầng mấy?","opts":["Can I have a copy of this?","The twenty-fifth.","That painting will look nice there."],"vi":["Cho tôi xin một bản sao cái này được không?","Tầng hai mươi lăm.","Bức tranh đó đặt ở đó sẽ đẹp đấy."],"ans":"B","xp":"Hỏi đi tầng mấy (What floor) → (B) trả lời cụ thể: tầng 25. (A) không liên quan. (C) 'there' gây nhầm vì liên tưởng tới 'going to'.","a":"E24-T07-09.mp3"},{"n":10,"q":"How do I set up this projector?","qvi":"Tôi lắp đặt cái máy chiếu này thế nào?","opts":["The storage area downstairs.","A new project code.","There's a manual in the drawer."],"vi":["Khu vực kho ở tầng dưới.","Một mã dự án mới.","Có sách hướng dẫn trong ngăn kéo."],"ans":"C","xp":"Hỏi cách lắp máy chiếu (How) → (C) gián tiếp chỉ cách: xem sách hướng dẫn (manual) trong ngăn kéo. (A) trả lời nơi chốn, không hợp. (B) 'project' gần âm với 'projector'.","a":"E24-T07-10.mp3"},{"n":11,"q":"Who has already received their promotion letter?","qvi":"Ai đã nhận được thư thăng chức rồi?","opts":["I did yesterday.","A party invitation.","Polina gave the speech."],"vi":["Tôi nhận hôm qua rồi.","Một thư mời dự tiệc.","Polina đã phát biểu."],"ans":"A","xp":"Hỏi ai đã nhận thư thăng chức → (A) 'Tôi đã nhận hôm qua' trả lời đúng. (B) 'invitation' liên tưởng tới 'letter'. (C) có tên người nhưng nói về việc phát biểu, lạc đề.","a":"E24-T07-11.mp3"},{"n":12,"q":"Did you read the press release?","qvi":"Bạn đã đọc thông cáo báo chí chưa?","opts":["I haven't checked my e-mail all day.","It's not raining here yet.","The switch works fine."],"vi":["Cả ngày nay tôi chưa kiểm tra e-mail.","Ở đây chưa mưa.","Công tắc hoạt động tốt."],"ans":"A","xp":"Hỏi đã đọc thông cáo báo chí chưa → (A) gián tiếp trả lời 'chưa': cả ngày chưa xem e-mail (nên chưa đọc). (B), (C) không liên quan.","a":"E24-T07-12.mp3"},{"n":13,"q":"Didn't we renew our newspaper subscription last month?","qvi":"Chẳng phải tháng trước mình đã gia hạn đặt báo rồi sao?","opts":["That photo's on the front page.","Here's the paper for your newsletter.","Yes, it was renewed for another six months."],"vi":["Bức ảnh đó ở trang nhất.","Đây là giấy cho bản tin của bạn.","Đúng vậy, đã gia hạn thêm sáu tháng."],"ans":"C","xp":"Câu hỏi phủ định xác nhận việc gia hạn đặt báo → (C) 'Yes' + gia hạn thêm 6 tháng, khớp. (A) 'front page' liên tưởng tới 'newspaper'. (B) 'paper', 'newsletter' gần âm với 'newspaper'.","a":"E24-T07-13.mp3"},{"n":14,"q":"When will we mention our budgetary needs to the outreach coordinator?","qvi":"Khi nào chúng ta sẽ nói với điều phối viên hoạt động cộng đồng về nhu cầu ngân sách?","opts":["I can't quite reach the top shelf.","We're fully funded through the end of the year.","Because our accountant is on vacation."],"vi":["Tôi không với tới kệ trên cùng.","Chúng ta đã được cấp đủ kinh phí đến cuối năm rồi.","Vì kế toán của chúng ta đang đi nghỉ."],"ans":"B","xp":"Hỏi khi nào báo nhu cầu ngân sách → (B) gián tiếp: đã đủ kinh phí đến cuối năm, nên chưa cần nói. (A) 'reach' gần âm với 'outreach'. (C) 'Because' trả lời câu hỏi Why, không phải When.","a":"E24-T07-14.mp3"},{"n":15,"q":"My appointment is with Dr. Hamdy today, right?","qvi":"Hôm nay tôi có hẹn với bác sĩ Hamdy, đúng không?","opts":["Usually an annual checkup.","No, parking is not free.","Yes, and she'll see you in a minute."],"vi":["Thường là khám sức khỏe định kỳ hằng năm.","Không, đỗ xe không miễn phí.","Vâng, và bác sĩ sẽ khám cho bạn ngay đây."],"ans":"C","xp":"Câu hỏi đuôi xác nhận lịch hẹn → (C) 'Yes' + bác sĩ sẽ gặp bạn ngay, hợp lý. (A) 'checkup' liên tưởng tới 'appointment', 'Dr.'. (B) không liên quan.","a":"E24-T07-15.mp3"},{"n":16,"q":"Where should I store this shipment of paper?","qvi":"Tôi nên cất lô giấy mới giao này ở đâu?","opts":["The store closes at four.","By express delivery.","Well, the supply room is full."],"vi":["Cửa hàng đóng cửa lúc bốn giờ.","Bằng chuyển phát nhanh.","À, phòng chứa đồ dùng đầy rồi."],"ans":"C","xp":"Hỏi cất giấy ở đâu → (C) gián tiếp cho biết phòng vật tư đã đầy (không cất ở đó được). (A) lặp từ 'store' (nghĩa khác: cửa hàng). (B) 'delivery' liên tưởng tới 'shipment'.","a":"E24-T07-16.mp3"},{"n":17,"q":"Would you be able to reschedule my haircut for Monday?","qvi":"Bạn có thể dời lịch cắt tóc của tôi sang thứ Hai được không?","opts":["No, we're fully booked that day.","I'll open a window to let in some fresh air.","The grass needs cutting."],"vi":["Không được, hôm đó kín lịch rồi.","Tôi sẽ mở cửa sổ cho thoáng khí.","Cỏ cần được cắt."],"ans":"A","xp":"Lời đề nghị dời lịch → (A) từ chối và nêu lý do: hôm đó kín lịch (fully booked). (B) 'air' gần âm với 'haircut'. (C) 'cutting' liên tưởng tới 'haircut'.","a":"E24-T07-17.mp3"},{"n":18,"q":"Should I take the train or the bus to the airport?","qvi":"Tôi nên đi tàu hay xe buýt ra sân bay?","opts":["The bus stop is five kilometers away.","There are enough for all of us.","No, I went to a training session."],"vi":["Trạm xe buýt cách đây năm cây số.","Có đủ cho tất cả chúng ta.","Không, tôi đã đi dự buổi đào tạo."],"ans":"A","xp":"Câu hỏi lựa chọn tàu hay xe buýt → (A) gián tiếp: trạm xe buýt xa 5 km, tức là nên đi tàu. (B) lạc đề. (C) câu hỏi lựa chọn không trả lời Yes/No; 'training' gần âm 'train'.","a":"E24-T07-18.mp3"},{"n":19,"q":"How long will the online course take?","qvi":"Khóa học trực tuyến sẽ mất bao lâu?","opts":["You can finish it in a few hours.","Forty dollars a month.","I'll take the blue jacket."],"vi":["Bạn có thể học xong trong vài giờ.","Bốn mươi đô la một tháng.","Tôi sẽ lấy cái áo khoác màu xanh."],"ans":"A","xp":"How long hỏi thời gian → (A) 'vài giờ là xong'. (B) trả lời giá tiền (How much). (C) lặp từ 'take' với nghĩa khác.","a":"E24-T07-19.mp3"},{"n":20,"q":"Will this month's company gathering be held in Benson Park?","qvi":"Buổi họp mặt công ty tháng này có tổ chức ở công viên Benson không?","opts":["I usually park by the fountain.","It's still cold outside most days.","Those should be printed in color."],"vi":["Tôi thường đỗ xe cạnh đài phun nước.","Ngoài trời vẫn lạnh gần như mỗi ngày.","Những cái đó nên được in màu."],"ans":"B","xp":"Hỏi buổi họp mặt có tổ chức ở công viên không → (B) gián tiếp: trời còn lạnh, ý là khó tổ chức ngoài trời. (A) lặp từ 'park' (đỗ xe). (C) không liên quan.","a":"E24-T07-20.mp3"},{"n":21,"q":"When will the tickets for the performance be ready to pick up?","qvi":"Khi nào vé xem buổi biểu diễn sẵn sàng để nhận?","opts":["We should get them by the end of the week.","A famous director.","Twenty-five euros."],"vi":["Chắc cuối tuần này là chúng ta nhận được.","Một đạo diễn nổi tiếng.","Hai mươi lăm euro."],"ans":"A","xp":"Câu hỏi When → (A) nêu thời điểm: cuối tuần. (B) 'director' liên tưởng tới 'performance'. (C) là giá tiền, trả lời How much.","a":"E24-T07-21.mp3"},{"n":22,"q":"I don't know if the packaging materials were ordered already.","qvi":"Tôi không biết vật liệu đóng gói đã được đặt mua chưa.","opts":["I saw some boxes on the loading dock.","She's wearing a red hat.","A lunch appointment at twelve thirty."],"vi":["Tôi thấy mấy thùng hàng ở khu bốc dỡ.","Cô ấy đang đội mũ đỏ.","Một cuộc hẹn ăn trưa lúc mười hai giờ ba mươi."],"ans":"A","xp":"Câu trần thuật bày tỏ không chắc vật liệu đóng gói đã đặt chưa → (A) gián tiếp: thấy thùng hàng ở khu bốc dỡ, tức là hàng có thể đã về. (B), (C) không liên quan.","a":"E24-T07-22.mp3"},{"n":23,"q":"Could you please send me the sales report?","qvi":"Bạn gửi giúp tôi bản báo cáo doanh số được không?","opts":["Fifty percent off last season's merchandise.","Of course—I'll do it now.","Did you check the weather report?"],"vi":["Giảm năm mươi phần trăm cho hàng mùa trước.","Tất nhiên rồi, tôi gửi ngay đây.","Bạn đã xem dự báo thời tiết chưa?"],"ans":"B","xp":"Lời nhờ gửi báo cáo → (B) đồng ý 'Of course' và nói sẽ làm ngay. (A) 'Fifty percent off' liên tưởng tới 'sales' (giảm giá). (C) lặp từ 'report'.","a":"E24-T07-23.mp3"},{"n":24,"q":"What type of view will your apartment have?","qvi":"Căn hộ của bạn sẽ có tầm nhìn ra cảnh gì?","opts":["The kitchen lighting looks great.","I haven't signed a lease yet.","We're in complete agreement on that."],"vi":["Đèn trong bếp trông tuyệt lắm.","Tôi chưa ký hợp đồng thuê nhà mà.","Chúng tôi hoàn toàn đồng ý về việc đó."],"ans":"B","xp":"Hỏi căn hộ nhìn ra cảnh gì → (B) gián tiếp: chưa ký hợp đồng thuê (lease) nên chưa biết. (A) 'kitchen lighting' liên tưởng tới 'apartment'. (C) 'agreement' gần âm với 'apartment'.","a":"E24-T07-24.mp3"},{"n":25,"q":"How much oil does your heater use in the winter?","qvi":"Mùa đông máy sưởi nhà bạn dùng hết bao nhiêu dầu?","opts":["We may need to stop for gas on our trip.","That recipe calls for butter.","We only use electric appliances."],"vi":["Có thể chúng ta phải dừng đổ xăng trong chuyến đi.","Công thức đó cần dùng bơ.","Nhà tôi chỉ dùng thiết bị chạy điện."],"ans":"C","xp":"Hỏi máy sưởi dùng bao nhiêu dầu → (C) gián tiếp: nhà chỉ dùng đồ điện, tức là không dùng dầu. (A) 'gas' liên tưởng tới 'heater', 'oil'. (B) 'butter' liên tưởng tới 'oil'.","a":"E24-T07-25.mp3"},{"n":26,"q":"Where can I find the vitamins?","qvi":"Tôi có thể tìm vitamin ở đâu?","opts":["In aisle six.","That's a really healthy recipe.","The library is closed on Sundays."],"vi":["Ở dãy kệ số sáu.","Đó là một công thức món ăn rất tốt cho sức khỏe.","Thư viện đóng cửa vào Chủ nhật."],"ans":"A","xp":"Câu hỏi Where → (A) chỉ vị trí cụ thể: dãy kệ (aisle) số 6. (B) 'healthy' liên tưởng tới 'vitamins'. (C) không liên quan.","a":"E24-T07-26.mp3"},{"n":27,"q":"Thank you for helping me create a survey.","qvi":"Cảm ơn bạn đã giúp tôi làm bảng khảo sát.","opts":["The software did most of the work.","Our loyal customers.","The crates are still in the warehouse."],"vi":["Phần mềm làm gần hết việc mà.","Các khách hàng thân thiết của chúng ta.","Mấy thùng hàng vẫn còn trong kho."],"ans":"A","xp":"Lời cảm ơn → (A) đáp lại khiêm tốn: phần mềm làm gần hết, mình giúp không nhiều. (B) 'loyal customers' liên tưởng tới 'survey'. (C) 'crates' gần âm với 'create'.","a":"E24-T07-27.mp3"},{"n":28,"q":"When will you be done testing the new mobile app?","qvi":"Khi nào bạn sẽ kiểm thử xong ứng dụng di động mới?","opts":["No, just an older laptop model.","I'm almost finished.","It's about a two-hour drive from here."],"vi":["Không, chỉ là một mẫu máy tính xách tay cũ hơn.","Tôi sắp xong rồi.","Từ đây lái xe mất khoảng hai tiếng."],"ans":"B","xp":"Câu hỏi When → (B) 'sắp xong rồi' cho biết sẽ hoàn thành sớm. (A) câu hỏi When không trả lời Yes/No. (C) 'two-hour drive' là quãng đường, lạc đề.","a":"E24-T07-28.mp3"},{"n":29,"q":"Don't forget to turn off the projector after your presentation.","qvi":"Nhớ tắt máy chiếu sau khi thuyết trình xong nhé.","opts":["I don't have a summary.","Should I return it to the supply closet?","Please distribute these handouts."],"vi":["Tôi không có bản tóm tắt.","Tôi có nên mang nó trả lại tủ đồ dùng không?","Vui lòng phát những tài liệu này."],"ans":"B","xp":"Lời nhắc tắt máy chiếu → (B) hỏi tiếp liên quan: có cần cất máy chiếu lại vào tủ đồ dùng không. (A) 'summary', (C) 'handouts' liên tưởng tới 'presentation' nhưng không phải câu đáp hợp lý.","a":"E24-T07-29.mp3"},{"n":30,"q":"Didn't there use to be a parking garage on this street?","qvi":"Trước đây trên con phố này có một bãi đỗ xe phải không?","opts":["Yes, but it's been torn down.","You can hang your keys on this hook.","My car has a flat tire."],"vi":["Đúng, nhưng nó bị phá dỡ rồi.","Bạn có thể treo chìa khóa lên cái móc này.","Xe tôi bị xẹp lốp."],"ans":"A","xp":"Câu hỏi phủ định xác nhận trước đây có bãi đỗ xe → (A) 'Yes' + giải thích đã bị phá dỡ (torn down). (B) không liên quan. (C) 'car' liên tưởng tới 'parking'.","a":"E24-T07-30.mp3"},{"n":31,"q":"Will you be available to work on Thursday or Friday?","qvi":"Bạn có thể đi làm vào thứ Năm hay thứ Sáu?","opts":["There's mandatory training on Friday.","Yes, it was a good show.","A daily schedule."],"vi":["Thứ Sáu có buổi đào tạo bắt buộc.","Vâng, buổi diễn hay lắm.","Một lịch trình hằng ngày."],"ans":"A","xp":"Câu hỏi lựa chọn thứ Năm hay thứ Sáu → (A) gián tiếp chọn thứ Năm vì thứ Sáu bận đào tạo bắt buộc. (B) câu hỏi lựa chọn không trả lời Yes/No. (C) 'schedule' liên tưởng tới ngày làm việc.","a":"E24-T07-31.mp3"}],"p3":[{"ns":[32,34],"script":[["W","Hi. I'm Gabriela Alvarez of Organic Easy Meals. I'm scheduled to offer some samples of our new vegetable chips to your customers from three to five P.M.","Chào anh. Tôi là Gabriela Alvarez của công ty Organic Easy Meals. Theo lịch, tôi sẽ mời khách hàng của cửa hàng dùng thử món snack rau củ mới của chúng tôi từ 3 đến 5 giờ chiều."],["M","Oh yes. Hello, Ms. Alvarez. I'm Ryan Hughes, the manager. We have a table set up for you at the end of aisle eight. That's our snacks aisle.","À vâng. Chào chị Alvarez. Tôi là Ryan Hughes, quản lý ở đây. Chúng tôi đã kê sẵn một cái bàn cho chị ở cuối dãy kệ số tám. Đó là dãy đồ ăn vặt."],["W","Thanks. I'll start bringing in food and some equipment from my truck. But first I'd like to take a look at the table I'll be using.","Cảm ơn anh. Tôi sẽ bắt đầu mang đồ ăn và một số dụng cụ từ xe tải vào. Nhưng trước tiên tôi muốn xem qua cái bàn mình sẽ dùng."],["M","Sounds good. If you'd like any help bringing in your stuff, just let me know.","Được thôi. Nếu chị cần giúp mang đồ vào thì cứ nói với tôi nhé."]],"qs":[{"n":32,"q":"What is the woman preparing to do?","qvi":"Người phụ nữ đang chuẩn bị làm gì?","opts":["Conduct an inspection","Film a cooking demonstration","Offer some product samples","Make a purchase"],"vi":["Tiến hành kiểm tra","Quay video trình diễn nấu ăn","Mời dùng thử sản phẩm mẫu","Mua hàng"],"ans":"C","xp":"Người phụ nữ nói: \"I'm scheduled to offer some samples of our new vegetable chips to your customers\" (tôi sẽ mời khách dùng thử snack rau củ mới) → 'samples of our new vegetable chips' = 'product samples'. Chọn (C)."},{"n":33,"q":"Where is the conversation most likely taking place?","qvi":"Cuộc hội thoại có lẽ diễn ra ở đâu?","opts":["At a restaurant","At a factory","At an organic farm","At a grocery store"],"vi":["Ở nhà hàng","Ở nhà máy","Ở trang trại hữu cơ","Ở cửa hàng thực phẩm"],"ans":"D","xp":"Người quản lý nói: \"We have a table set up for you at the end of aisle eight. That's our snacks aisle.\" → có dãy kệ (aisle) bán đồ ăn vặt, nên đây là cửa hàng thực phẩm/siêu thị. Chọn (D). (C) 'organic' chỉ là tên công ty của cô ấy."},{"n":34,"q":"What does the man offer to help with?","qvi":"Người đàn ông đề nghị giúp việc gì?","opts":["Scheduling an interview","Mixing some ingredients","Carrying some supplies","Assembling some equipment"],"vi":["Sắp xếp lịch phỏng vấn","Trộn nguyên liệu","Mang đồ dùng","Lắp ráp thiết bị"],"ans":"C","xp":"Người đàn ông nói: \"If you'd like any help bringing in your stuff, just let me know.\" → 'bringing in your stuff' (mang đồ vào) = 'Carrying some supplies'. Chọn (C)."}],"a":"E24-T07-32-34.mp3"},{"ns":[35,37],"script":[["W","Hello. I received a notice in the mail about a fee I need to pay because I returned some books late. My name is Ling Gao.","Chào anh. Tôi nhận được thông báo qua bưu điện về khoản phí tôi phải trả vì trả sách muộn. Tôi tên là Ling Gao."],["M","Hmm. Yes, it says here in the system that you owe ten dollars for overdue materials. Would you like to pay that now?","Ừm. Vâng, trên hệ thống ghi chị còn nợ mười đô la vì trả tài liệu quá hạn. Chị có muốn thanh toán luôn bây giờ không?"],["W","Do you take credit cards?","Ở đây có nhận thẻ tín dụng không?"],["M","We usually accept either cash or credit, but our card reader has been malfunctioning. Let me see if it's working again.","Bình thường chúng tôi nhận cả tiền mặt lẫn thẻ, nhưng máy đọc thẻ dạo này bị trục trặc. Để tôi xem nó chạy lại được chưa."]],"qs":[{"n":35,"q":"Who most likely is the man?","qvi":"Người đàn ông có lẽ là ai?","opts":["A bank teller","A librarian","A mail carrier","A truck driver"],"vi":["Giao dịch viên ngân hàng","Thủ thư","Người đưa thư","Tài xế xe tải"],"ans":"B","xp":"Người phụ nữ nói phải trả phí vì \"I returned some books late\" (trả sách muộn), người đàn ông kiểm tra hệ thống: \"you owe ten dollars for overdue materials\" → anh ấy làm ở thư viện, là thủ thư. Chọn (B)."},{"n":36,"q":"What does the woman ask about?","qvi":"Người phụ nữ hỏi về điều gì?","opts":["A method of payment","A type of delivery service","A way to fill out a form","A schedule change"],"vi":["Hình thức thanh toán","Một loại dịch vụ giao hàng","Cách điền một mẫu đơn","Thay đổi lịch trình"],"ans":"A","xp":"Người phụ nữ hỏi: \"Do you take credit cards?\" (có nhận thẻ tín dụng không) → hỏi về hình thức thanh toán. Chọn (A)."},{"n":37,"q":"What does the man say he will do?","qvi":"Người đàn ông nói anh ấy sẽ làm gì?","opts":["Look up some information","Print a document","Check on a machine","Update an account"],"vi":["Tra cứu thông tin","In một tài liệu","Kiểm tra một cái máy","Cập nhật tài khoản"],"ans":"C","xp":"Người đàn ông nói: \"our card reader has been malfunctioning. Let me see if it's working again.\" → kiểm tra máy đọc thẻ: 'see' = 'check on', 'card reader' = 'a machine'. Chọn (C)."}],"a":"E24-T07-35-37.mp3"},{"ns":[38,40],"script":[["M1","Hi, everybody. Are we ready for the sales meeting this morning?","Chào mọi người. Chúng ta đã sẵn sàng cho cuộc họp kinh doanh sáng nay chưa?"],["W","Yes, I've finished putting together my presentation.","Rồi, tôi đã chuẩn bị xong bài thuyết trình."],["M2","The meeting's in the conference room, right?","Cuộc họp ở phòng hội nghị đúng không?"],["M1","No—there's been a last-minute change. The conference room is being used by the IT department all day to interview job candidates.","Không, vừa có thay đổi vào phút chót. Phòng hội nghị bị phòng IT dùng cả ngày để phỏng vấn ứng viên."],["W","Oh no! My presentation requires the use of a television.","Ôi không! Bài thuyết trình của tôi cần dùng ti vi."],["M1","Don't worry. We're meeting in the boardroom. There's a smart TV there.","Đừng lo. Chúng ta họp ở phòng họp ban giám đốc. Ở đó có ti vi thông minh."],["M2","Is that room large enough for our team?","Phòng đó có đủ rộng cho cả nhóm mình không?"],["M1","Yes, we won't have a problem.","Có, sẽ không có vấn đề gì đâu."]],"qs":[{"n":38,"q":"What does the woman say she has finished doing?","qvi":"Người phụ nữ nói cô ấy đã làm xong việc gì?","opts":["Organizing a luncheon","Preparing some materials","Submitting a purchase order","Reviewing some résumés"],"vi":["Tổ chức bữa tiệc trưa","Chuẩn bị tài liệu","Nộp đơn đặt hàng","Xem xét hồ sơ xin việc"],"ans":"B","xp":"Người phụ nữ nói: \"I've finished putting together my presentation\" → 'putting together my presentation' (soạn bài thuyết trình) = 'Preparing some materials'. Chọn (B)."},{"n":39,"q":"Why was a change made at the last minute?","qvi":"Vì sao có sự thay đổi vào phút chót?","opts":["An area is too noisy.","Some participants are delayed.","A room was already taken.","Some revisions were requested."],"vi":["Một khu vực quá ồn.","Một số người tham dự bị trễ.","Một phòng đã có người dùng.","Có yêu cầu chỉnh sửa."],"ans":"C","xp":"\"there's been a last-minute change. The conference room is being used by the IT department all day\" → phòng hội nghị đã bị phòng IT dùng = 'A room was already taken'. Chọn (C)."},{"n":40,"q":"What is the woman concerned about?","qvi":"Người phụ nữ lo lắng về điều gì?","opts":["The security of an Internet connection","The amount of approved funding","The feedback from some colleagues","The availability of some equipment"],"vi":["Độ an toàn của kết nối Internet","Số tiền kinh phí được duyệt","Phản hồi của đồng nghiệp","Việc có sẵn thiết bị hay không"],"ans":"D","xp":"Người phụ nữ lo: \"My presentation requires the use of a television.\" và được trấn an \"Don't worry... There's a smart TV there.\" → cô lo không có ti vi để dùng = 'availability of some equipment'. Chọn (D)."}],"a":"E24-T07-38-40.mp3"},{"ns":[41,43],"script":[["M","Did you see the road construction sign at the corner? All traffic is being directed away from our street—no one can come this way!","Chị có thấy biển báo thi công đường ở góc phố không? Tất cả xe cộ đang bị chuyển hướng khỏi con phố của mình, không ai đi lối này được!"],["W","I know! How will customers visit our store to make copies and pick up photo prints?","Tôi biết! Vậy khách hàng làm sao đến cửa hàng mình để photo tài liệu và lấy ảnh in đây?"],["M","I'm afraid they'll have to park on another street. They can still access the store on foot.","Tôi e là họ sẽ phải đỗ xe ở phố khác. Họ vẫn có thể đi bộ đến cửa hàng."],["W","OK. I'll update our social media page to direct our customers.","Được rồi. Tôi sẽ cập nhật trang mạng xã hội của mình để chỉ đường cho khách."]],"qs":[{"n":41,"q":"What problem do the speakers discuss?","qvi":"Những người nói đang bàn về vấn đề gì?","opts":["A parking garage is full.","A street is closed.","Some equipment is broken.","Some items are damaged."],"vi":["Bãi đỗ xe đã đầy.","Một con phố bị đóng.","Một số thiết bị bị hỏng.","Một số món hàng bị hư hại."],"ans":"B","xp":"Người đàn ông nói: \"Did you see the road construction sign...? All traffic is being directed away from our street—no one can come this way!\" → phố bị chặn vì thi công, tức là đường bị đóng. Chọn (B)."},{"n":42,"q":"What does the man say customers will have to do?","qvi":"Người đàn ông nói khách hàng sẽ phải làm gì?","opts":["Visit an online store","Present a receipt","Park in a different area","Schedule a delivery"],"vi":["Ghé cửa hàng trực tuyến","Xuất trình hóa đơn","Đỗ xe ở khu vực khác","Hẹn lịch giao hàng"],"ans":"C","xp":"\"I'm afraid they'll have to park on another street.\" → 'park on another street' = 'Park in a different area'. Chọn (C)."},{"n":43,"q":"What will the woman do next?","qvi":"Người phụ nữ sẽ làm gì tiếp theo?","opts":["Cancel her plans for the weekend","Close the shop early","Drive slowly","Post an update on social media"],"vi":["Hủy kế hoạch cuối tuần","Đóng cửa hàng sớm","Lái xe chậm","Đăng thông tin cập nhật lên mạng xã hội"],"ans":"D","xp":"Người phụ nữ nói: \"I'll update our social media page to direct our customers.\" → cập nhật trang mạng xã hội = 'Post an update on social media'. Chọn (D)."}],"a":"E24-T07-41-43.mp3"},{"ns":[44,46],"script":[["M","It's your first day working here, so we'll spend the morning surveying the walking trails so you can get a sense of the area. While we're at it, we'll also collect soil samples from different areas of the park.","Hôm nay là ngày đầu chị làm việc ở đây, nên buổi sáng chúng ta sẽ đi khảo sát các đường mòn đi bộ để chị nắm được khu vực này. Nhân tiện, chúng ta cũng sẽ lấy mẫu đất ở nhiều khu khác nhau trong công viên."],["W","We need to test the soil samples to monitor the health of the preserve, right?","Chúng ta cần xét nghiệm mẫu đất để theo dõi tình trạng của khu bảo tồn, đúng không?"],["M","Yes. We don't have a laboratory, so we send them out for testing every month. And since it's a sunny day today, it's a good time to take photographs for our social media page.","Đúng vậy. Chúng ta không có phòng thí nghiệm nên hằng tháng phải gửi mẫu đi nơi khác xét nghiệm. Còn nữa, hôm nay trời nắng đẹp nên là dịp tốt để chụp ảnh cho trang mạng xã hội."],["W","I can do that. I brought my camera.","Việc đó để tôi làm. Tôi có mang máy ảnh theo."]],"qs":[{"n":44,"q":"Where do the speakers most likely work?","qvi":"Những người nói có lẽ làm việc ở đâu?","opts":["At a nature preserve","At a vegetable farm","At a garden supply store","At a construction site"],"vi":["Ở khu bảo tồn thiên nhiên","Ở trang trại rau","Ở cửa hàng đồ làm vườn","Ở công trường xây dựng"],"ans":"A","xp":"Họ khảo sát \"walking trails\", lấy \"soil samples from different areas of the park\" và người phụ nữ nói \"to monitor the health of the preserve\" → nơi làm việc là khu bảo tồn thiên nhiên. Chọn (A)."},{"n":45,"q":"What will the speakers do with some samples?","qvi":"Những người nói sẽ làm gì với các mẫu?","opts":["Display them in a window","Send them to a laboratory","Distribute them to customers","Donate them to a university"],"vi":["Trưng bày ở cửa sổ","Gửi đến phòng thí nghiệm","Phát cho khách hàng","Tặng cho một trường đại học"],"ans":"B","xp":"\"We don't have a laboratory, so we send them out for testing every month.\" → gửi mẫu đất ra ngoài để xét nghiệm, tức là gửi đến phòng thí nghiệm. Chọn (B)."},{"n":46,"q":"What does the woman volunteer to do?","qvi":"Người phụ nữ xung phong làm gì?","opts":["Lead a training session","Take some photographs","Order some supplies","Organize a tour"],"vi":["Dẫn một buổi đào tạo","Chụp ảnh","Đặt mua đồ dùng","Tổ chức chuyến tham quan"],"ans":"B","xp":"Người đàn ông nói \"it's a good time to take photographs for our social media page\", người phụ nữ đáp \"I can do that. I brought my camera.\" → cô ấy xung phong chụp ảnh. Chọn (B)."}],"a":"E24-T07-44-46.mp3"},{"ns":[47,49],"script":[["W","Good morning, Ivan. Everyone's talking about the flyer that was posted on our bulletin board yesterday. Have you seen it?","Chào buổi sáng, Ivan. Mọi người đang bàn tán về tờ thông báo dán trên bảng tin hôm qua. Anh xem chưa?"],["M","I was out of the office yesterday, but I've heard. Big changes are coming for all mail carriers in the city.","Hôm qua tôi không có ở văn phòng, nhưng tôi có nghe rồi. Sắp có thay đổi lớn cho tất cả nhân viên đưa thư trong thành phố."],["W","That's right. Our entire postal delivery fleet is being replaced with electric vehicles.","Đúng vậy. Toàn bộ đội xe giao bưu phẩm của mình sẽ được thay bằng xe điện."],["M","I just hope that we don't have to charge them every few hours. I'm concerned that the battery won't last through my entire route.","Tôi chỉ mong là không phải sạc xe vài tiếng một lần. Tôi lo pin sẽ không đủ cho tôi đi hết tuyến đường của mình."]],"qs":[{"n":47,"q":"Who are the speakers?","qvi":"Những người nói là ai?","opts":["Executive assistants","Maintenance supervisors","Postal workers","Food delivery drivers"],"vi":["Trợ lý điều hành","Giám sát bảo trì","Nhân viên bưu điện","Tài xế giao đồ ăn"],"ans":"C","xp":"Người phụ nữ nói \"Our entire postal delivery fleet\" (đội xe giao bưu phẩm của chúng ta), người đàn ông nhắc \"all mail carriers\" và \"my entire route\" → họ là nhân viên bưu điện. Chọn (C)."},{"n":48,"q":"What was announced in a flyer?","qvi":"Tờ thông báo đã công bố điều gì?","opts":["Some computer software will be replaced.","A building will be sold.","A route will be added.","Some vehicles will be replaced."],"vi":["Một số phần mềm máy tính sẽ được thay.","Một tòa nhà sẽ được bán.","Một tuyến đường sẽ được bổ sung.","Một số xe sẽ được thay thế."],"ans":"D","xp":"Nói về tờ thông báo (flyer), người phụ nữ cho biết: \"Our entire postal delivery fleet is being replaced with electric vehicles.\" → 'postal delivery fleet' (đội xe) = 'Some vehicles'. Chọn (D)."},{"n":49,"q":"What is the man concerned about?","qvi":"Người đàn ông lo lắng về điều gì?","opts":["How long a battery will last","How expensive a purchase will be","How accurate a weather forecast is","How current a training program is"],"vi":["Pin sẽ dùng được bao lâu","Món hàng mua sẽ đắt cỡ nào","Dự báo thời tiết chính xác đến đâu","Chương trình đào tạo cập nhật đến mức nào"],"ans":"A","xp":"\"I'm concerned that the battery won't last through my entire route.\" → lo pin không trụ được hết tuyến = lo pin dùng được bao lâu. Chọn (A)."}],"a":"E24-T07-47-49.mp3"},{"ns":[50,52],"script":[["W1","Kota, I want you to meet Claudia. Claudia is starting work today. Could you show her around and explain some of our processes?","Kota, tôi muốn giới thiệu anh với Claudia. Hôm nay Claudia bắt đầu đi làm. Anh dẫn cô ấy đi một vòng và giải thích một số quy trình của chúng ta được không?"],["M","Of course, Ms. Park. Welcome to the team, Claudia!","Tất nhiên rồi, chị Park. Chào mừng Claudia đến với nhóm!"],["W2","Thank you. I'm coming from the Silver Ridge Inn, where I also worked at the front desk.","Cảm ơn anh. Tôi chuyển từ khách sạn Silver Ridge Inn sang, ở đó tôi cũng làm lễ tân."],["M","So you already have experience with taking reservations and checking in guests?","Vậy là chị đã có kinh nghiệm nhận đặt phòng và làm thủ tục nhận phòng cho khách rồi nhỉ?"],["W2","Yes, but we used a different software system than the one I see you have here.","Vâng, nhưng chỗ cũ dùng hệ thống phần mềm khác với cái tôi thấy ở đây."],["M","It's easy to use. Let me show you how.","Nó dễ dùng lắm. Để tôi chỉ chị cách dùng."]],"qs":[{"n":50,"q":"What does Ms. Park ask the man to do?","qvi":"Bà Park nhờ người đàn ông làm gì?","opts":["Assist a new employee","Book an event","Meet with a vendor","Prepare a presentation"],"vi":["Hỗ trợ một nhân viên mới","Đặt lịch một sự kiện","Gặp một nhà cung cấp","Chuẩn bị bài thuyết trình"],"ans":"A","xp":"Bà Park nói: \"Claudia is starting work today. Could you show her around and explain some of our processes?\" → nhờ hướng dẫn nhân viên mới. Chọn (A)."},{"n":51,"q":"Where does the conversation most likely take place?","qvi":"Cuộc hội thoại có lẽ diễn ra ở đâu?","opts":["At a museum","At a technology firm","At an airport","At a hotel"],"vi":["Ở bảo tàng","Ở công ty công nghệ","Ở sân bay","Ở khách sạn"],"ans":"D","xp":"Claudia nói \"I'm coming from the Silver Ridge Inn, where I also worked at the front desk\" (chỗ cũ cũng làm lễ tân), anh Kota nhắc \"taking reservations and checking in guests\" → nơi này cũng là khách sạn. Chọn (D)."},{"n":52,"q":"What will the man do next?","qvi":"Người đàn ông sẽ làm gì tiếp theo?","opts":["Provide some feedback","Check a calendar","Demonstrate a computer program","Help a coworker find some supplies"],"vi":["Góp ý","Xem lịch","Hướng dẫn cách dùng một chương trình máy tính","Giúp đồng nghiệp tìm đồ dùng"],"ans":"C","xp":"Claudia nói \"we used a different software system...\", người đàn ông đáp \"It's easy to use. Let me show you how.\" → 'show you how' = 'Demonstrate', 'software system' = 'a computer program'. Chọn (C)."}],"a":"E24-T07-50-52.mp3"},{"ns":[53,55],"script":[["W1","Wow. I didn't expect this restaurant to be so popular—look at all the people waiting to be seated.","Chà. Tôi không ngờ nhà hàng này lại đông khách thế, nhìn bao nhiêu người đang chờ chỗ ngồi kìa."],["W2","I know. It's brand-new—I didn't think anyone knew about it yet. Looks like we won't be able to get a table for a while.","Đúng thật. Nó mới mở mà, tôi tưởng chưa ai biết đến. Có vẻ phải một lúc nữa mình mới có bàn."],["W1","Well, we don't have much time. We need to drive back to the office to train our interns at one o'clock. Should we go somewhere else?","Mà mình không có nhiều thời gian. Mình phải lái xe về văn phòng để đào tạo thực tập sinh lúc một giờ. Hay mình đi chỗ khác nhé?"],["W2","Let's see if they offer takeout—we can just order something to go.","Để xem họ có bán mang về không, mình gọi món mang đi là được."],["W1","Good idea. I'm looking forward to trying the spicy noodles!","Ý hay đấy. Tôi rất muốn thử món mì cay!"]],"qs":[{"n":53,"q":"What do the speakers find surprising about a restaurant?","qvi":"Những người nói thấy ngạc nhiên về điều gì ở nhà hàng?","opts":["Its prices","Its popularity","Its menu options","Its decor"],"vi":["Giá cả","Mức độ đông khách","Các lựa chọn trong thực đơn","Cách trang trí"],"ans":"B","xp":"Người phụ nữ thứ nhất nói: \"I didn't expect this restaurant to be so popular\" và người kia đồng ý \"I know.\" → ngạc nhiên vì nhà hàng đông khách. Chọn (B)."},{"n":54,"q":"Why are the speakers in a hurry?","qvi":"Vì sao những người nói đang vội?","opts":["They need to catch a train.","They will be conducting an interview.","They will be leading a training session.","A business is about to close."],"vi":["Họ cần bắt tàu.","Họ sẽ tiến hành một cuộc phỏng vấn.","Họ sẽ dẫn một buổi đào tạo.","Một cửa hàng sắp đóng cửa."],"ans":"C","xp":"\"we don't have much time. We need to drive back to the office to train our interns at one o'clock\" → 'train our interns' = 'leading a training session'. Chọn (C)."},{"n":55,"q":"What will the speakers most likely do next?","qvi":"Những người nói có lẽ sẽ làm gì tiếp theo?","opts":["Go to another restaurant","Try a free sample","Order food to go","Pay a bill"],"vi":["Đi nhà hàng khác","Ăn thử miễn phí","Gọi đồ ăn mang đi","Thanh toán hóa đơn"],"ans":"C","xp":"Người phụ nữ thứ hai đề nghị \"we can just order something to go\", người kia đáp \"Good idea.\" → họ sẽ gọi đồ mang đi. Chọn (C)."}],"a":"E24-T07-53-55.mp3"},{"ns":[56,58],"script":[["W","Hi, Ahmed. Did you see the e-mail from management?","Chào Ahmed. Anh xem e-mail của ban quản lý chưa?"],["M","I just got here to teach my aerobics class.","Tôi vừa mới đến để dạy lớp thể dục nhịp điệu (aerobic) của tôi."],["W","It looks like the gym is opening another facility just a few miles from here. I'm surprised they want to open another location so close by.","Có vẻ phòng tập sắp mở thêm một cơ sở nữa chỉ cách đây vài dặm. Tôi ngạc nhiên là họ lại muốn mở chi nhánh gần như vậy."],["M","Well, this is a densely populated area.","À, khu này dân cư đông đúc mà."],["W","True. I guess they'll have to hire more employees. There's just not enough of us to staff both locations.","Đúng thế. Chắc họ sẽ phải tuyển thêm nhân viên. Chúng ta không đủ người để làm ở cả hai cơ sở."]],"qs":[{"n":56,"q":"Where do the speakers most likely work?","qvi":"Những người nói có lẽ làm việc ở đâu?","opts":["At a sporting goods store","At a campground","At a footwear factory","At a fitness center"],"vi":["Ở cửa hàng đồ thể thao","Ở khu cắm trại","Ở nhà máy giày dép","Ở trung tâm thể dục thể hình"],"ans":"D","xp":"Người đàn ông \"just got here to teach my aerobics class\", người phụ nữ nói \"the gym is opening another facility\" → 'the gym' = 'a fitness center'. Chọn (D)."},{"n":57,"q":"Why does the man say, \"this is a densely populated area\"?","qvi":"Tại sao người đàn ông nói \"this is a densely populated area\" (khu này dân cư đông đúc)?","opts":["To complain that traffic is heavy","To suggest changes in regulations","To explain a decision","To request a review of property values"],"vi":["Để phàn nàn giao thông đông đúc","Để đề xuất thay đổi quy định","Để giải thích một quyết định","Để yêu cầu xem xét lại giá trị bất động sản"],"ans":"C","xp":"Người phụ nữ ngạc nhiên: \"I'm surprised they want to open another location so close by.\" Người đàn ông đáp khu này đông dân → anh ấy giải thích lý do hợp lý cho quyết định mở thêm cơ sở gần đó của ban quản lý. Chọn (C)."},{"n":58,"q":"What does the woman think a business should do?","qvi":"Người phụ nữ nghĩ doanh nghiệp nên làm gì?","opts":["Hire more employees","Place a large order","Revise an employee handbook","Advertise on social media"],"vi":["Tuyển thêm nhân viên","Đặt một đơn hàng lớn","Sửa đổi sổ tay nhân viên","Quảng cáo trên mạng xã hội"],"ans":"A","xp":"\"I guess they'll have to hire more employees.\" → chọn (A)."}],"a":"E24-T07-56-58.mp3"},{"ns":[59,61],"script":[["W","Marcel, I'd like to plan a team-building event with our graphic design group.","Marcel, tôi muốn lên kế hoạch tổ chức một sự kiện gắn kết đội nhóm với nhóm thiết kế đồ họa của chúng ta."],["M","Sure. We could reserve the conference room upstairs.","Được chứ. Mình có thể đặt phòng hội nghị trên lầu."],["W","But the event wouldn't be just for on-site graphic designers. Nearly a third of our staff will be participating remotely.","Nhưng sự kiện không chỉ dành cho các nhà thiết kế làm việc tại chỗ. Gần một phần ba nhân viên của mình sẽ tham gia từ xa."],["M","Oh, you're right. Everyone needs to feel equally included. Let's have our on-site staff join the event from their desks.","À, chị nói đúng. Ai cũng cần cảm thấy được tham gia như nhau. Vậy hãy để nhân viên tại chỗ tham gia sự kiện ngay từ bàn làm việc của họ."],["W","OK. I'll do a search for effective team-building activities that we can do online.","Được. Tôi sẽ tìm các hoạt động gắn kết đội nhóm hiệu quả có thể làm trực tuyến."]],"qs":[{"n":59,"q":"What is the conversation about?","qvi":"Cuộc hội thoại nói về điều gì?","opts":["Organizing an event","Preparing for a renovation","Updating some software","Selecting a caterer"],"vi":["Tổ chức một sự kiện","Chuẩn bị cho việc cải tạo","Cập nhật phần mềm","Chọn đơn vị cung cấp đồ ăn"],"ans":"A","xp":"Người phụ nữ mở đầu: \"I'd like to plan a team-building event with our graphic design group.\" và cả hai bàn cách tổ chức → chủ đề là tổ chức sự kiện. Chọn (A)."},{"n":60,"q":"What does the woman imply when she says, \"Nearly a third of our staff will be participating remotely\"?","qvi":"Người phụ nữ ngụ ý gì khi nói \"Nearly a third of our staff will be participating remotely\" (gần một phần ba nhân viên sẽ tham gia từ xa)?","opts":["Travel expenses should be refunded.","Some workers may feel excluded.","A venue is not the correct size.","A workshop should be postponed."],"vi":["Chi phí đi lại nên được hoàn trả.","Một số nhân viên có thể cảm thấy bị bỏ rơi.","Địa điểm không đúng kích cỡ.","Một buổi hội thảo nên bị hoãn lại."],"ans":"B","xp":"Sau câu này người đàn ông đáp: \"you're right. Everyone needs to feel equally included.\" → ý cô ấy là nếu tổ chức ở phòng họp thì những người làm từ xa có thể cảm thấy bị loại ra (excluded). Chọn (B)."},{"n":61,"q":"What will the woman do next?","qvi":"Người phụ nữ sẽ làm gì tiếp theo?","opts":["Review an agenda","Reserve an event space","Research some online activities","Check a budget"],"vi":["Xem lại chương trình nghị sự","Đặt chỗ tổ chức sự kiện","Tìm hiểu một số hoạt động trực tuyến","Kiểm tra ngân sách"],"ans":"C","xp":"\"I'll do a search for effective team-building activities that we can do online.\" → 'do a search' = 'Research'. Chọn (C)."}],"a":"E24-T07-59-61.mp3"},{"ns":[62,64],"script":[["M","Hi. I'm calling because I saw some coffee tables on your department store's Web site. I'd like to see them in person. Can you tell me if you have the same furniture selection in your store?","Chào chị. Tôi gọi vì thấy mấy cái bàn cà phê trên trang web của cửa hàng bách hóa bên chị. Tôi muốn xem tận mắt. Chị cho tôi hỏi cửa hàng có các mẫu đồ nội thất giống như trên web không?"],["W","Yes, we do. We're fully stocked at the moment, so you'll be able to see everything that's on our online catalog.","Có ạ. Hiện tại hàng đang đầy đủ, nên anh sẽ xem được mọi thứ có trong danh mục trực tuyến."],["M","OK. One more thing. I use a wheelchair, and I'm concerned about navigating your store.","Được. Còn một điều nữa. Tôi dùng xe lăn, nên tôi lo việc di chuyển trong cửa hàng."],["W","Oh, that's not a problem. We have large elevators that can easily accommodate a wheelchair.","Ồ, không vấn đề gì ạ. Chúng tôi có thang máy lớn, xe lăn vào dễ dàng."],["M","Great. Thanks for the information. I'll stop by later this afternoon.","Tuyệt. Cảm ơn chị đã cho biết. Chiều nay tôi sẽ ghé qua."]],"qs":[{"n":62,"q":"Look at the graphic. Which floor will the man visit?","qvi":"Nhìn vào bảng. Người đàn ông sẽ đến tầng nào?","opts":["Floor 1","Floor 2","Floor 3","Floor 4"],"vi":["Tầng 1","Tầng 2","Tầng 3","Tầng 4"],"ans":"C","xp":"Người đàn ông muốn xem bàn cà phê: \"Can you tell me if you have the same furniture selection in your store?\" → cần đến khu đồ nội thất (Furniture). Theo bảng, Furniture ở tầng 3. Chọn (C)."},{"n":63,"q":"Why is the man calling the store?","qvi":"Tại sao người đàn ông gọi điện đến cửa hàng?","opts":["To complain about receiving a faulty product","To point out an error in an invoice","To ask about seeing some merchandise","To request delivery of a catalog"],"vi":["Để phàn nàn về việc nhận được sản phẩm lỗi","Để chỉ ra lỗi trong hóa đơn","Để hỏi về việc xem một số hàng hóa","Để yêu cầu gửi một cuốn danh mục sản phẩm"],"ans":"C","xp":"Người đàn ông nói: \"I saw some coffee tables on your department store's Web site. I'd like to see them in person. Can you tell me if you have the same furniture selection in your store?\" → hỏi để đến xem tận mắt hàng → 'coffee tables' = 'some merchandise'. Chọn (C)."},{"n":64,"q":"What does the woman assure the man about?","qvi":"Người phụ nữ cam đoan với người đàn ông về điều gì?","opts":["An online payment system is secure.","A building is wheelchair accessible.","A product is eligible for a refund.","A food court is open daily."],"vi":["Hệ thống thanh toán trực tuyến an toàn.","Tòa nhà có lối đi cho xe lăn.","Sản phẩm đủ điều kiện được hoàn tiền.","Khu ẩm thực mở cửa hằng ngày."],"ans":"B","xp":"Người đàn ông lo: \"I use a wheelchair, and I'm concerned about navigating your store.\" Người phụ nữ trấn an: \"that's not a problem. We have large elevators that can easily accommodate a wheelchair.\" → tòa nhà thuận tiện cho người đi xe lăn. Chọn (B)."}],"a":"E24-T07-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["W","Adam, our Kyoto office just called. Our investors want me to present a project update there as soon as possible. Can you get me on the first flight to Kyoto tomorrow morning?","Adam, văn phòng Kyoto vừa gọi. Các nhà đầu tư muốn tôi đến đó trình bày tiến độ dự án càng sớm càng tốt. Anh đặt giúp tôi chuyến bay đầu tiên đi Kyoto sáng mai được không?"],["M","Let me check. Per company policy, we can only use Blue Jet airlines for international travel—and unfortunately, that flight's not the first one out tomorrow.","Để tôi kiểm tra. Theo quy định của công ty, đi công tác nước ngoài chỉ được dùng hãng Blue Jet, mà tiếc là chuyến của hãng đó không phải chuyến sớm nhất ngày mai."],["W","That will have to do, thanks. And I'll need a ride to the airport too. Can you arrange that?","Vậy cũng được, cảm ơn anh. Tôi cũng cần xe đưa ra sân bay nữa. Anh sắp xếp giúp được không?"],["M","Sure thing. I'll finalize the reservations and e-mail you the details.","Được chứ. Tôi sẽ chốt các đặt chỗ và gửi e-mail chi tiết cho chị."]],"qs":[{"n":65,"q":"Why does the woman need to go to Kyoto?","qvi":"Tại sao người phụ nữ cần đi Kyoto?","opts":["To attend a conference","To sign a contract","To find investors","To report on a project"],"vi":["Để dự hội nghị","Để ký hợp đồng","Để tìm nhà đầu tư","Để báo cáo về một dự án"],"ans":"D","xp":"\"Our investors want me to present a project update there as soon as possible.\" → 'present a project update' (trình bày tiến độ dự án) = 'report on a project'. Chọn (D). (C) sai vì nhà đầu tư đã có sẵn."},{"n":66,"q":"Look at the graphic. What time will the woman depart for Kyoto?","qvi":"Nhìn vào bảng. Người phụ nữ sẽ khởi hành đi Kyoto lúc mấy giờ?","opts":["At 6:02 A.M.","At 8:15 A.M.","At 9:07 A.M.","At 10:20 A.M."],"vi":["Lúc 6:02 sáng","Lúc 8:15 sáng","Lúc 9:07 sáng","Lúc 10:20 sáng"],"ans":"C","xp":"\"Per company policy, we can only use Blue Jet airlines for international travel\" → cô ấy phải bay hãng Blue Jet. Theo bảng, Blue Jet khởi hành lúc 9:07 A.M. Chọn (C)."},{"n":67,"q":"What does the man say he will do?","qvi":"Người đàn ông nói anh ấy sẽ làm gì?","opts":["Drive the woman to the airport","Reserve a hotel","E-mail some information","Print out a boarding pass"],"vi":["Lái xe đưa người phụ nữ ra sân bay","Đặt khách sạn","Gửi e-mail một số thông tin","In thẻ lên máy bay"],"ans":"C","xp":"\"I'll finalize the reservations and e-mail you the details.\" → 'e-mail you the details' = 'E-mail some information'. Chọn (C). (A) anh ấy chỉ sắp xếp xe, không tự lái."}],"a":"E24-T07-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["M","Hi, Astrid. For tonight's six o'clock news broadcast, the lead story is going to be on the rumor that the Beavers' football team is going to build a stadium. Have you heard about the project?","Chào Astrid. Bản tin 6 giờ tối nay, tin chính sẽ là tin đồn đội bóng Beavers sắp xây sân vận động. Chị có nghe về dự án đó chưa?"],["W","My sources have confirmed the story, actually. I've just gained exclusive access to some bidding proposals. Four cities are competing for the project.","Thật ra các nguồn tin của tôi đã xác nhận chuyện đó rồi. Tôi vừa được tiếp cận độc quyền một số hồ sơ dự thầu. Có bốn thành phố đang cạnh tranh giành dự án này."],["M","It's great you were able to confirm this before we went on the air. Do you know where the new stadium might be built?","Thật tuyệt là chị xác nhận được tin này trước khi mình lên sóng. Chị có biết sân vận động mới có thể được xây ở đâu không?"],["W","Well, one document suggests that Columbia City's proposal is the favorite. However, the team does have three other bids to consider.","À, một tài liệu cho thấy đề xuất của Columbia City đang được ưu ái nhất. Tuy nhiên, đội bóng vẫn còn ba hồ sơ khác để cân nhắc."]],"qs":[{"n":68,"q":"Who most likely are the speakers?","qvi":"Những người nói có lẽ là ai?","opts":["Architects","Government officials","News reporters","Contractors"],"vi":["Kiến trúc sư","Quan chức chính phủ","Phóng viên tin tức","Nhà thầu"],"ans":"C","xp":"Người đàn ông nói \"For tonight's six o'clock news broadcast, the lead story is...\" và \"before we went on the air\"; người phụ nữ nhắc \"My sources\" → họ là phóng viên. Chọn (C)."},{"n":69,"q":"What does the woman say she had access to?","qvi":"Người phụ nữ nói cô ấy đã được tiếp cận cái gì?","opts":["Uniform designs","Sporting event tickets","A company vehicle","Bid proposals"],"vi":["Mẫu thiết kế đồng phục","Vé sự kiện thể thao","Xe của công ty","Hồ sơ dự thầu"],"ans":"D","xp":"\"I've just gained exclusive access to some bidding proposals.\" → 'bidding proposals' = 'Bid proposals'. Chọn (D)."},{"n":70,"q":"Look at the graphic. According to the woman, where will a stadium most likely be located?","qvi":"Nhìn vào bản đồ. Theo người phụ nữ, sân vận động nhiều khả năng sẽ nằm ở đâu?","opts":["At site A","At site B","At site C","At site D"],"vi":["Ở khu A","Ở khu B","Ở khu C","Ở khu D"],"ans":"C","xp":"\"one document suggests that Columbia City's proposal is the favorite\" → Columbia City được ưu ái nhất. Trên bản đồ, Columbia City là khu C (A: Duncanville, B: Princeford Creek, D: Springfield). Chọn (C)."}],"a":"E24-T07-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Are you interested in learning how to start your own business? Winston Community College is the place for you! Last month, we opened a new campus in Cedarview that offers lots of business courses to equip aspiring entrepreneurs with the tools to launch a new career. We offer flexible schedules so you can take courses in the evenings or on weekends. Visit us at our new campus or online to submit your application.","Bạn có muốn học cách tự khởi nghiệp kinh doanh không? Trường Cao đẳng Cộng đồng Winston chính là nơi dành cho bạn! Tháng trước, chúng tôi đã mở cơ sở mới ở Cedarview với rất nhiều khóa học kinh doanh, trang bị cho những người muốn khởi nghiệp các công cụ để bắt đầu một sự nghiệp mới. Chúng tôi có lịch học linh hoạt để bạn có thể học vào buổi tối hoặc cuối tuần. Hãy đến cơ sở mới của chúng tôi hoặc truy cập trực tuyến để nộp đơn đăng ký."]],"qs":[{"n":71,"q":"What is being advertised?","qvi":"Điều gì đang được quảng cáo?","opts":["An accounting firm","A real estate office","A trucking company","A community college"],"vi":["Một công ty kế toán","Một văn phòng bất động sản","Một công ty vận tải bằng xe tải","Một trường cao đẳng cộng đồng"],"ans":"D","xp":"Mở đầu: \"Are you interested in learning how to start your own business? Winston Community College is the place for you!\" → đang quảng cáo trường cao đẳng cộng đồng. Chọn (D)."},{"n":72,"q":"What happened last month?","qvi":"Tháng trước đã có chuyện gì?","opts":["A Web site was launched.","A company merger was finalized.","A new location was opened.","A new director was hired."],"vi":["Một trang web được ra mắt.","Một vụ sáp nhập công ty được hoàn tất.","Một cơ sở mới được khai trương.","Một giám đốc mới được tuyển."],"ans":"C","xp":"\"Last month, we opened a new campus in Cedarview\" → 'opened a new campus' = 'A new location was opened'. Chọn (C)."},{"n":73,"q":"What are the listeners invited to do?","qvi":"Người nghe được mời làm gì?","opts":["Join an online group","Participate in a study","Attend a workshop","Submit an application"],"vi":["Tham gia một nhóm trực tuyến","Tham gia một nghiên cứu","Dự một buổi hội thảo","Nộp đơn đăng ký"],"ans":"D","xp":"Câu cuối: \"Visit us at our new campus or online to submit your application.\" → mời nộp đơn. Chọn (D)."}],"a":"E24-T07-71-73.mp3"},{"ns":[74,76],"script":[["","Please be sure to mark your calendars for a get-together on April sixteenth. We all work on different biochemistry research projects, and it's nice to share and celebrate our progress. Sung-Hee has reserved us rooms at a conference center off-site where we'll be able to relax outdoors after our sessions. Thanks for taking care of that, Sung-Hee. A few of you have asked whether we can hold other social events throughout the year. We don't have the budget to do anything big, but I'd like to hear your ideas. Everyone has my e-mail address.","Mọi người nhớ đánh dấu lịch cho buổi họp mặt vào ngày 16 tháng Tư nhé. Chúng ta đều làm các dự án nghiên cứu hóa sinh khác nhau, nên thật vui khi được chia sẻ và ăn mừng những tiến bộ của mình. Sung-Hee đã đặt cho chúng ta các phòng ở một trung tâm hội nghị bên ngoài công ty, nơi chúng ta có thể thư giãn ngoài trời sau các phiên làm việc. Cảm ơn Sung-Hee đã lo việc đó. Một vài bạn đã hỏi liệu chúng ta có thể tổ chức các hoạt động giao lưu khác trong năm không. Chúng ta không có ngân sách để làm gì lớn, nhưng tôi muốn nghe ý tưởng của các bạn. Ai cũng có địa chỉ e-mail của tôi mà."]],"qs":[{"n":74,"q":"What is scheduled for April 16?","qvi":"Ngày 16 tháng 4 có lịch gì?","opts":["An awards banquet","A software demonstration","A company celebration","A national holiday"],"vi":["Tiệc trao giải","Buổi trình diễn phần mềm","Một buổi liên hoan của công ty","Ngày lễ quốc gia"],"ans":"C","xp":"\"mark your calendars for a get-together on April sixteenth... it's nice to share and celebrate our progress\" → buổi họp mặt để ăn mừng tiến bộ = 'A company celebration'. Chọn (C)."},{"n":75,"q":"What does the speaker thank Sung-Hee for doing?","qvi":"Người nói cảm ơn Sung-Hee vì đã làm gì?","opts":["Presenting her research","Approving a budget","E-mailing an agenda","Reserving some space"],"vi":["Trình bày nghiên cứu của cô ấy","Phê duyệt ngân sách","Gửi e-mail chương trình nghị sự","Đặt chỗ/địa điểm"],"ans":"D","xp":"\"Sung-Hee has reserved us rooms at a conference center off-site... Thanks for taking care of that, Sung-Hee.\" → 'reserved us rooms' = 'Reserving some space'. Chọn (D)."},{"n":76,"q":"Why does the speaker say, \"Everyone has my e-mail address\"?","qvi":"Tại sao người nói nói \"Everyone has my e-mail address\" (ai cũng có địa chỉ e-mail của tôi)?","opts":["To discourage the listeners from calling his phone","To complain that he receives too many e-mails","To explain how he learned about an opportunity","To encourage the listeners to make suggestions"],"vi":["Để khuyên người nghe đừng gọi điện cho anh ấy","Để phàn nàn rằng anh ấy nhận quá nhiều e-mail","Để giải thích anh ấy biết về một cơ hội như thế nào","Để khuyến khích người nghe đóng góp ý kiến"],"ans":"D","xp":"Ngay trước đó: \"A few of you have asked whether we can hold other social events... I'd like to hear your ideas.\" → nhắc ai cũng có e-mail của mình để khuyến khích mọi người gửi ý tưởng. Chọn (D)."}],"a":"E24-T07-74-76.mp3"},{"ns":[77,79],"script":[["","My name is Raul Phillips. I know it's short notice, but I'm a patient at your clinic, and I'd like to see a doctor today. I ran in a local half-marathon yesterday, and, well, I didn't feel pain at the time, but I think I sprained my ankle during the race. It's been sore since after the race, and I might need an x-ray. Could you call me back? I'll be conducting some job interviews this morning, so I may not be able to answer my phone, but please leave a message. My number is 555-0167. Thanks!","Tôi tên là Raul Phillips. Tôi biết là báo hơi gấp, nhưng tôi là bệnh nhân của phòng khám và tôi muốn được gặp bác sĩ hôm nay. Hôm qua tôi chạy một giải bán marathon ở địa phương, và lúc đó tôi không thấy đau, nhưng tôi nghĩ mình đã bị bong gân mắt cá chân trong lúc chạy. Từ sau cuộc đua nó cứ đau nhức, có lẽ tôi cần chụp X-quang. Phòng khám gọi lại cho tôi được không? Sáng nay tôi sẽ phỏng vấn tuyển dụng nên có thể không nghe máy được, nhưng xin cứ để lại lời nhắn. Số của tôi là 555-0167. Cảm ơn!"]],"qs":[{"n":77,"q":"Why is the speaker calling?","qvi":"Tại sao người nói gọi điện?","opts":["To obtain a copy of his medical records","To express interest in a job","To complain about a service","To request an appointment"],"vi":["Để xin bản sao hồ sơ bệnh án","Để bày tỏ mong muốn ứng tuyển một công việc","Để phàn nàn về dịch vụ","Để xin một cuộc hẹn khám"],"ans":"D","xp":"\"I'm a patient at your clinic, and I'd like to see a doctor today.\" → 'see a doctor' = xin hẹn khám. Chọn (D)."},{"n":78,"q":"What event did the speaker recently participate in?","qvi":"Gần đây người nói đã tham gia sự kiện gì?","opts":["An art festival","An athletic competition","A career fair","A walking tour"],"vi":["Một lễ hội nghệ thuật","Một cuộc thi thể thao","Một hội chợ việc làm","Một chuyến tham quan đi bộ"],"ans":"B","xp":"\"I ran in a local half-marathon yesterday\" → 'half-marathon' (bán marathon) là một cuộc thi thể thao = 'An athletic competition'. Chọn (B)."},{"n":79,"q":"What does the speaker say he will be doing this morning?","qvi":"Người nói cho biết sáng nay anh ấy sẽ làm gì?","opts":["Picking up supplies","Holding interviews","Giving a demonstration","Touring a facility"],"vi":["Đi lấy đồ dùng","Tổ chức phỏng vấn","Trình diễn/hướng dẫn","Tham quan một cơ sở"],"ans":"B","xp":"\"I'll be conducting some job interviews this morning\" → 'conducting job interviews' = 'Holding interviews'. Chọn (B)."}],"a":"E24-T07-77-79.mp3"},{"ns":[80,82],"script":[["","This is Giovanni calling from Salazar Market. We're excited about selling your breakfast cereal in our store. Our customers have been asking for your brand for several months now. I'll be e-mailing you a contract later today. You can sign it and send it back to me at your convenience. It states that we'll be displaying your cereals at the end of an aisle, on the endcap, as you requested. You'll want to make sure we have enough boxes in the store to create a nice display and keep the shelves well stocked for you.","Tôi là Giovanni gọi từ siêu thị Salazar Market. Chúng tôi rất hào hứng được bán ngũ cốc ăn sáng của quý công ty tại cửa hàng. Mấy tháng nay khách hàng của chúng tôi liên tục hỏi mua nhãn hàng của quý vị. Chiều nay tôi sẽ gửi e-mail hợp đồng cho anh/chị. Anh/chị có thể ký và gửi lại cho tôi khi nào tiện. Hợp đồng ghi rõ chúng tôi sẽ trưng bày ngũ cốc của quý vị ở đầu dãy kệ, đúng như yêu cầu. Anh/chị nên đảm bảo cửa hàng có đủ số hộp để trưng bày đẹp mắt và giữ cho kệ luôn đầy hàng."]],"qs":[{"n":80,"q":"What does the listener produce?","qvi":"Người nghe sản xuất mặt hàng gì?","opts":["Furniture","Electronics","Food","Vehicles"],"vi":["Đồ nội thất","Đồ điện tử","Thực phẩm","Xe cộ"],"ans":"C","xp":"\"We're excited about selling your breakfast cereal in our store.\" → người nghe sản xuất ngũ cốc ăn sáng (breakfast cereal) = thực phẩm. Chọn (C)."},{"n":81,"q":"What does the speaker say he will send the listener?","qvi":"Người nói cho biết anh ấy sẽ gửi cho người nghe cái gì?","opts":["A contract","A delivery schedule","Some display ideas","Some coupons"],"vi":["Một bản hợp đồng","Lịch giao hàng","Một số ý tưởng trưng bày","Một số phiếu giảm giá"],"ans":"A","xp":"\"I'll be e-mailing you a contract later today.\" → gửi hợp đồng. Chọn (A)."},{"n":82,"q":"What does the speaker recommend doing?","qvi":"Người nói khuyên nên làm gì?","opts":["Lowering a price","Advertising in a newspaper","Developing new flavors","Sending plenty of inventory"],"vi":["Giảm giá","Quảng cáo trên báo","Phát triển hương vị mới","Gửi nhiều hàng"],"ans":"D","xp":"\"You'll want to make sure we have enough boxes in the store to create a nice display and keep the shelves well stocked\" → khuyên gửi đủ nhiều hàng = 'Sending plenty of inventory'. Chọn (D)."}],"a":"E24-T07-80-82.mp3"},{"ns":[83,85],"script":[["","Team, let's debrief on the trial run of the DQY-5, our satellite Internet system. As you know, the DQY-5 is a small satellite dish that can be used to access the Internet in remote locations. Test users have said that it generally works very well. However, they all report service interruptions when winter storms cover the satellite dish in snow. That means we need to focus on designing an internal system that can heat up the satellite receiver and melt the snow to ensure that the connection is not disrupted. Let's break into groups of three and start brainstorming technical solutions.","Cả nhóm, chúng ta cùng tổng kết đợt chạy thử DQY-5, hệ thống Internet vệ tinh của chúng ta. Như mọi người biết, DQY-5 là một chảo thu vệ tinh cỡ nhỏ có thể dùng để truy cập Internet ở những vùng xa xôi. Người dùng thử cho biết nhìn chung nó hoạt động rất tốt. Tuy nhiên, tất cả đều báo bị gián đoạn dịch vụ khi bão mùa đông phủ tuyết lên chảo thu. Điều đó có nghĩa là chúng ta cần tập trung thiết kế một hệ thống bên trong có thể làm nóng bộ thu vệ tinh và làm tan tuyết để đảm bảo kết nối không bị gián đoạn. Chúng ta hãy chia thành các nhóm ba người và bắt đầu cùng đưa ra các giải pháp kỹ thuật."]],"qs":[{"n":83,"q":"What type of product has the team developed?","qvi":"Nhóm đã phát triển loại sản phẩm gì?","opts":["A robot for household tasks","A mobile application for weather updates","A satellite dish for Internet access","A smartwatch for fitness tracking"],"vi":["Rô-bốt làm việc nhà","Ứng dụng di động cập nhật thời tiết","Chảo thu vệ tinh để truy cập Internet","Đồng hồ thông minh theo dõi luyện tập"],"ans":"C","xp":"\"the DQY-5 is a small satellite dish that can be used to access the Internet in remote locations\" → sản phẩm là chảo thu vệ tinh để truy cập Internet. Chọn (C)."},{"n":84,"q":"What has caused a problem for some users?","qvi":"Điều gì đã gây ra vấn đề cho một số người dùng?","opts":["Limited screen options","A short battery life","Unclear instructions","Poor weather conditions"],"vi":["Lựa chọn màn hình hạn chế","Thời lượng pin ngắn","Hướng dẫn không rõ ràng","Thời tiết xấu"],"ans":"D","xp":"\"they all report service interruptions when winter storms cover the satellite dish in snow\" → 'winter storms' (bão mùa đông) = 'Poor weather conditions'. Chọn (D)."},{"n":85,"q":"What will the listeners most likely do next?","qvi":"Người nghe có lẽ sẽ làm gì tiếp theo?","opts":["Take a break","Work in small groups","Visit a production facility","Take some measurements"],"vi":["Nghỉ giải lao","Làm việc theo nhóm nhỏ","Tham quan cơ sở sản xuất","Đo đạc"],"ans":"B","xp":"\"Let's break into groups of three and start brainstorming technical solutions.\" → chia nhóm ba người = 'Work in small groups'. Chọn (B)."}],"a":"E24-T07-83-85.mp3"},{"ns":[86,88],"script":[["","Thanks for joining us for this evening's community orchestra performance. The concert was scheduled to begin at eight P.M. Unfortunately, some of the microphones aren't working. So while our sound engineers are correcting the issue, I'd like to tell you about an opportunity to help the theater. You may notice that all our ushers are volunteers, and we're always looking for more. Ushers take tickets, help patrons find their seats, and then, of course, get to enjoy the concert for free. If you're interested, be sure to check page four of your program booklet for more details.","Cảm ơn quý vị đã đến xem buổi biểu diễn của dàn nhạc cộng đồng tối nay. Buổi hòa nhạc dự kiến bắt đầu lúc 8 giờ tối. Thật không may, một số micro đang không hoạt động. Vì vậy, trong lúc các kỹ thuật viên âm thanh khắc phục sự cố, tôi xin giới thiệu với quý vị một cơ hội để giúp đỡ nhà hát. Có thể quý vị đã để ý rằng tất cả nhân viên hướng dẫn chỗ ngồi của chúng tôi đều là tình nguyện viên, và chúng tôi luôn cần thêm người. Nhân viên hướng dẫn sẽ soát vé, giúp khán giả tìm chỗ ngồi, và tất nhiên là được thưởng thức buổi hòa nhạc miễn phí. Nếu quý vị quan tâm, vui lòng xem trang 4 của cuốn chương trình để biết thêm chi tiết."]],"qs":[{"n":86,"q":"Why does the speaker say, \"Unfortunately, some of the microphones aren't working\"?","qvi":"Tại sao người nói nói \"Unfortunately, some of the microphones aren't working\" (thật không may, một số micro không hoạt động)?","opts":["To suggest purchasing new equipment","To recommend changing a venue","To ask the listeners to remain silent","To apologize for a delay"],"vi":["Để đề xuất mua thiết bị mới","Để đề nghị đổi địa điểm","Để yêu cầu người nghe giữ im lặng","Để xin lỗi vì sự chậm trễ"],"ans":"D","xp":"Trước đó: \"The concert was scheduled to begin at eight P.M.\", sau đó: \"while our sound engineers are correcting the issue...\" → buổi diễn chưa thể bắt đầu đúng giờ, người nói đang xin lỗi vì sự chậm trễ. Chọn (D)."},{"n":87,"q":"What are the listeners invited to do?","qvi":"Người nghe được mời làm gì?","opts":["Upgrade their tickets","Become volunteers","Participate in a contest","Ask the performers some questions"],"vi":["Nâng hạng vé","Trở thành tình nguyện viên","Tham gia một cuộc thi","Đặt câu hỏi cho các nghệ sĩ"],"ans":"B","xp":"\"all our ushers are volunteers, and we're always looking for more\" → mời người nghe làm tình nguyện viên. Chọn (B)."},{"n":88,"q":"Where does the speaker say some information can be found?","qvi":"Người nói cho biết có thể tìm thông tin ở đâu?","opts":["On a posted sign","At the box office","In a program booklet","On a Web site"],"vi":["Trên biển thông báo","Ở quầy bán vé","Trong cuốn chương trình","Trên trang web"],"ans":"C","xp":"\"be sure to check page four of your program booklet for more details\" → thông tin ở cuốn chương trình. Chọn (C)."}],"a":"E24-T07-86-88.mp3"},{"ns":[89,91],"script":[["","I'm Natalie from Akroy Technologies, and I'm here to train everyone on using System Ace, your new project management software. Since you organize and provide a venue for professional conferences and trade shows, System Ace will allow you to create separate project folders for each event. This means that event-related to-do lists, schedules, and other documents for each folder will all be in one place. Now—the best way to learn a new program is by using it. So please, get out your tablet or laptop. We're going to try a few things together.","Tôi là Natalie đến từ Akroy Technologies, và tôi ở đây để hướng dẫn mọi người sử dụng System Ace, phần mềm quản lý dự án mới của quý vị. Vì quý vị tổ chức và cung cấp địa điểm cho các hội nghị chuyên ngành và hội chợ thương mại, System Ace sẽ cho phép quý vị tạo thư mục dự án riêng cho từng sự kiện. Nghĩa là danh sách việc cần làm, lịch trình và các tài liệu khác liên quan đến từng sự kiện sẽ nằm gọn ở một chỗ. Nào, cách tốt nhất để học một chương trình mới là dùng nó. Vậy mời mọi người lấy máy tính bảng hoặc máy tính xách tay ra. Chúng ta sẽ cùng thử vài thao tác."]],"qs":[{"n":89,"q":"What is the focus of the training?","qvi":"Buổi đào tạo tập trung vào điều gì?","opts":["Using some software","Processing customer complaints","Securing sensitive documents","Creating advertisements"],"vi":["Sử dụng một phần mềm","Xử lý khiếu nại của khách hàng","Bảo mật tài liệu nhạy cảm","Làm quảng cáo"],"ans":"A","xp":"\"I'm here to train everyone on using System Ace, your new project management software.\" → đào tạo cách dùng phần mềm. Chọn (A)."},{"n":90,"q":"Where do the listeners most likely work?","qvi":"Người nghe có lẽ làm việc ở đâu?","opts":["At a conference center","At a factory","At a warehouse","At a department store"],"vi":["Ở trung tâm hội nghị","Ở nhà máy","Ở nhà kho","Ở cửa hàng bách hóa"],"ans":"A","xp":"\"Since you organize and provide a venue for professional conferences and trade shows\" → người nghe tổ chức và cho thuê địa điểm hội nghị, hội chợ → làm ở trung tâm hội nghị. Chọn (A)."},{"n":91,"q":"What does the speaker ask the listeners to do?","qvi":"Người nói yêu cầu người nghe làm gì?","opts":["Create an account","Open a manual","Fill out a form","Take out an electronic device"],"vi":["Tạo tài khoản","Mở sách hướng dẫn","Điền vào mẫu đơn","Lấy thiết bị điện tử ra"],"ans":"D","xp":"\"So please, get out your tablet or laptop.\" → 'tablet or laptop' = 'an electronic device', 'get out' = 'take out'. Chọn (D)."}],"a":"E24-T07-89-91.mp3"},{"ns":[92,94],"script":[["","In this online session, I'd like to discuss how small businesses like those represented here today can be more energy efficient. For example, some companies install solar panels to reduce their electricity costs. Now, we all have different ideas about how to conserve energy. What does your company do to reduce its carbon footprint? There's a lot of combined knowledge at this meeting. Let's take advantage of that. Please submit your questions and comments in the chat. By the way, this session is being recorded so that it's available to all participants after the session.","Trong buổi trực tuyến này, tôi muốn bàn về cách các doanh nghiệp nhỏ như những đơn vị có mặt hôm nay có thể sử dụng năng lượng hiệu quả hơn. Ví dụ, một số công ty lắp tấm pin mặt trời để giảm chi phí tiền điện. Chúng ta mỗi người đều có những ý tưởng khác nhau về cách tiết kiệm năng lượng. Công ty của bạn làm gì để giảm lượng khí thải carbon? Cuộc họp này quy tụ rất nhiều kiến thức. Hãy tận dụng điều đó. Vui lòng gửi câu hỏi và ý kiến vào khung chat. Nhân tiện, buổi này đang được ghi hình để tất cả người tham dự có thể xem lại sau khi kết thúc."]],"qs":[{"n":92,"q":"What is the topic of the talk?","qvi":"Chủ đề của bài nói là gì?","opts":["Customer satisfaction","Career development","Energy efficiency","Time management"],"vi":["Sự hài lòng của khách hàng","Phát triển sự nghiệp","Hiệu quả sử dụng năng lượng","Quản lý thời gian"],"ans":"C","xp":"\"I'd like to discuss how small businesses... can be more energy efficient\" → chủ đề là sử dụng năng lượng hiệu quả. Chọn (C)."},{"n":93,"q":"Why does the speaker say, \"There's a lot of combined knowledge at this meeting\"?","qvi":"Tại sao người nói nói \"There's a lot of combined knowledge at this meeting\" (cuộc họp này quy tụ rất nhiều kiến thức)?","opts":["To encourage participation","To indicate an agenda change","To stress the importance of leadership","To correct a misconception"],"vi":["Để khuyến khích mọi người tham gia","Để báo thay đổi chương trình","Để nhấn mạnh tầm quan trọng của khả năng lãnh đạo","Để sửa một hiểu lầm"],"ans":"A","xp":"Người nói vừa hỏi \"What does your company do to reduce its carbon footprint?\", rồi nói câu này và tiếp \"Let's take advantage of that. Please submit your questions and comments in the chat.\" → khuyến khích người nghe chia sẻ, tham gia. Chọn (A)."},{"n":94,"q":"What does the speaker say will happen after the talk?","qvi":"Người nói cho biết điều gì sẽ diễn ra sau bài nói?","opts":["Refreshments will be served.","Payment will be collected.","A group photograph will be taken.","A recording will be shared."],"vi":["Đồ ăn nhẹ sẽ được phục vụ.","Sẽ thu tiền.","Sẽ chụp ảnh tập thể.","Bản ghi hình sẽ được chia sẻ."],"ans":"D","xp":"\"this session is being recorded so that it's available to all participants after the session\" → bản ghi sẽ được chia sẻ cho mọi người sau buổi. Chọn (D)."}],"a":"E24-T07-92-94.mp3"},{"ns":[95,97],"script":[["","Thanks for coming to this weekly briefing. As you know, Joe's Trucking Company takes safety very seriously, and I'm glad all our drivers are able to attend today. So we have five loads to deliver, including two loads of steel beams. Yasushi, you've been assigned to the car carrier, so please be sure to follow the safety checklist, especially the part about securely fastening all restraints. Junko, I'm concerned the lumber you're carrying will be considered oversize. I think the company will need to obtain a permit for you—we'll talk after the meeting.","Cảm ơn mọi người đã đến buổi họp giao ban hằng tuần. Như mọi người biết, Công ty Vận tải Joe's rất coi trọng an toàn, và tôi rất vui vì hôm nay tất cả tài xế đều có mặt. Chúng ta có năm chuyến hàng cần giao, trong đó có hai chuyến dầm thép. Yasushi, anh được phân công lái xe chở ô tô, nên nhớ làm đúng theo danh mục kiểm tra an toàn, nhất là phần cố định chắc chắn tất cả dây chằng. Junko, tôi lo là lô gỗ chị chở sẽ bị coi là quá khổ. Tôi nghĩ công ty sẽ phải xin giấy phép cho chị, chúng ta sẽ nói chuyện sau cuộc họp."]],"qs":[{"n":95,"q":"Who most likely are the listeners?","qvi":"Người nghe có lẽ là ai?","opts":["Warehouse supervisors","Construction workers","Safety inspectors","Truck drivers"],"vi":["Giám sát kho","Công nhân xây dựng","Thanh tra an toàn","Tài xế xe tải"],"ans":"D","xp":"\"Joe's Trucking Company takes safety very seriously, and I'm glad all our drivers are able to attend today\" → người nghe là tài xế của công ty vận tải xe tải. Chọn (D)."},{"n":96,"q":"What does the speaker remind Yasushi to do?","qvi":"Người nói nhắc Yasushi làm gì?","opts":["Park in a different location","Follow a checklist","Contact a customer","Check a schedule"],"vi":["Đỗ xe ở chỗ khác","Làm theo danh mục kiểm tra","Liên lạc với khách hàng","Kiểm tra lịch trình"],"ans":"B","xp":"\"Yasushi, you've been assigned to the car carrier, so please be sure to follow the safety checklist\" → nhắc làm theo danh mục kiểm tra an toàn. Chọn (B)."},{"n":97,"q":"Look at the graphic. Which load length is the speaker concerned about?","qvi":"Nhìn vào bảng. Người nói lo lắng về chiều dài lô hàng nào?","opts":["10 meters","13 meters","20 meters","25 meters"],"vi":["10 mét","13 mét","20 mét","25 mét"],"ans":"C","xp":"\"Junko, I'm concerned the lumber you're carrying will be considered oversize.\" → lo về lô gỗ (Lumber). Theo bảng, Lumber dài 20 meters. Chọn (C)."}],"a":"E24-T07-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","Welcome to the evening news program on WXNL Radio. In local news, the much-anticipated holiday parade will be held downtown this Saturday, beginning promptly at ten A.M. on Main Street. However, according to the city government's Web site, there's been one important change. The parade was supposed to follow a route along five city roads, but because of traffic concerns, the parade will now stop at the end of Curtis Avenue instead of continuing to the originally planned end point. Now, in case you're wondering whether we'll have sunny skies or clouds on the day of the parade, stay tuned after the commercial break for our weekend forecast.","Chào mừng quý vị đến với chương trình thời sự buổi tối của đài WXNL Radio. Tin địa phương, cuộc diễu hành mừng lễ được mong chờ từ lâu sẽ diễn ra ở trung tâm thành phố vào thứ Bảy này, bắt đầu đúng 10 giờ sáng trên phố Main. Tuy nhiên, theo trang web của chính quyền thành phố, có một thay đổi quan trọng. Theo kế hoạch, đoàn diễu hành sẽ đi qua năm con đường của thành phố, nhưng vì lo ngại về giao thông, giờ đây đoàn sẽ dừng ở cuối đại lộ Curtis thay vì tiếp tục đến điểm kết thúc như dự định ban đầu. Còn nếu quý vị đang thắc mắc ngày diễu hành trời sẽ nắng hay nhiều mây, xin đừng chuyển kênh, sau giờ quảng cáo sẽ là bản tin dự báo thời tiết cuối tuần."]],"qs":[{"n":98,"q":"What will begin at 10 A.M. on Saturday?","qvi":"Điều gì sẽ bắt đầu lúc 10 giờ sáng thứ Bảy?","opts":["A holiday parade","A bicycle race","A new bus route","Some road construction"],"vi":["Một cuộc diễu hành mừng lễ","Một cuộc đua xe đạp","Một tuyến xe buýt mới","Việc thi công đường"],"ans":"A","xp":"\"the much-anticipated holiday parade will be held downtown this Saturday, beginning promptly at ten A.M.\" → chọn (A)."},{"n":99,"q":"Look at the graphic. Which road will be excluded?","qvi":"Nhìn vào bản đồ. Con đường nào sẽ bị loại khỏi lộ trình?","opts":["Oak Street","Lake Drive","Curtis Avenue","Broad Street"],"vi":["Phố Oak","Đường Lake","Đại lộ Curtis","Phố Broad"],"ans":"D","xp":"\"the parade will now stop at the end of Curtis Avenue instead of continuing to the originally planned end point\" → đoàn dừng ở cuối Curtis Avenue. Trên bản đồ, đoạn đường sau Curtis Avenue dẫn đến điểm End là Broad Street → Broad Street bị bỏ. Chọn (D)."},{"n":100,"q":"What will the listeners hear after a commercial break?","qvi":"Người nghe sẽ nghe gì sau giờ quảng cáo?","opts":["A financial report","A weather forecast","An interview with a government official","A live musical performance"],"vi":["Bản tin tài chính","Bản tin dự báo thời tiết","Cuộc phỏng vấn một quan chức chính phủ","Một buổi biểu diễn âm nhạc trực tiếp"],"ans":"B","xp":"\"stay tuned after the commercial break for our weekend forecast\" → 'weekend forecast' = 'A weather forecast'. Chọn (B)."}],"a":"E24-T07-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"Passengers must keep ------- boarding passes and luggage with them at all times.","opts":["their","his","my","our"],"ans":"A","xp":"Đại từ sở hữu: chủ ngữ là 'Passengers' (số nhiều, ngôi thứ ba) và phía sau có 'with them' → cần tính từ sở hữu tương ứng là 'their'. (B) his = của anh ấy, (C) my = của tôi, (D) our = của chúng tôi – không khớp với 'Passengers'.\nDịch: Hành khách phải luôn giữ thẻ lên máy bay và hành lý của mình bên người."},{"n":102,"q":"The company's policy allows business travel by ------- train and airplane.","opts":["both","either","further","hardly"],"ans":"A","xp":"Cặp liên từ: thấy 'and' phía sau → 'both A and B' (cả A và B). (B) either đi với 'or' (either A or B). (C) further = xa hơn/thêm nữa, (D) hardly = hầu như không – không tạo cấu trúc với 'and'.\nDịch: Chính sách của công ty cho phép đi công tác bằng cả tàu hỏa và máy bay."},{"n":103,"q":"The production technicians are ------- for maintaining our factory equipment.","opts":["responsibly","responsible","responsibility","responsibilities"],"ans":"B","xp":"Từ loại: sau động từ 'are' cần tính từ làm vị ngữ; cụm cố định 'be responsible for' = chịu trách nhiệm về. (A) responsibly là trạng từ, (C)(D) responsibility/responsibilities là danh từ ('trách nhiệm') – không hợp nghĩa với chủ ngữ chỉ người.\nDịch: Các kỹ thuật viên sản xuất chịu trách nhiệm bảo trì thiết bị nhà máy của chúng tôi."},{"n":104,"q":"The team found Ms. Dietrich's advice on managing office staff to be especially -------.","opts":["helpful","thankful","regular","extra"],"ans":"A","xp":"Từ vựng: 'find + O + (to be) + tính từ' = thấy cái gì như thế nào. Lời khuyên (advice) thì 'helpful' = hữu ích → chọn (A). (B) thankful = biết ơn (dùng cho người), (C) regular = đều đặn/thường xuyên, (D) extra = thêm, phụ.\nDịch: Nhóm thấy lời khuyên của bà Dietrich về việc quản lý nhân viên văn phòng đặc biệt hữu ích."},{"n":105,"q":"The film crew ------- in Namibia earlier this week to prepare for the promotional tourism campaign.","opts":["to arrive","having arrived","arrived","arriving"],"ans":"C","xp":"Động từ chính & thì: câu thiếu động từ chính cho chủ ngữ 'The film crew', có 'earlier this week' (đầu tuần này – đã xảy ra) → quá khứ đơn 'arrived'. (A) to arrive, (B) having arrived, (D) arriving đều không phải động từ chia, không làm động từ chính được.\nDịch: Đoàn làm phim đã đến Namibia hồi đầu tuần này để chuẩn bị cho chiến dịch quảng bá du lịch."},{"n":106,"q":"The committee expects to be finished with the negotiations ------- 4:00 P.M.","opts":["over","until","on","by"],"ans":"D","xp":"Giới từ chỉ thời gian: 'be finished … by 4:00 P.M.' = xong trước/chậm nhất lúc 4 giờ chiều (hạn chót, hành động hoàn tất một lần). (B) until = cho đến khi (dùng cho hành động kéo dài liên tục, ví dụ 'work until 4'), không hợp với 'be finished'. (A) over = qua/trong suốt, (C) on dùng cho ngày (on Monday).\nDịch: Ủy ban dự kiến sẽ hoàn tất các cuộc đàm phán trước 4 giờ chiều."},{"n":107,"q":"United Medical Board is an ------- panel of physicians that makes recommendations for hospital improvements.","opts":["expertise","expert","expertness","expertly"],"ans":"B","xp":"Từ loại: giữa mạo từ 'an' và danh từ 'panel' cần từ bổ nghĩa → 'expert' (dùng như tính từ: gồm chuyên gia, chuyên môn). 'an expert panel' = hội đồng chuyên gia. (A) expertise là danh từ 'chuyên môn', (C) expertness là danh từ ít dùng, (D) expertly là trạng từ.\nDịch: United Medical Board là một hội đồng chuyên gia gồm các bác sĩ, chuyên đưa ra khuyến nghị để cải thiện bệnh viện."},{"n":108,"q":"Digital payments are ------- accepted at all Southern Coach bus stations.","opts":["tightly","far","after","now"],"ans":"D","xp":"Trạng từ (từ vựng): chen giữa 'are' và 'accepted' cần trạng từ hợp nghĩa → 'now' = giờ đây, hiện nay (thanh toán điện tử nay đã được chấp nhận). (A) tightly = chặt chẽ, (B) far = xa/nhiều, (C) after = sau đó – không hợp nghĩa.\nDịch: Thanh toán điện tử hiện đã được chấp nhận tại tất cả các bến xe buýt Southern Coach."},{"n":109,"q":"The fund-raising event for the library was successful, ------- the author's reading was canceled.","opts":["seldom","though","rarely","secondly"],"ans":"B","xp":"Liên từ: chỗ trống nối hai mệnh đề ('… was successful' và 'the author's reading was canceled') với ý trái ngược (thành công dù bị hủy một phần) → 'though' = mặc dù. (A) seldom và (C) rarely = hiếm khi, (D) secondly = thứ hai là – đều là trạng từ, không nối mệnh đề.\nDịch: Sự kiện gây quỹ cho thư viện đã thành công, mặc dù buổi đọc sách của tác giả bị hủy."},{"n":110,"q":"To ------- the status of your delivery, select the Track Order option in the drop-down menu.","opts":["place","want","check","look"],"ans":"C","xp":"Từ vựng: 'check the status' = kiểm tra tình trạng (đơn giao hàng), hợp với 'Track Order' (theo dõi đơn hàng). (A) place = đặt (place an order = đặt hàng), (B) want = muốn, (D) look là nội động từ, phải có giới từ (look at) mới có tân ngữ.\nDịch: Để kiểm tra tình trạng giao hàng của bạn, hãy chọn mục Track Order (Theo dõi đơn hàng) trong menu thả xuống."},{"n":111,"q":"Our project-based mentoring approach enables executives with limited time ------- junior staff.","opts":["to counsel","should counsel","counseling","counseled"],"ans":"A","xp":"Cấu trúc: 'enable + O + to V' = giúp/cho phép ai làm gì. O là 'executives with limited time' → cần 'to counsel'. (B) should counsel là động từ chia, (C) counseling, (D) counseled sai cấu trúc.\nDịch: Phương pháp cố vấn theo dự án của chúng tôi giúp các giám đốc dù ít thời gian vẫn có thể hướng dẫn nhân viên cấp dưới."},{"n":112,"q":"Mr. Yerkes is updating our quarterly sales ------- after receiving the final report from the Boston office.","opts":["measures","grounds","instructions","figures"],"ans":"D","xp":"Từ vựng: 'sales figures' = số liệu doanh số; cập nhật số liệu quý sau khi nhận báo cáo cuối cùng. (A) measures = biện pháp/thước đo, (B) grounds = căn cứ/khu đất, (C) instructions = hướng dẫn.\nDịch: Ông Yerkes đang cập nhật số liệu doanh số hàng quý của chúng ta sau khi nhận được báo cáo cuối cùng từ văn phòng Boston."},{"n":113,"q":"------- up your desk with beautiful paper products from Norimi Stationery.","opts":["Brightens","Brighten","Brightened","Brightening"],"ans":"B","xp":"Câu mệnh lệnh: câu không có chủ ngữ, mang tính mời gọi (quảng cáo) → dùng động từ nguyên mẫu đứng đầu câu: 'Brighten up' = làm sáng sủa, tươi tắn lên. (A) có -s, (C) quá khứ, (D) V-ing đều không làm câu mệnh lệnh được.\nDịch: Hãy làm bàn làm việc của bạn tươi sáng hơn với những sản phẩm giấy xinh đẹp từ Norimi Stationery."},{"n":114,"q":"Ultitemp, an application that allows users to ------- room temperature remotely, is currently available only in Asia.","opts":["control","impose","announce","encourage"],"ans":"A","xp":"Từ vựng: ứng dụng cho phép người dùng 'control room temperature remotely' = điều khiển nhiệt độ phòng từ xa. (B) impose = áp đặt, (C) announce = thông báo, (D) encourage = khuyến khích.\nDịch: Ultitemp, một ứng dụng cho phép người dùng điều khiển nhiệt độ phòng từ xa, hiện chỉ có mặt ở châu Á."},{"n":115,"q":"------- the cost of travel, the cost of attending the conference is reasonable.","opts":["Along","Even if","Aside from","Because"],"ans":"C","xp":"Giới từ/liên từ: sau chỗ trống là cụm danh từ 'the cost of travel' (không phải mệnh đề) → loại (B) Even if và (D) Because (liên từ, cần mệnh đề). 'Aside from' = ngoài … ra/không tính … → ngoài chi phí đi lại, chi phí dự hội nghị là hợp lý. (A) Along = dọc theo – không hợp nghĩa.\nDịch: Ngoài chi phí đi lại ra, chi phí tham dự hội nghị là hợp lý."},{"n":116,"q":"Customers are ------- anticipating the latest model pickup truck from Askio Automobiles.","opts":["eagerly","sharply","voluntarily","rapidly"],"ans":"A","xp":"Từ vựng (trạng từ): 'eagerly anticipating' = háo hức mong chờ – kết hợp rất thường gặp. (B) sharply = mạnh, đột ngột, (C) voluntarily = tự nguyện, (D) rapidly = nhanh chóng.\nDịch: Khách hàng đang háo hức mong chờ mẫu xe bán tải mới nhất của Askio Automobiles."},{"n":117,"q":"Once you have Mr. Garcia's -------, please post the job listing to the usual Web sites.","opts":["approve","approves","approval","approving"],"ans":"C","xp":"Từ loại: sau sở hữu cách 'Mr. Garcia's' cần danh từ → 'approval' = sự chấp thuận. (A) approve, (B) approves là động từ, (D) approving là V-ing.\nDịch: Khi đã có sự chấp thuận của ông Garcia, vui lòng đăng tin tuyển dụng lên các trang web quen thuộc."},{"n":118,"q":"Dabby's Restaurant broadened its customer base by making ------- changes to its menu.","opts":["extensive","precious","commercial","accurate"],"ans":"A","xp":"Từ vựng: 'make extensive changes' = thay đổi sâu rộng/nhiều → nhờ vậy mở rộng tệp khách hàng. (B) precious = quý giá, (C) commercial = thuộc thương mại, (D) accurate = chính xác.\nDịch: Nhà hàng Dabby's đã mở rộng lượng khách hàng nhờ thay đổi thực đơn một cách sâu rộng."},{"n":119,"q":"The redesigned intersection ------- shortens the street-crossing distance for pedestrians, making it safer.","opts":["effectively","effects","effective","effected"],"ans":"A","xp":"Từ loại: giữa chủ ngữ 'The redesigned intersection' và động từ chính 'shortens' cần trạng từ → 'effectively' = một cách hiệu quả. (B) effects là danh từ/động từ, (C) effective là tính từ, (D) effected là động từ quá khứ.\nDịch: Giao lộ được thiết kế lại đã rút ngắn hiệu quả quãng đường băng qua đường cho người đi bộ, giúp an toàn hơn."},{"n":120,"q":"Workshop attendees are asked to ------- from asking questions until the end of the formal presentation.","opts":["refrain","forbid","retreat","hesitate"],"ans":"A","xp":"Từ vựng: 'refrain from V-ing' = kiềm chế, không làm gì → được yêu cầu không đặt câu hỏi cho đến cuối bài trình bày. (B) forbid = cấm (forbid sb from doing, cần tân ngữ người), (C) retreat = rút lui, (D) hesitate = do dự (hesitate to V).\nDịch: Người tham dự hội thảo được đề nghị không đặt câu hỏi cho đến khi kết thúc phần trình bày chính thức."},{"n":121,"q":"The Tamano Foundation accepts grant ------- related to a wide range of scientific research.","opts":["proposes","proposed","proposals","proposing"],"ans":"C","xp":"Từ loại: sau động từ 'accepts' cần tân ngữ là danh từ; 'grant proposals' = các đề xuất xin tài trợ (danh từ ghép). (A) proposes là động từ, (B) proposed là quá khứ/phân từ, (D) proposing là V-ing.\nDịch: Quỹ Tamano tiếp nhận các đề xuất xin tài trợ liên quan đến nhiều lĩnh vực nghiên cứu khoa học."},{"n":122,"q":"Gateway Electronics will cancel any orders that have not been picked up ------- five days.","opts":["about","during","within","from"],"ans":"C","xp":"Giới từ: 'within five days' = trong vòng 5 ngày (giới hạn thời gian). (A) about = khoảng/về, (B) during đi với danh từ chỉ khoảng thời gian/sự kiện (during the meeting), không đi với số lượng ngày như thế này, (D) from = từ.\nDịch: Gateway Electronics sẽ hủy mọi đơn hàng không được nhận trong vòng năm ngày."},{"n":123,"q":"------- who arrives at the company parking garage after 10:00 A.M. must contact security for an access code.","opts":["Each","Those","Everything","Anyone"],"ans":"D","xp":"Đại từ: chỗ trống làm chủ ngữ, theo sau là 'who arrives' (động từ số ít) và chỉ người → 'Anyone who…' = bất kỳ ai. (B) Those who đi với động từ số nhiều (arrive). (A) Each thường đi 'each of' hoặc 'each + danh từ', không đi trực tiếp với 'who'. (C) Everything chỉ vật.\nDịch: Bất kỳ ai đến bãi đỗ xe của công ty sau 10 giờ sáng đều phải liên hệ bảo vệ để lấy mã ra vào."},{"n":124,"q":"To get to the conference room, turn left ------- after passing the employee cafeteria.","opts":["immediately","recently","originally","lately"],"ans":"A","xp":"Từ vựng (trạng từ): 'immediately after' = ngay sau khi. (B) recently, (D) lately = gần đây (dùng với thì hoàn thành/quá khứ), (C) originally = ban đầu – không hợp câu chỉ đường.\nDịch: Để đến phòng hội nghị, hãy rẽ trái ngay sau khi đi qua căng-tin nhân viên."},{"n":125,"q":"The wellness ------- at Trayer Media Group directly led to greater employee satisfaction with the company.","opts":["initiate","initiator","initiated","initiative"],"ans":"D","xp":"Từ loại & nghĩa: sau 'The wellness' cần danh từ làm chủ ngữ (danh từ ghép). 'wellness initiative' = sáng kiến/chương trình chăm sóc sức khỏe – vật dẫn đến sự hài lòng. (B) initiator = người khởi xướng (không hợp 'wellness'), (A) initiate là động từ, (C) initiated là quá khứ.\nDịch: Chương trình chăm sóc sức khỏe tại Tập đoàn Truyền thông Trayer đã trực tiếp làm tăng mức độ hài lòng của nhân viên với công ty."},{"n":126,"q":"We will keep producing our signature shoe designs ------- there is demand for them.","opts":["or else","as long as","as well as","in between"],"ans":"B","xp":"Liên từ: nối hai mệnh đề với nghĩa điều kiện → 'as long as' = miễn là, chừng nào còn. (A) or else = nếu không thì, (C) as well as = cũng như (nối danh từ/cụm từ), (D) in between = ở giữa.\nDịch: Chúng tôi sẽ tiếp tục sản xuất những mẫu giày đặc trưng của mình chừng nào còn có nhu cầu."},{"n":127,"q":"Regular applications of fertilizer improve seedling health and ------- enhance the growth of leafy vegetables.","opts":["drama","dramatic","dramatically","dramatize"],"ans":"C","xp":"Từ loại: chỗ trống đứng trước động từ 'enhance' (song song với 'improve') → cần trạng từ bổ nghĩa cho động từ: 'dramatically' = đáng kể, mạnh mẽ. (A) drama là danh từ, (B) dramatic là tính từ, (D) dramatize là động từ.\nDịch: Bón phân thường xuyên giúp cây con khỏe mạnh hơn và thúc đẩy đáng kể sự phát triển của các loại rau ăn lá."},{"n":128,"q":"Wantner Manufacturing received this year's Top Employer Award in ------- of its people-centered workplace environment.","opts":["service","accordance","recognition","dedication"],"ans":"C","xp":"Cụm cố định: 'in recognition of' = để ghi nhận/công nhận (thành tích) – rất hợp với việc nhận giải thưởng. (A) in service of = phục vụ cho, (B) in accordance with = phù hợp với (đi với 'with', không phải 'of'), (D) dedication = sự cống hiến (không có cụm 'in dedication of' với nghĩa này).\nDịch: Wantner Manufacturing đã nhận Giải thưởng Nhà tuyển dụng hàng đầu năm nay để ghi nhận môi trường làm việc lấy con người làm trung tâm của công ty."},{"n":129,"q":"The editor noted some ------- content and marked the text to be deleted.","opts":["repetition","repetitious","repetitiously","repetitiousness"],"ans":"B","xp":"Từ loại: trước danh từ 'content' cần tính từ → 'repetitious' = lặp đi lặp lại, trùng lặp. (A) repetition và (D) repetitiousness là danh từ, (C) repetitiously là trạng từ.\nDịch: Biên tập viên phát hiện một số nội dung bị lặp lại và đánh dấu đoạn văn cần xóa."},{"n":130,"q":"Bay City Zoo members get ------- access to members-only activities, such as after-hours guided tours.","opts":["exclusive","unknown","creative","previous"],"ans":"A","xp":"Từ vựng: 'exclusive access' = quyền tiếp cận dành riêng – khớp với 'members-only activities' (hoạt động chỉ dành cho hội viên). (B) unknown = không ai biết, (C) creative = sáng tạo, (D) previous = trước đó.\nDịch: Hội viên Sở thú Bay City được quyền tham gia riêng các hoạt động chỉ dành cho hội viên, chẳng hạn như các tour có hướng dẫn sau giờ mở cửa."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Naomi Richter &lt;naomirichter@mailcurrent.com&gt;</p><p><b>From:</b> Watanu Sakamoto &lt;wsakamoto@RHNimports.com&gt;</p><p><b>Date:</b> 23 November</p><p><b>Subject:</b> Follow-up</p><p><b>Attachment:</b> Logistics coordinator description</p></div><p>Dear Ms. Richter,</p><p>Thank you for coming to our office to interview for the assistant import manager position last week. We were impressed with your credentials and enthusiasm. <span class=\"blank\" data-n=\"131\">-------</span> we are moving ahead with another candidate, we would like to offer you a different position that just became available: logistics coordinator.</p><p><span class=\"blank\" data-n=\"132\">-------</span>. The attached document contains the detailed job description and pay rate. This <span class=\"blank\" data-n=\"133\">-------</span> has not yet been posted publicly. If you are <span class=\"blank\" data-n=\"134\">-------</span>, please let me know by the end of this week.</p><p>Sincerely,</p><p>Watanu Sakamoto<br>Human Resource Manager, RHN Imports</p>","vi":"Đến: Naomi Richter <naomirichter@mailcurrent.com>\nTừ: Watanu Sakamoto <wsakamoto@RHNimports.com>\nNgày: 23 tháng 11\nTiêu đề: Thư tiếp theo\nTệp đính kèm: Mô tả vị trí điều phối viên hậu cần\n\nChị Richter thân mến,\n\nCảm ơn chị đã đến văn phòng chúng tôi phỏng vấn cho vị trí trợ lý quản lý nhập khẩu vào tuần trước. Chúng tôi rất ấn tượng với trình độ và sự nhiệt tình của chị. Mặc dù chúng tôi đã quyết định chọn một ứng viên khác, chúng tôi muốn mời chị nhận một vị trí khác vừa mới trống: điều phối viên hậu cần.\n\nKinh nghiệm và bộ kỹ năng của chị khiến chị rất phù hợp. Tài liệu đính kèm có mô tả công việc chi tiết và mức lương. Cơ hội này chưa được đăng tuyển công khai. Nếu chị quan tâm, vui lòng cho tôi biết trước cuối tuần này.\n\nTrân trọng,\n\nWatanu Sakamoto\nTrưởng phòng Nhân sự, RHN Imports","qs":[{"n":131,"opts":["Rather","Although","Similarly","Consequently"],"ans":"B","xp":"Liên từ: chỗ trống đứng đầu mệnh đề 'we are moving ahead with another candidate', sau dấu phẩy là mệnh đề chính 'we would like to offer you…' → cần liên từ nối hai mệnh đề. Hai ý trái ngược (chọn người khác nhưng vẫn mời chị vị trí khác) → 'Although' = mặc dù. (A) Rather = đúng hơn là, (C) Similarly = tương tự, (D) Consequently = do đó – đều là trạng từ, không nối được hai mệnh đề.\nDịch: Mặc dù chúng tôi đã chọn một ứng viên khác, chúng tôi muốn mời chị một vị trí khác vừa trống."},{"n":132,"opts":["There are several other internal applicants.","Unfortunately, the position is no longer available.","My assistant will schedule your second interview.","Your experience and skill set make you a great fit."],"ans":"D","xp":"Điền câu: câu trước vừa mời chị Richter vị trí logistics coordinator; câu sau nói tài liệu đính kèm có mô tả công việc. Câu (D) 'Kinh nghiệm và kỹ năng của chị khiến chị rất phù hợp' giải thích lý do mời và nối tự nhiên. (A) có nhiều ứng viên nội bộ khác – mâu thuẫn với lời mời; (B) vị trí không còn – mâu thuẫn ('just became available'); (C) phỏng vấn vòng hai – không được nhắc, thư chỉ yêu cầu chị trả lời nếu quan tâm.\n(A) Có vài ứng viên nội bộ khác.\n(B) Rất tiếc, vị trí này không còn trống nữa.\n(C) Trợ lý của tôi sẽ sắp xếp buổi phỏng vấn thứ hai của chị.\n(D) Kinh nghiệm và bộ kỹ năng của chị khiến chị rất phù hợp."},{"n":133,"opts":["opportunity","authorization","application","capacity"],"ans":"A","xp":"Từ vựng: 'This ------- has not yet been posted publicly' – thứ chưa được đăng công khai chính là vị trí việc làm đang được mời → 'opportunity' = cơ hội (việc làm). (B) authorization = sự cho phép, (C) application = đơn ứng tuyển (là của ứng viên, không 'đăng công khai'), (D) capacity = sức chứa/năng lực.\nDịch: Cơ hội này chưa được đăng tuyển công khai."},{"n":134,"opts":["interest","interests","interested","interesting"],"ans":"C","xp":"Từ loại: sau 'you are' cần tính từ. Chỉ cảm xúc của người → dùng V-ed: 'interested' = quan tâm. (D) interesting = thú vị (tính chất của sự vật) – 'you are interesting' sai nghĩa. (A)(B) là danh từ/động từ.\nDịch: Nếu chị quan tâm, vui lòng cho tôi biết trước cuối tuần này."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following notice.","passage":"<p>The Oakville Horticulture Club <span class=\"blank\" data-n=\"135\">-------</span> a plant sale on Saturday, 9 September. The sale will be held from 9:00 A.M. to 4:00 P.M. at the Oakville Community Centre at 478 Hill Avenue. There will be great deals on hanging baskets, grasses, and herbs. <span class=\"blank\" data-n=\"136\">-------</span>. We <span class=\"blank\" data-n=\"137\">-------</span> have a delicious selection of fruits and vegetables available for purchase. Enjoy live talks and demonstrations <span class=\"blank\" data-n=\"138\">-------</span> the day. For more information, visit the Oakville Horticulture Web site: www.oakvillehorticultureclub.co.uk/events.</p>","vi":"Câu lạc bộ Làm vườn Oakville sẽ tổ chức một buổi bán cây vào thứ Bảy, ngày 9 tháng 9. Buổi bán hàng sẽ diễn ra từ 9 giờ sáng đến 4 giờ chiều tại Trung tâm Cộng đồng Oakville, số 478 đại lộ Hill. Sẽ có nhiều ưu đãi lớn cho giỏ cây treo, các loại cỏ và thảo mộc. Hãy đến sớm để chọn được những món tốt nhất. Chúng tôi cũng có nhiều loại trái cây và rau củ thơm ngon để bán. Hãy thưởng thức các buổi nói chuyện và trình diễn trực tiếp suốt cả ngày. Để biết thêm thông tin, hãy truy cập trang web của Câu lạc bộ Làm vườn Oakville: www.oakvillehorticultureclub.co.uk/events.","qs":[{"n":135,"opts":["host","hosted","is hosting","has hosted"],"ans":"C","xp":"Thì động từ: chủ ngữ số ít 'The Oakville Horticulture Club' → loại (A) host. Câu sau dùng 'The sale will be held…' → sự kiện ở tương lai, đã lên kế hoạch → hiện tại tiếp diễn 'is hosting' diễn tả kế hoạch tương lai. (B) hosted là quá khứ, (D) has hosted là hiện tại hoàn thành – chỉ việc đã xảy ra.\nDịch: Câu lạc bộ Làm vườn Oakville sẽ tổ chức một buổi bán cây vào thứ Bảy, ngày 9 tháng 9."},{"n":136,"opts":["Come early to get the best selection.","Plants help make your home beautiful.","Join the club for a discount on local garden tours.","The community center was just renovated."],"ans":"A","xp":"Điền câu: câu trước nói có 'great deals' (ưu đãi lớn) cho giỏ cây, cỏ, thảo mộc → (A) 'Hãy đến sớm để chọn được hàng tốt nhất' tiếp nối tự nhiên lời quảng cáo về hàng bán. Câu sau 'We also have…' cũng tiếp tục giới thiệu hàng bán. (B) quá chung chung; (C) nói về tour vườn, lạc đề; (D) trung tâm vừa sửa – không liên quan.\n(A) Hãy đến sớm để chọn được những món tốt nhất.\n(B) Cây cối giúp ngôi nhà của bạn đẹp hơn.\n(C) Hãy gia nhập câu lạc bộ để được giảm giá các tour tham quan vườn địa phương.\n(D) Trung tâm cộng đồng vừa được cải tạo."},{"n":137,"opts":["later","also","nearly","merely"],"ans":"B","xp":"Trạng từ (từ vựng): ngoài cây cối đã liệt kê, CLB 'cũng' có trái cây và rau củ để bán → 'also' = cũng. (A) later = sau đó, (C) nearly = gần như, (D) merely = chỉ đơn thuần – không hợp nghĩa.\nDịch: Chúng tôi cũng có nhiều loại trái cây và rau củ thơm ngon để bán."},{"n":138,"opts":["within","forward","following","throughout"],"ans":"D","xp":"Giới từ: 'throughout the day' = suốt cả ngày – các buổi nói chuyện, trình diễn diễn ra trong suốt buổi bán. (A) within = trong vòng/bên trong, (B) forward = về phía trước (trạng từ), (C) following = sau (following the sale = sau buổi bán) – không hợp với 'the day'.\nDịch: Hãy thưởng thức các buổi nói chuyện và trình diễn trực tiếp suốt cả ngày."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following letter.","passage":"<p>July 2</p><p>Dear Mr. Arakaki:</p><p>I am writing to inform you of scheduled road maintenance on Briggs Avenue. Beginning on July 15, Briggs Avenue <span class=\"blank\" data-n=\"139\">-------</span> reduced to one lane from Elm Street to Bay Road. <span class=\"blank\" data-n=\"140\">-------</span>. Although your <span class=\"blank\" data-n=\"141\">-------</span> is not located in this section of Briggs Avenue, traffic on most of the street will move more slowly than usual while work is being performed. You may <span class=\"blank\" data-n=\"142\">-------</span> consider advising your employees to take alternate routes to work during this time. The project is expected to be completed on or before October 22. Thank you for your cooperation and assistance.</p><p>Sincerely,</p><p>Amalia Villalobos<br>Director of Transportation<br>Enclosure</p>","vi":"Ngày 2 tháng 7\n\nKính gửi ông Arakaki:\n\nTôi viết thư này để thông báo với ông về đợt bảo trì đường đã lên lịch trên đại lộ Briggs. Bắt đầu từ ngày 15 tháng 7, đại lộ Briggs sẽ bị thu hẹp còn một làn xe từ phố Elm đến đường Bay. Vui lòng xem bản đồ khu vực bị ảnh hưởng được gửi kèm. Mặc dù doanh nghiệp của ông không nằm ở đoạn này của đại lộ Briggs, giao thông trên phần lớn con đường sẽ di chuyển chậm hơn bình thường trong thời gian thi công. Vì vậy, ông có thể cân nhắc khuyên nhân viên của mình đi các tuyến đường khác để đến chỗ làm trong thời gian này. Dự án dự kiến hoàn thành vào hoặc trước ngày 22 tháng 10. Cảm ơn sự hợp tác và hỗ trợ của ông.\n\nTrân trọng,\n\nAmalia Villalobos\nGiám đốc Sở Giao thông\nTài liệu gửi kèm","qs":[{"n":139,"opts":["was","will be","can be","has been"],"ans":"B","xp":"Thì động từ: thư viết ngày 2/7, việc bắt đầu 'Beginning on July 15' → sự việc trong tương lai, đã lên lịch ('scheduled road maintenance') → 'will be reduced' (sẽ bị thu hẹp). (A) was và (D) has been là quá khứ/hoàn thành; (C) can be = có thể bị – chỉ khả năng, không hợp với kế hoạch chắc chắn.\nDịch: Bắt đầu từ ngày 15 tháng 7, đại lộ Briggs sẽ bị thu hẹp còn một làn xe từ phố Elm đến đường Bay."},{"n":140,"opts":["Briggs Avenue is only two miles away.","The event will take place on Elm Street.","Please refer to the enclosed map of the affected area.","However, all city services will close during this time."],"ans":"C","xp":"Điền câu: câu trước mô tả đoạn đường bị thu hẹp (từ Elm Street đến Bay Road); cuối thư có chữ 'Enclosure' (tài liệu gửi kèm) → (C) 'Vui lòng xem bản đồ khu vực bị ảnh hưởng gửi kèm' khớp hoàn toàn. (A) khoảng cách 2 dặm – không liên quan; (B) không có 'sự kiện' nào; (D) mọi dịch vụ thành phố đóng cửa – không có căn cứ.\n(A) Đại lộ Briggs chỉ cách đó hai dặm.\n(B) Sự kiện sẽ diễn ra trên phố Elm.\n(C) Vui lòng xem bản đồ khu vực bị ảnh hưởng được gửi kèm.\n(D) Tuy nhiên, tất cả các dịch vụ của thành phố sẽ đóng cửa trong thời gian này."},{"n":141,"opts":["mailbox","school","signage","business"],"ans":"D","xp":"Từ vựng: phía sau thư nhắc 'advising your employees' (khuyên nhân viên của ông) → ông Arakaki có một doanh nghiệp → 'your business is not located in this section' = doanh nghiệp của ông không nằm ở đoạn này. (A) mailbox = hộp thư, (B) school = trường học, (C) signage = biển hiệu – không hợp với 'employees'.\nDịch: Mặc dù doanh nghiệp của ông không nằm ở đoạn này của đại lộ Briggs, giao thông trên phần lớn con đường sẽ chậm hơn bình thường."},{"n":142,"opts":["fortunately","instead","likewise","therefore"],"ans":"D","xp":"Trạng từ liên kết: câu trước nêu nguyên nhân (giao thông sẽ chậm hơn), câu này nêu hệ quả/đề xuất (khuyên nhân viên đi đường khác) → 'therefore' = vì vậy, do đó. (A) fortunately = may mắn thay, (B) instead = thay vào đó, (C) likewise = tương tự như vậy – không thể hiện quan hệ nhân quả.\nDịch: Vì vậy, ông có thể cân nhắc khuyên nhân viên đi các tuyến đường khác đến chỗ làm trong thời gian này."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following article.","passage":"<h3>Franklin Planetarium to Move Downtown</h3><p>(June 3)—After 48 years in its present location on Mayfield's south side, the Franklin Planetarium is moving to a new home. Construction is underway on the downtown facility, part of a complex that includes the new Natural History Museum. Both <span class=\"blank\" data-n=\"143\">-------</span> are expected to open to the public next September.</p><p>The current planetarium's main attraction is a 300-seat theater, where visitors can view projections of stars and planets on the dome above. <span class=\"blank\" data-n=\"144\">-------</span> a larger theater, the new planetarium will feature an upgraded digital projection system. <span class=\"blank\" data-n=\"145\">-------</span>. Visitors will be able <span class=\"blank\" data-n=\"146\">-------</span> the night sky more clearly and explore other planets and galaxies through new, interactive displays.</p>","vi":"Cung thiên văn Franklin chuyển về trung tâm thành phố\n\n(Ngày 3 tháng 6) – Sau 48 năm ở vị trí hiện tại phía nam Mayfield, Cung thiên văn Franklin đang chuyển đến một địa điểm mới. Công trình ở trung tâm thành phố đang được xây dựng, là một phần của khu phức hợp bao gồm cả Bảo tàng Lịch sử Tự nhiên mới. Cả hai tòa nhà dự kiến sẽ mở cửa đón công chúng vào tháng 9 năm sau.\n\nĐiểm thu hút chính của cung thiên văn hiện nay là một rạp chiếu 300 chỗ, nơi du khách có thể xem hình chiếu các vì sao và hành tinh trên mái vòm phía trên. Ngoài một rạp chiếu lớn hơn, cung thiên văn mới sẽ có hệ thống chiếu kỹ thuật số được nâng cấp. Ngoài ra cũng sẽ có chỗ cho ba khu trưng bày ngắn hạn. Du khách sẽ có thể ngắm bầu trời đêm rõ hơn và khám phá các hành tinh, thiên hà khác qua những màn trưng bày tương tác mới.","qs":[{"n":143,"opts":["trails","buildings","campuses","performances"],"ans":"B","xp":"Từ vựng: 'Both' chỉ hai thứ vừa được nhắc: cung thiên văn mới và Bảo tàng Lịch sử Tự nhiên mới trong cùng khu phức hợp → 'Both buildings' = cả hai tòa nhà sẽ mở cửa. (A) trails = đường mòn, (C) campuses = khuôn viên (trường), (D) performances = buổi biểu diễn.\nDịch: Cả hai tòa nhà dự kiến sẽ mở cửa đón công chúng vào tháng 9 năm sau."},{"n":144,"opts":["In addition to","In particular","In agreement with","For instance"],"ans":"A","xp":"Giới từ/cụm từ nối: sau chỗ trống là cụm danh từ 'a larger theater', rồi đến mệnh đề chính → cần giới từ. 'In addition to' = ngoài … ra, bên cạnh: ngoài rạp chiếu lớn hơn, còn có hệ thống chiếu nâng cấp. (B) In particular = đặc biệt là, (D) For instance = ví dụ – là trạng từ, không đi trực tiếp với danh từ như vậy; (C) In agreement with = đồng ý với – sai nghĩa.\nDịch: Ngoài một rạp chiếu lớn hơn, cung thiên văn mới sẽ có hệ thống chiếu kỹ thuật số được nâng cấp."},{"n":145,"opts":["There are currently three other museums in the Mayfield area.","Attendance at the planetarium has been up in recent years.","Planning for the new planetarium began five years ago.","There will be room for three short-term exhibits as well."],"ans":"D","xp":"Điền câu: đoạn 2 đang liệt kê các tiện ích của cung thiên văn MỚI (rạp lớn hơn, hệ thống chiếu nâng cấp…, màn trưng bày tương tác). (D) 'Cũng sẽ có chỗ cho ba khu trưng bày ngắn hạn' – có 'as well' (cũng) tiếp tục danh sách tính năng mới. (A) các bảo tàng khác – lạc đề; (B) lượng khách tăng – nói về quá khứ, phá mạch liệt kê; (C) kế hoạch bắt đầu 5 năm trước – không liên quan đến tính năng.\n(A) Hiện có ba bảo tàng khác ở khu vực Mayfield.\n(B) Lượng khách đến cung thiên văn đã tăng trong những năm gần đây.\n(C) Việc lên kế hoạch cho cung thiên văn mới bắt đầu từ năm năm trước.\n(D) Ngoài ra cũng sẽ có chỗ cho ba khu trưng bày ngắn hạn."},{"n":146,"opts":["to see","will see","who saw","by seeing"],"ans":"A","xp":"Cấu trúc: 'be able to + V' = có thể làm gì → 'able to see'. (B) will see là động từ chia, (C) who saw là mệnh đề quan hệ, (D) by seeing = bằng cách nhìn – đều sai cấu trúc.\nDịch: Du khách sẽ có thể ngắm bầu trời đêm rõ hơn và khám phá các hành tinh, thiên hà khác qua những màn trưng bày tương tác mới."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following notice.","passages":["<h3>NOTICE</h3><p>As part of our routine maintenance of Selino Apartments, all public areas of our building will be painted according to the following schedule:</p><ul><li>Stairwells, first and second floors: 12 April</li><li>Hallways, first and second floors: 13 April</li><li>Stairwells, third and fourth floors: 14 April</li><li>Hallways, third and fourth floors: 15 April</li></ul><p>The elevators will be available during this time. Please use caution, and do not touch any wet paint.</p><p>Management, Selino Apartments</p>"],"vi":"THÔNG BÁO\n\nTrong khuôn khổ công tác bảo trì định kỳ tại Chung cư Selino, tất cả các khu vực công cộng của tòa nhà sẽ được sơn theo lịch sau:\n\n- Cầu thang bộ, tầng một và tầng hai: ngày 12 tháng 4\n- Hành lang, tầng một và tầng hai: ngày 13 tháng 4\n- Cầu thang bộ, tầng ba và tầng bốn: ngày 14 tháng 4\n- Hành lang, tầng ba và tầng bốn: ngày 15 tháng 4\n\nThang máy vẫn sử dụng được trong thời gian này. Xin hãy cẩn thận và không chạm vào sơn còn ướt.\n\nBan quản lý, Chung cư Selino","qs":[{"n":147,"q":"For whom is the notice most likely intended?","qvi":"Thông báo này nhiều khả năng dành cho ai?","opts":["Painting contractors","Elevator repair workers","Graphic artists","Apartment residents"],"ans":"D","xp":"Câu hỏi suy luận (đối tượng người đọc). Thông báo nói về việc sơn \"all public areas of our building\" của \"Selino Apartments\", dặn \"The elevators will be available during this time. Please use caution, and do not touch any wet paint\" và ký tên \"Management, Selino Apartments\" → ban quản lý gửi cho người đang sống trong chung cư → chọn (D). Thợ sơn là người làm việc, không phải người được nhắc 'đừng chạm vào sơn ướt'; thang máy không bị sửa.\n(A) Các nhà thầu sơn\n(B) Thợ sửa thang máy\n(C) Họa sĩ đồ họa\n(D) Cư dân chung cư"},{"n":148,"q":"When will work on the stairwells of all floors most likely be completed?","qvi":"Công việc ở cầu thang bộ của tất cả các tầng nhiều khả năng sẽ hoàn thành khi nào?","opts":["On April 12","On April 13","On April 14","On April 15"],"ans":"C","xp":"Câu hỏi chi tiết. Lịch ghi: \"Stairwells, first and second floors: 12 April\" và \"Stairwells, third and fourth floors: 14 April\" → cầu thang của tầng cuối cùng (tầng 3, 4) được sơn vào ngày 14/4, nên toàn bộ cầu thang xong vào ngày 14/4 → chọn (C). Ngày 13 và 15 là lịch sơn hành lang (Hallways).\n(A) Vào ngày 12 tháng 4\n(B) Vào ngày 13 tháng 4\n(C) Vào ngày 14 tháng 4\n(D) Vào ngày 15 tháng 4"}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following coupon.","passages":["<h3>Jin-Hwa Grill</h3><p>Serving the finest Korean cuisine in northern California for over 30 years</p><p>Come celebrate the reopening of our newly remodeled restaurant on Lakeside Drive! Purchase any two dinners and enjoy a complimentary appetizer platter during the entire month of May.</p><p>Valid only at Jin-Hwa Grill, 4104 Lakeside Drive, Oakland, CA. Coupon does not apply to takeout orders. Visit www.jin-hwagrill.com for a list of all our locations, hours of operation, and menus.</p>"],"vi":"Jin-Hwa Grill\nPhục vụ những món ăn Hàn Quốc ngon nhất ở miền bắc California trong hơn 30 năm\n\nHãy đến mừng ngày mở cửa trở lại của nhà hàng vừa được tu sửa của chúng tôi trên đường Lakeside Drive! Mua hai suất ăn tối bất kỳ và thưởng thức một đĩa món khai vị miễn phí trong suốt tháng Năm.\n\nChỉ áp dụng tại Jin-Hwa Grill, số 4104 Lakeside Drive, Oakland, CA. Phiếu giảm giá không áp dụng cho đơn mang đi. Hãy truy cập www.jin-hwagrill.com để xem danh sách tất cả các chi nhánh, giờ mở cửa và thực đơn của chúng tôi.","qs":[{"n":149,"q":"How can people receive the benefit from the coupon?","qvi":"Làm thế nào để khách hàng nhận được ưu đãi từ phiếu giảm giá?","opts":["By placing a takeout order","By spending a minimum amount of money","By ordering two meals","By attending the opening day celebration"],"ans":"C","xp":"Câu hỏi chi tiết. Phiếu ghi: \"Purchase any two dinners and enjoy a complimentary appetizer platter\" → mua hai suất ăn tối = ordering two meals → chọn (C). (A) sai vì \"Coupon does not apply to takeout orders\"; (B) không nói số tiền tối thiểu; (D) ưu đãi kéo dài cả tháng Năm, không cần dự ngày khai trương.\n(A) Bằng cách đặt đơn mang đi\n(B) Bằng cách chi tiêu một số tiền tối thiểu\n(C) Bằng cách gọi hai suất ăn\n(D) Bằng cách tham dự lễ mừng ngày khai trương"},{"n":150,"q":"What is mentioned about Jin-Hwa Grill?","qvi":"Điều gì được nhắc đến về Jin-Hwa Grill?","opts":["It is celebrating an anniversary.","It has more than one location.","It recently began serving Korean food.","It has expanded its hours of operation."],"ans":"B","xp":"Câu hỏi chi tiết. Câu cuối: \"Visit www.jin-hwagrill.com for a list of all our locations\" → 'danh sách tất cả các chi nhánh' nghĩa là nhà hàng có nhiều hơn một địa điểm → chọn (B). (A) sai: họ mừng 'reopening' (mở cửa lại), không phải kỷ niệm thành lập; (C) sai: đã phục vụ món Hàn \"for over 30 years\"; (D) giờ mở cửa không được nói là kéo dài thêm.\n(A) Nhà hàng đang kỷ niệm ngày thành lập.\n(B) Nhà hàng có nhiều hơn một chi nhánh.\n(C) Nhà hàng mới bắt đầu phục vụ món Hàn Quốc.\n(D) Nhà hàng đã kéo dài giờ mở cửa."}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Bindu Gil &lt;bgil@opalmail.com&gt;</p><p><b>From:</b> Neela Balay &lt;n_balay@celebrate.com&gt;</p><p><b>Date:</b> June 18</p><p><b>Subject:</b> Follow-up</p></div><p>Dear Ms. Gil,</p><p>Regarding our telephone conversation earlier today, here in writing is the change I would like to make to Saturday's delivery.</p><p>I am requesting that you now deliver the flowers to the Grand Dining Room at the Kaltan Hotel instead of the Saji Banquet Hall. I apologize for this last-minute switch, but the banquet hall manager contacted me just last night to inform me about an electrical system malfunction that will require a weekend repair. Since the office party I am planning cannot be postponed, I have had to reserve this other venue.</p><p>I would appreciate receiving the delivery by 4:00 P.M.</p><p>Best regards,</p><p>Neela Balay</p>"],"vi":"Người nhận: Bindu Gil <bgil@opalmail.com>\nNgười gửi: Neela Balay <n_balay@celebrate.com>\nNgày: 18 tháng 6\nTiêu đề: Theo dõi tiếp\n\nKính gửi cô Gil,\n\nLiên quan đến cuộc nói chuyện qua điện thoại của chúng ta sáng nay, tôi xin ghi lại bằng văn bản thay đổi mà tôi muốn thực hiện đối với đơn giao hàng hôm thứ Bảy.\n\nTôi đề nghị cô giao hoa đến Phòng ăn Grand ở Khách sạn Kaltan thay vì Sảnh tiệc Saji. Tôi xin lỗi vì sự thay đổi vào phút chót này, nhưng quản lý sảnh tiệc mới liên lạc với tôi tối qua để báo về một sự cố hệ thống điện cần phải sửa vào cuối tuần. Vì bữa tiệc văn phòng tôi đang tổ chức không thể hoãn lại, tôi đã phải đặt địa điểm khác này.\n\nTôi rất mong nhận được hàng trước 4 giờ chiều.\n\nTrân trọng,\n\nNeela Balay","qs":[{"n":151,"q":"Why did Ms. Balay send an e-mail to Ms. Gil?","qvi":"Tại sao cô Balay gửi e-mail cho cô Gil?","opts":["To reschedule a weekend business trip","To invite her to an office party","To request the services of an electrician","To confirm some spoken instructions"],"ans":"D","xp":"Câu hỏi mục đích. Câu mở đầu: \"Regarding our telephone conversation earlier today, here in writing is the change I would like to make\" → cô ấy viết lại bằng văn bản yêu cầu đã nói qua điện thoại = xác nhận chỉ dẫn bằng lời (spoken instructions) → chọn (D). (B) bữa tiệc văn phòng có nhắc nhưng không mời cô Gil; (C) thợ điện là việc của sảnh tiệc; (A) không có chuyến công tác nào.\n(A) Để dời lịch một chuyến công tác cuối tuần\n(B) Để mời cô ấy đến một bữa tiệc văn phòng\n(C) Để yêu cầu dịch vụ của thợ điện\n(D) Để xác nhận một số chỉ dẫn đã nói qua lời"},{"n":152,"q":"What does Ms. Balay expect to receive on Saturday afternoon?","qvi":"Cô Balay mong đợi nhận được gì vào chiều thứ Bảy?","opts":["Flowers","Tickets","A signed contract","An updated cost estimate"],"ans":"A","xp":"Câu hỏi chi tiết. E-mail nói về \"Saturday's delivery\", yêu cầu \"deliver the flowers to the Grand Dining Room\" và \"I would appreciate receiving the delivery by 4:00 P.M.\" → chiều thứ Bảy cô ấy nhận hoa → chọn (A).\n(A) Hoa\n(B) Vé\n(C) Một hợp đồng đã ký\n(D) Một bảng báo giá đã cập nhật"}]},{"ns":[153,154],"head":"Questions 153-154 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Ae-Cha Kim (9:16 A.M.)</b></p><p>Good morning. I have an issue with an order I placed on the Winter Wear Web site.</p></div><div class=\"msg\"><p><b>Kelvin Long (9:18 A.M.)</b></p><p>Good morning. How can I help you?</p></div><div class=\"msg\"><p><b>Ae-Cha Kim (9:20 A.M.)</b></p><p>Well, I ordered some gloves two weeks ago, and they still haven't arrived.</p></div><div class=\"msg\"><p><b>Kelvin Long (9:21 A.M.)</b></p><p>I'm sorry to hear that. Did you get an order number?</p></div><div class=\"msg\"><p><b>Ae-Cha Kim (9:22 A.M.)</b></p><p>It's ADF193.</p></div><div class=\"msg\"><p><b>Kelvin Long (9:23 A.M.)</b></p><p>Thanks.</p></div><div class=\"msg\"><p><b>Kelvin Long (9:26 A.M.)</b></p><p>This is very unusual. The system is showing that the order was fulfilled. I'm not sure why it hasn't left the warehouse yet. I can have another pair of gloves sent to you with rush shipping, at no extra charge.</p></div><div class=\"msg\"><p><b>Ae-Cha Kim (9:27 A.M.)</b></p><p>That would be great! Thanks!</p></div>"],"vi":"Ae-Cha Kim (9:16 sáng): Chào buổi sáng. Tôi gặp vấn đề với một đơn hàng tôi đã đặt trên trang web Winter Wear.\n\nKelvin Long (9:18 sáng): Chào buổi sáng. Tôi có thể giúp gì cho chị?\n\nAe-Cha Kim (9:20 sáng): À, tôi đã đặt mua đôi găng tay cách đây hai tuần mà vẫn chưa nhận được.\n\nKelvin Long (9:21 sáng): Tôi rất tiếc khi nghe điều đó. Chị có nhận được mã đơn hàng không?\n\nAe-Cha Kim (9:22 sáng): Mã là ADF193.\n\nKelvin Long (9:23 sáng): Cảm ơn chị.\n\nKelvin Long (9:26 sáng): Chuyện này rất bất thường. Hệ thống đang hiển thị là đơn hàng đã được xử lý xong. Tôi không rõ tại sao nó vẫn chưa rời kho. Tôi có thể cho gửi một đôi găng tay khác đến chị bằng hình thức giao hàng nhanh, không tính thêm phí.\n\nAe-Cha Kim (9:27 sáng): Vậy thì tuyệt quá! Cảm ơn anh!","qs":[{"n":153,"q":"What problem does Ms. Kim have?","qvi":"Cô Kim gặp vấn đề gì?","opts":["She received the wrong order.","Her order has not arrived.","An item was damaged in transport.","An item is missing from her order."],"ans":"B","xp":"Câu hỏi chi tiết. Lúc 9:20 cô Kim viết: \"I ordered some gloves two weeks ago, and they still haven't arrived.\" → đơn hàng chưa đến → chọn (B). Cô ấy chưa nhận được gì nên không thể nhận sai, hỏng hay thiếu hàng.\n(A) Cô ấy nhận nhầm đơn hàng.\n(B) Đơn hàng của cô ấy chưa đến.\n(C) Một món hàng bị hư hỏng khi vận chuyển.\n(D) Đơn hàng của cô ấy bị thiếu một món."},{"n":154,"q":"At 9:26 A.M., what does Mr. Long most likely mean when he writes, \"This is very unusual\"?","qvi":"Lúc 9:26 sáng, khi anh Long viết \"This is very unusual\" (Chuyện này rất bất thường), nhiều khả năng anh ấy có ý gì?","opts":["He is frustrated by the slow computer system.","He is sorry about taking so long to answer Ms. Kim's question.","He is surprised about the warehouse issue.","He is confused about which style of gloves was ordered."],"ans":"C","xp":"Câu hỏi hàm ý. Ngay sau câu đó anh Long giải thích: \"The system is showing that the order was fulfilled. I'm not sure why it hasn't left the warehouse yet.\" → anh ấy ngạc nhiên vì hệ thống báo đã xử lý mà hàng vẫn nằm trong kho → chọn (C). Không có chi tiết hệ thống chậm, xin lỗi vì trả lời lâu hay nhầm kiểu găng tay.\n(A) Anh ấy bực mình vì hệ thống máy tính chậm.\n(B) Anh ấy xin lỗi vì mất quá lâu để trả lời câu hỏi của cô Kim.\n(C) Anh ấy ngạc nhiên về vấn đề ở kho hàng.\n(D) Anh ấy bối rối không biết kiểu găng tay nào đã được đặt."}]},{"ns":[155,157],"head":"Questions 155-157 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Jessica Yu &lt;jyu@myemail.com&gt;</p><p><b>From:</b> Customer Service &lt;cs@velascobank.com&gt;</p><p><b>Date:</b> July 15</p><p><b>Subject:</b> Customer account security</p></div><p>Dear Ms. Yu,</p><p>For security reasons we need our customers to review their contact information with Velasco Bank every year. <span class=\"pos\">[1]</span> This year, the deadline to review your contact information is July 29. <span class=\"pos\">[2]</span> You may check your information on our Web site at www.velascobank.com, or you can do so on the Velasco Bank mobile app. Simply log in to your digital banking account, go to \"Settings,\" and then go to \"Contact.\" <span class=\"pos\">[3]</span> Review your phone number and e-mail address to make sure they are both up-to-date. Then select them as your primary contact methods. If you are not yet enrolled in digital banking, we recommend doing so online at www.velascobank.com/myaccount.</p><p><span class=\"pos\">[4]</span> If you have any questions, please visit any of our branches or call us at 410-555-0156 Monday through Friday, 7:00 A.M. to 5:00 P.M.</p><p>Thank you,</p><p>Velasco Bank Customer Service</p>"],"vi":"Người nhận: Jessica Yu <jyu@myemail.com>\nNgười gửi: Bộ phận Chăm sóc Khách hàng <cs@velascobank.com>\nNgày: 15 tháng 7\nTiêu đề: Bảo mật tài khoản khách hàng\n\nKính gửi cô Yu,\n\nVì lý do bảo mật, chúng tôi cần khách hàng xem lại thông tin liên lạc của mình với Ngân hàng Velasco mỗi năm. [1] Năm nay, hạn chót để xem lại thông tin liên lạc là ngày 29 tháng 7. [2] Cô có thể kiểm tra thông tin của mình trên trang web của chúng tôi tại www.velascobank.com, hoặc cô có thể làm việc này trên ứng dụng di động của Ngân hàng Velasco. Chỉ cần đăng nhập vào tài khoản ngân hàng số, vào mục \"Settings\" (Cài đặt), rồi vào mục \"Contact\" (Liên hệ). [3] Hãy xem lại số điện thoại và địa chỉ e-mail để chắc chắn rằng cả hai đều được cập nhật. Sau đó chọn chúng làm phương thức liên lạc chính. Nếu cô chưa đăng ký ngân hàng số, chúng tôi khuyên cô nên đăng ký trực tuyến tại www.velascobank.com/myaccount.\n\n[4] Nếu cô có bất kỳ câu hỏi nào, vui lòng đến bất kỳ chi nhánh nào của chúng tôi hoặc gọi cho chúng tôi theo số 410-555-0156 từ thứ Hai đến thứ Sáu, 7 giờ sáng đến 5 giờ chiều.\n\nXin cảm ơn,\n\nBộ phận Chăm sóc Khách hàng Ngân hàng Velasco","qs":[{"n":155,"q":"What is the purpose of the e-mail?","qvi":"Mục đích của e-mail là gì?","opts":["To inquire about an account closure","To inform customers of a change in banking hours","To ask a customer to confirm personal data","To provide information about a bank deposit"],"ans":"C","xp":"Câu hỏi mục đích. Câu đầu: \"we need our customers to review their contact information with Velasco Bank every year\" và \"the deadline to review your contact information is July 29\" → ngân hàng yêu cầu khách hàng kiểm tra/xác nhận thông tin cá nhân (contact information → personal data) → chọn (C). Không nói về đóng tài khoản, đổi giờ làm việc hay tiền gửi.\n(A) Để hỏi về việc đóng tài khoản\n(B) Để thông báo cho khách hàng về thay đổi giờ làm việc của ngân hàng\n(C) Để yêu cầu khách hàng xác nhận dữ liệu cá nhân\n(D) Để cung cấp thông tin về một khoản tiền gửi ngân hàng"},{"n":156,"q":"According to the e-mail, what should a customer do to register for digital banking?","qvi":"Theo e-mail, khách hàng nên làm gì để đăng ký ngân hàng số?","opts":["Go to the bank's Web site","Contact a customer service representative","Visit a local bank branch","Install a mobile app"],"ans":"A","xp":"Câu hỏi chi tiết. E-mail viết: \"If you are not yet enrolled in digital banking, we recommend doing so online at www.velascobank.com/myaccount.\" → đăng ký trực tuyến trên trang web của ngân hàng → chọn (A). Gọi điện hay đến chi nhánh là khi có câu hỏi; ứng dụng di động dùng để kiểm tra thông tin, không phải để đăng ký.\n(A) Truy cập trang web của ngân hàng\n(B) Liên hệ nhân viên chăm sóc khách hàng\n(C) Đến một chi nhánh ngân hàng ở địa phương\n(D) Cài đặt một ứng dụng di động"},{"n":157,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"This can be done in one of two ways.\"","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"This can be done in one of two ways.\" (Việc này có thể thực hiện theo một trong hai cách.)","opts":["[1]","[2]","[3]","[4]"],"ans":"B","xp":"Câu hỏi điền câu. Câu cần điền nói 'có hai cách làm việc này'. Ngay sau vị trí [2] là hai cách: \"You may check your information on our Web site ..., or you can do so on the Velasco Bank mobile app.\" (trang web hoặc ứng dụng). 'This' chỉ việc xem lại thông tin liên lạc được nhắc ở câu trước (\"the deadline to review your contact information is July 29\") → chọn (B).\n(A) [1]\n(B) [2]\n(C) [3]\n(D) [4]"}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following brochure.","passages":["<h3>Sumner Woodcrafting</h3><p>Sumner Woodcrafting of Memphis, Tennessee, was established nearly 45 years ago by Kiran Sumner, with the goal of providing personalized service to customers seeking high-quality, handmade furniture. Now semiretired, Mr. Sumner still takes orders and responds to questions himself through the company's customer-service telephone line at 901-555-0185 on Thursdays and Fridays. Sumner Woodcrafting offers a wide selection of custom-made bedroom sets, tables, desks, cabinetry, and more—all made from high-quality solid woods.</p><p>Prices for handcrafted furniture are naturally higher than for furniture that is mass-produced in a factory. Because our master crafters do exceptionally fine work, our customers never regret spending a bit more for pieces built to last for generations.</p><p>Note that it can take up to two months to create a piece of furniture once it is ordered. Delivery fees are based on distance from our workshop. Unpacking and placing the item is available for an additional $50.</p><p>For photos of our workshop, artisan biographies, customer reviews, and ordering information, please visit us online at www.sumnerwoodcrafting.com.</p>"],"vi":"Sumner Woodcrafting\n\nSumner Woodcrafting ở Memphis, Tennessee, được Kiran Sumner thành lập cách đây gần 45 năm với mục tiêu mang lại dịch vụ dành riêng cho từng khách hàng đang tìm kiếm đồ nội thất làm thủ công chất lượng cao. Giờ đây dù đã bán nghỉ hưu, ông Sumner vẫn đích thân nhận đơn đặt hàng và trả lời câu hỏi qua đường dây điện thoại chăm sóc khách hàng của công ty theo số 901-555-0185 vào các ngày thứ Năm và thứ Sáu. Sumner Woodcrafting cung cấp nhiều lựa chọn bộ phòng ngủ, bàn ăn, bàn làm việc, tủ kệ và nhiều thứ khác được làm theo yêu cầu — tất cả đều làm từ gỗ nguyên khối chất lượng cao.\n\nGiá của đồ nội thất làm thủ công đương nhiên cao hơn đồ nội thất sản xuất hàng loạt trong nhà máy. Vì các thợ cả của chúng tôi làm việc đặc biệt tinh xảo, khách hàng của chúng tôi không bao giờ hối tiếc khi chi thêm một chút cho những sản phẩm được làm để dùng qua nhiều thế hệ.\n\nXin lưu ý rằng có thể mất tới hai tháng để làm ra một món đồ nội thất sau khi được đặt. Phí giao hàng được tính dựa trên khoảng cách từ xưởng của chúng tôi. Dịch vụ mở hộp và sắp đặt món đồ có với chi phí thêm 50 đô la.\n\nĐể xem ảnh xưởng, tiểu sử các nghệ nhân, đánh giá của khách hàng và thông tin đặt hàng, vui lòng truy cập trang web của chúng tôi tại www.sumnerwoodcrafting.com.","qs":[{"n":158,"q":"What is mentioned about Sumner Woodcrafting?","qvi":"Điều gì được nhắc đến về Sumner Woodcrafting?","opts":["Its prices are highly competitive.","It offers free delivery in Memphis.","Its founder handles telephone inquiries.","It allows customers to tour its workshop."],"ans":"C","xp":"Câu hỏi chi tiết. Đoạn 1: công ty do \"Kiran Sumner\" thành lập và \"Mr. Sumner still takes orders and responds to questions himself through the company's customer-service telephone line\" → nhà sáng lập trực tiếp trả lời câu hỏi qua điện thoại → chọn (C). (A) sai: giá \"naturally higher\"; (B) sai: \"Delivery fees are based on distance\"; (D) chỉ có ảnh xưởng trên web, không có tham quan.\n(A) Giá của công ty rất cạnh tranh.\n(B) Công ty giao hàng miễn phí ở Memphis.\n(C) Nhà sáng lập của công ty xử lý các câu hỏi qua điện thoại.\n(D) Công ty cho phép khách hàng tham quan xưởng."},{"n":159,"q":"The word \"fine\" in paragraph 2, line 2, is closest in meaning to","qvi":"Từ \"fine\" ở đoạn 2, dòng 2 gần nghĩa nhất với","opts":["small","sharp","skillful","agreeable"],"ans":"C","xp":"Câu hỏi đồng nghĩa. Câu gốc: \"Because our master crafters do exceptionally fine work\" → 'fine work' ở đây là công việc tinh xảo, tay nghề cao → skillful (khéo léo, điêu luyện) → chọn (C). 'fine' còn có nghĩa 'nhỏ, mảnh' (small) hay 'sắc' (sharp) nhưng không hợp ngữ cảnh khen tay nghề thợ cả.\n(A) nhỏ\n(B) sắc bén\n(C) khéo léo, điêu luyện\n(D) dễ chịu"},{"n":160,"q":"What is suggested about Sumner Woodcrafting's products?","qvi":"Điều gì được ngụ ý về sản phẩm của Sumner Woodcrafting?","opts":["They are extremely long-lasting.","They contain both natural and human-made materials.","They often require assembly after delivery.","They are usually ordered for offices."],"ans":"A","xp":"Câu hỏi suy luận. Đoạn 2: \"our customers never regret spending a bit more for pieces built to last for generations\" → được làm để dùng qua nhiều thế hệ = cực kỳ bền → chọn (A). (B) sai: \"all made from high-quality solid woods\"; (C) chỉ nói dịch vụ mở hộp và sắp đặt, không nói phải lắp ráp; (D) sản phẩm gồm bộ phòng ngủ, bàn..., không nói chủ yếu cho văn phòng.\n(A) Chúng cực kỳ bền.\n(B) Chúng gồm cả vật liệu tự nhiên lẫn nhân tạo.\n(C) Chúng thường phải lắp ráp sau khi giao.\n(D) Chúng thường được đặt cho văn phòng."}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following article.","passages":["<p>COLLINSVALE (28 March)—Over the last decade, instability in the pricing of raw materials has become the biggest concern for manufacturers. The issue now surpasses recruitment and technology, which had previously been ranked by businesses as the top two concerns respectively.</p><p>The reasons are not difficult to understand. For electronics manufacturers, materials typically represent 20 percent of all expenses, while makers of processed food can spend anywhere between 40 and 60 percent on materials. Thus, even a 10 percent rise in the cost of sugar can dramatically affect a factory's bottom line. Companies that can predict rising costs may be able to temper the effects of market volatility, but even the best forecasting cannot anticipate every change in the marketplace.</p>"],"vi":"COLLINSVALE (28 tháng 3) — Trong thập kỷ qua, sự bất ổn trong giá nguyên liệu thô đã trở thành mối lo lớn nhất của các nhà sản xuất. Vấn đề này hiện đã vượt qua tuyển dụng và công nghệ, hai vấn đề trước đây lần lượt được các doanh nghiệp xếp là mối lo hàng đầu và thứ hai.\n\nLý do không khó hiểu. Đối với các nhà sản xuất đồ điện tử, nguyên liệu thường chiếm 20% tổng chi phí, trong khi các nhà sản xuất thực phẩm chế biến có thể chi từ 40 đến 60% cho nguyên liệu. Vì vậy, chỉ cần giá đường tăng 10% cũng có thể ảnh hưởng nghiêm trọng đến lợi nhuận của một nhà máy. Những công ty có thể dự đoán chi phí tăng có thể giảm bớt tác động của sự biến động thị trường, nhưng ngay cả dự báo tốt nhất cũng không thể lường trước mọi thay đổi trên thị trường.","qs":[{"n":161,"q":"What is the article mainly about?","qvi":"Bài báo chủ yếu nói về điều gì?","opts":["An improvement in manufacturing methods","A recent shift in consumer preferences","The introduction of environmental regulations","The changes in costs faced by producers"],"ans":"D","xp":"Câu hỏi chủ đề. Câu mở đầu: \"instability in the pricing of raw materials has become the biggest concern for manufacturers\", phần sau phân tích chi phí nguyên liệu và \"rising costs\" → bài nói về sự thay đổi chi phí mà nhà sản xuất phải đối mặt (manufacturers → producers; instability in pricing → changes in costs) → chọn (D). Không nói về phương pháp sản xuất, sở thích người tiêu dùng hay quy định môi trường.\n(A) Một cải tiến trong phương pháp sản xuất\n(B) Một sự thay đổi gần đây trong sở thích của người tiêu dùng\n(C) Việc ban hành các quy định về môi trường\n(D) Những thay đổi về chi phí mà các nhà sản xuất phải đối mặt"},{"n":162,"q":"Why does the writer mention electronics manufacturers?","qvi":"Tại sao người viết nhắc đến các nhà sản xuất đồ điện tử?","opts":["To illustrate innovation over ten years","To show the impact of global trade","To explain recent staffing difficulties","To make a comparison between industries"],"ans":"D","xp":"Câu hỏi mục đích (lý do nhắc chi tiết). Câu: \"For electronics manufacturers, materials typically represent 20 percent of all expenses, while makers of processed food can spend anywhere between 40 and 60 percent on materials.\" → từ 'while' cho thấy tác giả đặt ngành điện tử cạnh ngành thực phẩm chế biến để so sánh tỷ lệ chi phí nguyên liệu → chọn (D).\n(A) Để minh họa sự đổi mới trong mười năm\n(B) Để cho thấy tác động của thương mại toàn cầu\n(C) Để giải thích những khó khăn gần đây về nhân sự\n(D) Để so sánh giữa các ngành"},{"n":163,"q":"The word \"temper\" in paragraph 2, line 9, is closest in meaning to","qvi":"Từ \"temper\" ở đoạn 2, dòng 9 gần nghĩa nhất với","opts":["set","toughen","moderate","combine"],"ans":"C","xp":"Câu hỏi đồng nghĩa. Câu gốc: \"Companies that can predict rising costs may be able to temper the effects of market volatility\" → công ty dự đoán được chi phí tăng thì có thể làm dịu/giảm bớt tác động của biến động thị trường → temper = moderate (làm giảm nhẹ, điều hòa) → chọn (C). (B) toughen là 'làm cứng/tôi luyện' (nghĩa của temper khi nói về kim loại), không hợp ngữ cảnh.\n(A) đặt, thiết lập\n(B) làm cứng hơn\n(C) làm giảm nhẹ, điều hòa\n(D) kết hợp"}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following announcement.","passages":["<p>The Lowenstein Bookstore in Mission Bay invites you to this month's book discussion featuring author Hilda Flores. The event will be held on Thursday, April 10, from 7:00 P.M. to 8:30 P.M. Ms. Flores will talk about her new novel, <i>Grinding the Gears</i>. <span class=\"pos\">[1]</span> The latest adventure in the popular Inspector Svensson series, <i>Grinding the Gears</i> finds the beloved inspector investigating strange equipment malfunctions at a national physics research laboratory. <span class=\"pos\">[2]</span></p><p>Ms. Flores will discuss the background research she performed while writing the book. <span class=\"pos\">[3]</span> A question and answer session will follow the presentation. The event is free for all to attend. <span class=\"pos\">[4]</span> The bookstore requires that attendees register at least one day in advance.</p>"],"vi":"Hiệu sách Lowenstein ở Mission Bay mời bạn đến buổi thảo luận sách tháng này với sự góp mặt của tác giả Hilda Flores. Sự kiện sẽ diễn ra vào thứ Năm, ngày 10 tháng 4, từ 7:00 đến 8:30 tối. Bà Flores sẽ nói về cuốn tiểu thuyết mới của mình, Grinding the Gears. [1] Là cuộc phiêu lưu mới nhất trong loạt truyện nổi tiếng về Thanh tra Svensson, Grinding the Gears kể về vị thanh tra được yêu mến điều tra những sự cố thiết bị kỳ lạ tại một phòng thí nghiệm nghiên cứu vật lý quốc gia. [2]\n\nBà Flores sẽ nói về quá trình nghiên cứu bối cảnh mà bà đã thực hiện khi viết cuốn sách. [3] Phần hỏi đáp sẽ diễn ra sau bài trình bày. Sự kiện miễn phí cho tất cả mọi người. [4] Hiệu sách yêu cầu người tham dự đăng ký trước ít nhất một ngày.","qs":[{"n":164,"q":"What is being announced?","qvi":"Điều gì đang được thông báo?","opts":["The opening of a new bookstore","A presentation by a book author","A book describing a research project","An upcoming movie based on a book"],"ans":"B","xp":"Câu hỏi chủ đề. Câu đầu: \"invites you to this month's book discussion featuring author Hilda Flores\" và \"Ms. Flores will talk about her new novel\", \"A question and answer session will follow the presentation\" → buổi trình bày của một tác giả → chọn (B). Hiệu sách không mới mở; (C) cuốn sách là tiểu thuyết, không phải mô tả dự án nghiên cứu; không có phim.\n(A) Việc khai trương một hiệu sách mới\n(B) Một buổi trình bày của một tác giả sách\n(C) Một cuốn sách mô tả một dự án nghiên cứu\n(D) Một bộ phim sắp ra mắt dựa trên một cuốn sách"},{"n":165,"q":"What type of book is Grinding the Gears?","qvi":"Grinding the Gears là loại sách gì?","opts":["A nonfiction story","A biography of a scientist","A collection of short stories","A mystery novel"],"ans":"D","xp":"Câu hỏi chi tiết. Đoạn 1: \"her new novel, Grinding the Gears\" và \"The latest adventure in the popular Inspector Svensson series ... finds the beloved inspector investigating strange equipment malfunctions\" → tiểu thuyết có thanh tra điều tra sự việc kỳ lạ = tiểu thuyết trinh thám/bí ẩn → chọn (D). Đây là 'novel' (hư cấu) nên không phải (A) hay (B); là một cuốn tiểu thuyết, không phải tập truyện ngắn.\n(A) Một câu chuyện phi hư cấu\n(B) Tiểu sử của một nhà khoa học\n(C) Một tuyển tập truyện ngắn\n(D) Một tiểu thuyết trinh thám"},{"n":166,"q":"What is indicated about registration?","qvi":"Điều gì được nêu về việc đăng ký?","opts":["It closes on April 9.","It requires payment of a fee.","It is optional but encouraged.","It cannot be completed online."],"ans":"A","xp":"Câu hỏi suy luận. Sự kiện diễn ra \"on Thursday, April 10\" và \"The bookstore requires that attendees register at least one day in advance\" → phải đăng ký chậm nhất ngày 9/4, tức hạn đăng ký kết thúc ngày 9/4 → chọn (A). (B) sai: \"The event is free for all to attend\"; (C) sai: đăng ký là bắt buộc (requires); (D) không đề cập cách đăng ký.\n(A) Hạn đăng ký kết thúc vào ngày 9 tháng 4.\n(B) Phải trả phí khi đăng ký.\n(C) Đăng ký là không bắt buộc nhưng được khuyến khích.\n(D) Không thể đăng ký trực tuyến."},{"n":167,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"Part of her fact-finding involved interviewing government scientists.\"","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"Part of her fact-finding involved interviewing government scientists.\" (Một phần trong quá trình tìm hiểu thực tế của bà là phỏng vấn các nhà khoa học của chính phủ.)","opts":["[1]","[2]","[3]","[4]"],"ans":"C","xp":"Câu hỏi điền câu. 'her fact-finding' (việc tìm hiểu thực tế của bà) nối với câu ngay trước [3]: \"Ms. Flores will discuss the background research she performed while writing the book.\" → 'fact-finding' diễn đạt lại 'background research', và việc phỏng vấn nhà khoa học chính phủ hợp với bối cảnh 'phòng thí nghiệm vật lý quốc gia' trong truyện → chọn (C).\n(A) [1]\n(B) [2]\n(C) [3]\n(D) [4]"}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Customer Service &lt;customerservice@kishintech.com&gt;</p><p><b>From:</b> Dmytro Petrov &lt;d.petrov@silkmail.com&gt;</p><p><b>Date:</b> November 5</p><p><b>Subject:</b> Assistance with Kishin XT20 digital recorder</p></div><p>To Whom It May Concern:</p><p>I purchased the Kishin XT20 digital recorder to record several days' worth of conference presentations. Now, after my first day at the event, I am trying to transfer the audio files to my laptop, but I am not having any luck. I have followed all the instructions in the user manual as well as the tips found in the FAQ section of the product's Web page. I have even tried alternative cords and the laptops in the hotel's business center, so I do not believe computer hardware to be the issue.</p><p>I am supposed to cover the remaining two days of this conference for work. My business partners expect me to return with as much information as I can. The Kishin XT20 digital recorder is of no use to me if I cannot properly share the files. Can you please help?</p><p>Best regards,</p><p>Dmytro Petrov</p>"],"vi":"Người nhận: Bộ phận Chăm sóc Khách hàng <customerservice@kishintech.com>\nNgười gửi: Dmytro Petrov <d.petrov@silkmail.com>\nNgày: 5 tháng 11\nTiêu đề: Cần hỗ trợ với máy ghi âm kỹ thuật số Kishin XT20\n\nKính gửi Quý bộ phận:\n\nTôi đã mua máy ghi âm kỹ thuật số Kishin XT20 để ghi lại các bài thuyết trình trong một hội nghị kéo dài vài ngày. Giờ đây, sau ngày đầu tiên tham dự sự kiện, tôi đang cố chuyển các tệp âm thanh sang máy tính xách tay của mình nhưng không thành công. Tôi đã làm theo tất cả hướng dẫn trong sách hướng dẫn sử dụng cũng như các mẹo trong mục Câu hỏi thường gặp (FAQ) trên trang web của sản phẩm. Tôi thậm chí đã thử các dây cáp khác và cả máy tính xách tay ở trung tâm dịch vụ doanh nhân của khách sạn, vì vậy tôi không nghĩ phần cứng máy tính là nguyên nhân.\n\nTôi có nhiệm vụ đưa tin về hai ngày còn lại của hội nghị này cho công việc. Các đối tác kinh doanh của tôi mong tôi trở về với càng nhiều thông tin càng tốt. Máy ghi âm kỹ thuật số Kishin XT20 sẽ vô dụng với tôi nếu tôi không thể chia sẻ các tệp một cách bình thường. Quý vị có thể giúp tôi được không?\n\nTrân trọng,\n\nDmytro Petrov","qs":[{"n":168,"q":"What problem does Mr. Petrov have with his device?","qvi":"Anh Petrov gặp vấn đề gì với thiết bị của mình?","opts":["He cannot move audio files to his computer.","He dislikes its appearance.","He is unable to rename the files.","He is unsatisfied with the sound quality."],"ans":"A","xp":"Câu hỏi chi tiết. Đoạn 1: \"I am trying to transfer the audio files to my laptop, but I am not having any luck.\" → không chuyển được tệp âm thanh sang máy tính (transfer → move; laptop → computer) → chọn (A). Không nhắc đến ngoại hình, đổi tên tệp hay chất lượng âm thanh.\n(A) Anh ấy không thể chuyển tệp âm thanh sang máy tính.\n(B) Anh ấy không thích vẻ ngoài của nó.\n(C) Anh ấy không thể đổi tên các tệp.\n(D) Anh ấy không hài lòng với chất lượng âm thanh."},{"n":169,"q":"Why does Mr. Petrov mention a Web page?","qvi":"Tại sao anh Petrov nhắc đến một trang web?","opts":["To suggest that an image is misleading","To explain that he obtained additional information","To recommend changing a product description","To inquire about compatible accessories"],"ans":"B","xp":"Câu hỏi mục đích (lý do nhắc chi tiết). Anh ấy viết: \"I have followed all the instructions in the user manual as well as the tips found in the FAQ section of the product's Web page.\" → ngoài sách hướng dẫn, anh ấy còn tìm thêm mẹo trên trang web = đã tham khảo thêm thông tin → chọn (B). Không chê hình ảnh, không đề nghị sửa mô tả hay hỏi phụ kiện.\n(A) Để cho rằng một hình ảnh gây hiểu lầm\n(B) Để giải thích rằng anh ấy đã tìm thêm thông tin\n(C) Để đề nghị thay đổi phần mô tả sản phẩm\n(D) Để hỏi về các phụ kiện tương thích"},{"n":170,"q":"The word \"cover\" in paragraph 2, line 1, is closest in meaning to","qvi":"Từ \"cover\" ở đoạn 2, dòng 1 gần nghĩa nhất với","opts":["protect","contain","extend over","report on"],"ans":"D","xp":"Câu hỏi đồng nghĩa. Câu gốc: \"I am supposed to cover the remaining two days of this conference for work. My business partners expect me to return with as much information as I can.\" → 'cover' ở đây là ghi nhận/đưa tin về hội nghị để mang thông tin về → report on → chọn (D). Các nghĩa khác của cover như 'che chắn, bảo vệ' (protect), 'bao gồm' (contain), 'trải dài' (extend over) không hợp ngữ cảnh.\n(A) bảo vệ\n(B) chứa, bao gồm\n(C) trải dài trên\n(D) đưa tin, tường thuật về"},{"n":171,"q":"What is true about Mr. Petrov?","qvi":"Điều gì đúng về anh Petrov?","opts":["He volunteered to try some equipment.","He is currently traveling with his business partners.","He will share conference material with his colleagues.","He will soon receive a new laptop from his company."],"ans":"C","xp":"Câu hỏi chi tiết (thông tin đúng). Đoạn 2: \"My business partners expect me to return with as much information as I can. The Kishin XT20 digital recorder is of no use to me if I cannot properly share the files.\" → anh ấy sẽ chia sẻ tài liệu hội nghị (các tệp ghi âm) với đồng nghiệp → chọn (C). (B) sai: đối tác chờ anh ấy 'return' (trở về), tức họ không đi cùng; (A) và (D) không được nhắc.\n(A) Anh ấy tình nguyện dùng thử một số thiết bị.\n(B) Anh ấy hiện đang đi công tác cùng các đối tác kinh doanh.\n(C) Anh ấy sẽ chia sẻ tài liệu hội nghị với đồng nghiệp.\n(D) Anh ấy sắp nhận một máy tính xách tay mới từ công ty."}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Kristin Burton (8:16 A.M.)</b></p><p>This is my first time posting on this small-business forum. Has anyone here experienced problems when ordering one of Atlara's credit card readers?</p></div><div class=\"msg\"><p><b>Marcos Menke (9:04 A.M.)</b></p><p>Are you referring to the little unit that attaches to your mobile phone or the larger, stand-alone tablet model?</p></div><div class=\"msg\"><p><b>Kristin Burton (9:30 A.M.)</b></p><p>The phone unit. I started an online shop using the Atlara Web hosting service and added pictures of the necklaces and rings I create. But most of my sales are still in person. So I just need a way to accept in-person payments when I'm out at fairs or markets.</p></div><div class=\"msg\"><p><b>Marcos Menke (10:19 A.M.)</b></p><p>Just go to www.atlara.com/pos/hardware and add what you want to your cart.</p></div><div class=\"msg\"><p><b>Kristin Burton (11:21 A.M.)</b></p><p>That's the problem. The system won't let me order it. I get the error message “Your account cannot be verified.”</p></div><div class=\"msg\"><p><b>Suzanne Shroer (11:42 A.M.)</b></p><p>I think I know. You have to upload scans of your business registration, a government photo ID, and a statement from your business bank account.</p></div><div class=\"msg\"><p><b>Kristin Burton (12:23 P.M.)</b></p><p>I already did all that, and I still got the error message.</p></div><div class=\"msg\"><p><b>Suzanne Shroer (12:33 P.M.)</b></p><p>If that is the case, try logging back in and following the process again.</p></div><div class=\"msg\"><p><b>Cindy Acosta (1:05 P.M.)</b></p><p>You probably need to call the support line. I found them to be very helpful with my issues a few months ago.</p></div><div class=\"msg\"><p><b>Kristin Burton (1:10 P.M.)</b></p><p>I've spoken with three people already.</p></div>"],"vi":"Kristin Burton (8:16 sáng): Đây là lần đầu tôi đăng bài trên diễn đàn doanh nghiệp nhỏ này. Có ai ở đây từng gặp vấn đề khi đặt mua một trong các máy đọc thẻ tín dụng của Atlara chưa?\n\nMarcos Menke (9:04 sáng): Chị đang nói đến thiết bị nhỏ gắn vào điện thoại di động hay mẫu máy tính bảng độc lập cỡ lớn hơn?\n\nKristin Burton (9:30 sáng): Thiết bị gắn điện thoại. Tôi đã mở một cửa hàng trực tuyến bằng dịch vụ lưu trữ web của Atlara và đăng ảnh những chiếc vòng cổ và nhẫn tôi làm. Nhưng phần lớn doanh số của tôi vẫn là bán trực tiếp. Vì vậy tôi chỉ cần một cách để nhận thanh toán trực tiếp khi tôi đi bán ở hội chợ hoặc chợ phiên.\n\nMarcos Menke (10:19 sáng): Chị chỉ cần vào www.atlara.com/pos/hardware và thêm thứ chị muốn vào giỏ hàng.\n\nKristin Burton (11:21 sáng): Vấn đề là ở đó. Hệ thống không cho tôi đặt mua. Tôi nhận được thông báo lỗi \"Không thể xác minh tài khoản của bạn.\"\n\nSuzanne Shroer (11:42 sáng): Tôi nghĩ là tôi biết rồi. Chị phải tải lên bản scan giấy đăng ký kinh doanh, giấy tờ tùy thân có ảnh do nhà nước cấp và một bản sao kê từ tài khoản ngân hàng doanh nghiệp của chị.\n\nKristin Burton (12:23 chiều): Tôi đã làm hết những việc đó rồi mà vẫn bị báo lỗi.\n\nSuzanne Shroer (12:33 chiều): Nếu vậy thì chị thử đăng nhập lại và làm lại quy trình xem.\n\nCindy Acosta (1:05 chiều): Có lẽ chị cần gọi đường dây hỗ trợ. Vài tháng trước tôi thấy họ giúp tôi giải quyết vấn đề rất tận tình.\n\nKristin Burton (1:10 chiều): Tôi đã nói chuyện với ba người rồi.","qs":[{"n":172,"q":"What does Mr. Menke ask Ms. Burton to clarify?","qvi":"Anh Menke yêu cầu cô Burton làm rõ điều gì?","opts":["The type of device she is trying to buy","The experience she had with a Web site","The way she charges her mobile phone","The amount she was charged for a service"],"ans":"A","xp":"Câu hỏi chi tiết. Lúc 9:04 anh Menke hỏi: \"Are you referring to the little unit that attaches to your mobile phone or the larger, stand-alone tablet model?\" → hỏi cô ấy muốn mua loại máy đọc thẻ nào → chọn (A). (C) 'charge' ở đây là bẫy: anh ấy không hỏi cách sạc điện thoại.\n(A) Loại thiết bị cô ấy đang muốn mua\n(B) Trải nghiệm của cô ấy với một trang web\n(C) Cách cô ấy sạc điện thoại di động\n(D) Số tiền cô ấy bị tính cho một dịch vụ"},{"n":173,"q":"What does Ms. Burton sell?","qvi":"Cô Burton bán gì?","opts":["Art supplies","Board games","Jewelry","Furniture"],"ans":"C","xp":"Câu hỏi chi tiết. Lúc 9:30 cô Burton viết: \"added pictures of the necklaces and rings I create\" → vòng cổ và nhẫn = trang sức (jewelry) → chọn (C).\n(A) Đồ dùng mỹ thuật\n(B) Trò chơi cờ bàn\n(C) Trang sức\n(D) Đồ nội thất"},{"n":174,"q":"What does Ms. Shroer suggest?","qvi":"Cô Shroer đề xuất điều gì?","opts":["Filling out a service request","Adjusting a card reader's settings","Submitting some documentation","Creating a separate business account"],"ans":"C","xp":"Câu hỏi chi tiết (đề xuất). Lúc 11:42 cô Shroer viết: \"You have to upload scans of your business registration, a government photo ID, and a statement from your business bank account.\" → tải lên giấy đăng ký kinh doanh, giấy tờ tùy thân, sao kê ngân hàng = nộp một số giấy tờ (documentation) → chọn (C). Sau đó cô ấy chỉ khuyên đăng nhập lại, không nói điền yêu cầu dịch vụ, chỉnh cài đặt hay tạo tài khoản mới.\n(A) Điền một phiếu yêu cầu dịch vụ\n(B) Điều chỉnh cài đặt của máy đọc thẻ\n(C) Nộp một số giấy tờ\n(D) Tạo một tài khoản doanh nghiệp riêng"},{"n":175,"q":"At 1:10 P.M., what does Ms. Burton most likely mean when she writes, \"I've spoken with three people already\"?","qvi":"Lúc 1:10 chiều, khi cô Burton viết \"I've spoken with three people already\" (Tôi đã nói chuyện với ba người rồi), nhiều khả năng cô ấy có ý gì?","opts":["She is impressed with a company's response.","She has previously called the support line.","She has thoroughly researched some specifications.","She has confirmed that the product was shipped."],"ans":"B","xp":"Câu hỏi hàm ý. Ngay trước đó (1:05) cô Acosta khuyên: \"You probably need to call the support line.\" Cô Burton đáp đã nói chuyện với ba người rồi → ý là cô ấy đã gọi đường dây hỗ trợ (và vẫn chưa giải quyết được) → chọn (B). Cô ấy không hề hài lòng (A); vấn đề vẫn là chưa đặt được hàng nên không thể đã giao (D).\n(A) Cô ấy ấn tượng với phản hồi của một công ty.\n(B) Cô ấy đã gọi đường dây hỗ trợ trước đó.\n(C) Cô ấy đã tìm hiểu kỹ một số thông số kỹ thuật.\n(D) Cô ấy đã xác nhận rằng sản phẩm đã được giao đi."}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following Web page and e-mail.","passages":["<p><i>https://www.sunnywelcomehotel.co.in</i></p><p>At the Sunny Welcome Hotel in Kolkata, we work hard to ensure that you enjoy your stay.</p><p>Please note:</p><ul><li>Each room has a coffeemaker and complimentary coffee and tea. Guests may purchase snacks and other beverages in the vending areas located on each floor.</li><li>Guests with small children may request a rollaway bed or crib for their rooms for no additional charge.</li><li>The business center is open from 9:00 A.M. to 5:00 P.M. each day.</li><li>The swimming pool and children’s playground are open during daylight hours. Children must always be supervised by an adult.</li><li>A deposit is necessary to guarantee a room reservation. The deposit will only be refunded if the reservation is cancelled or changed more than 24 hours prior to arrival.</li><li>Guests may check in as early as 2:00 P.M. Checkout after noon on the day of departure is subject to an additional charge.</li><li>Guests are required to present a passport or driver’s license at the time of check-in.</li><li>We offer free shuttle service to the airport. Guests can make arrangements at the front desk.</li><li>Our reception desk is staffed 24 hours a day.</li></ul>","<div class=\"hdr\"><p><b>To:</b> generalmanager@sunnywelcomehotel.co.in</p><p><b>From:</b> samuelramon@myemail.co.uk</p><p><b>Date:</b> 13 May</p><p><b>Subject:</b> Reservation number EX52417</p></div><p>Hello,</p><p>My family and I were very comfortable in the family suite at the Sunny Welcome Hotel in Kolkata last year, and we were looking forward to returning this year for a week starting on 17 April. Unfortunately, we suddenly had to postpone our trip until June, so I called the hotel on the morning of 17 April to change our reservation dates. I thought everything was in order, but when I opened my credit card statement this month, I discovered an additional charge from the Sunny Welcome Hotel.</p><p>Could you please look into the matter? I believe that an error has been made and that I should be reimbursed. I would appreciate having the money credited to my account. We still plan to return to Kolkata later this year and anticipate an enjoyable stay at your hotel.</p><p>Yours sincerely,</p><p>Samuel Ramon</p>"],"vi":"https://www.sunnywelcomehotel.co.in\n\nTại khách sạn Sunny Welcome ở Kolkata, chúng tôi nỗ lực hết mình để đảm bảo quý khách có kỳ lưu trú vui vẻ.\n\nXin lưu ý:\n• Mỗi phòng đều có máy pha cà phê cùng cà phê và trà miễn phí. Khách có thể mua đồ ăn vặt và đồ uống khác tại khu máy bán hàng tự động ở mỗi tầng.\n• Khách có con nhỏ có thể yêu cầu giường phụ có bánh xe hoặc nôi cho phòng mà không mất thêm phí.\n• Trung tâm dịch vụ văn phòng (business center) mở cửa từ 9:00 sáng đến 5:00 chiều mỗi ngày.\n• Hồ bơi và sân chơi trẻ em mở cửa vào ban ngày. Trẻ em phải luôn có người lớn giám sát.\n• Cần đặt cọc để giữ chỗ đặt phòng. Tiền cọc chỉ được hoàn lại nếu việc đặt phòng bị hủy hoặc thay đổi trước giờ đến hơn 24 tiếng.\n• Khách có thể nhận phòng sớm nhất từ 2:00 chiều. Trả phòng sau buổi trưa vào ngày rời đi sẽ bị tính thêm phí.\n• Khách phải xuất trình hộ chiếu hoặc bằng lái xe khi nhận phòng.\n• Chúng tôi có dịch vụ xe đưa đón miễn phí ra sân bay. Khách có thể sắp xếp tại quầy lễ tân.\n• Quầy lễ tân của chúng tôi có nhân viên trực 24 giờ mỗi ngày.\n\nNgười nhận: generalmanager@sunnywelcomehotel.co.in\nNgười gửi: samuelramon@myemail.co.uk\nNgày: 13 tháng 5\nTiêu đề: Mã đặt phòng EX52417\n\nXin chào,\n\nNăm ngoái gia đình tôi đã ở rất thoải mái trong phòng suite gia đình tại khách sạn Sunny Welcome ở Kolkata, và chúng tôi đã mong chờ được quay lại vào năm nay trong một tuần bắt đầu từ ngày 17 tháng 4. Thật không may, chúng tôi đột ngột phải hoãn chuyến đi đến tháng Sáu, vì vậy tôi đã gọi cho khách sạn vào sáng ngày 17 tháng 4 để đổi ngày đặt phòng. Tôi tưởng mọi việc đã ổn, nhưng khi mở bảng sao kê thẻ tín dụng tháng này, tôi phát hiện một khoản phí phát sinh từ khách sạn Sunny Welcome.\n\nÔng/bà có thể xem xét giúp vấn đề này không? Tôi tin rằng đã có sai sót và tôi nên được hoàn tiền. Tôi rất mong số tiền được hoàn vào tài khoản của tôi. Chúng tôi vẫn dự định quay lại Kolkata vào cuối năm nay và mong có một kỳ nghỉ thú vị tại khách sạn của quý vị.\n\nTrân trọng,\n\nSamuel Ramon","qs":[{"n":176,"q":"According to the Web page, what are hotel guests asked to provide at check-in?","qvi":"Theo trang web, khách của khách sạn được yêu cầu cung cấp gì khi nhận phòng?","opts":["A home address","Payment in advance","Proof of identification","A confirmation number"],"ans":"C","xp":"Câu hỏi chi tiết. Trang web: \"Guests are required to present a passport or driver's license at the time of check-in.\" (Khách phải xuất trình hộ chiếu hoặc bằng lái xe khi nhận phòng). Hộ chiếu / bằng lái là giấy tờ tùy thân → paraphrase thành \"Proof of identification\" → (C). Tiền cọc (deposit) là để giữ phòng khi đặt, không phải khi check-in; địa chỉ nhà và mã xác nhận không được nhắc tới.\n(A) Địa chỉ nhà\n(B) Thanh toán trước\n(C) Giấy tờ chứng minh nhân thân\n(D) Mã xác nhận"},{"n":177,"q":"What is NOT included with a stay at the Sunny Welcome Hotel?","qvi":"Điều gì KHÔNG được bao gồm khi lưu trú tại khách sạn Sunny Welcome?","opts":["Hot beverages","A light breakfast","Airport shuttle service","Use of a swimming pool"],"ans":"B","xp":"Câu hỏi NOT. (A) đồ uống nóng: \"complimentary coffee and tea\" (cà phê và trà miễn phí). (C) xe đưa đón sân bay: \"We offer free shuttle service to the airport\". (D) hồ bơi: \"The swimming pool ... open during daylight hours\". Bữa sáng nhẹ hoàn toàn không được nhắc tới → (B).\n(A) Đồ uống nóng\n(B) Bữa sáng nhẹ\n(C) Dịch vụ xe đưa đón sân bay\n(D) Sử dụng hồ bơi"},{"n":178,"q":"What does Mr. Ramon indicate in his e-mail?","qvi":"Ông Ramon cho biết điều gì trong e-mail của mình?","opts":["He usually travels alone.","He has family living in Kolkata.","He is planning to move to Kolkata.","He has stayed at the Sunny Welcome Hotel before."],"ans":"D","xp":"Câu hỏi chi tiết. E-mail: \"My family and I were very comfortable in the family suite at the Sunny Welcome Hotel in Kolkata last year, and we were looking forward to returning this year\" → năm ngoái ông đã ở khách sạn này và muốn quay lại → (D). (A) sai vì ông đi cùng gia đình; (B), (C) không được nhắc tới — ông chỉ định quay lại Kolkata du lịch.\n(A) Ông ấy thường đi du lịch một mình.\n(B) Ông ấy có người thân sống ở Kolkata.\n(C) Ông ấy dự định chuyển đến Kolkata.\n(D) Ông ấy đã từng ở khách sạn Sunny Welcome trước đây."},{"n":179,"q":"Why most likely was Mr. Ramon charged a fee by the Sunny Welcome Hotel?","qvi":"Nhiều khả năng vì sao ông Ramon bị khách sạn Sunny Welcome tính phí?","opts":["He canceled a reservation less than a day before arrival.","He requested a rollaway bed for his room.","He checked out of his room after midday.","He reserved a work space in the business center."],"ans":"A","xp":"Câu hỏi suy luận (liên kết 2 văn bản). E-mail: kỳ nghỉ bắt đầu \"on 17 April\" nhưng ông \"called the hotel on the morning of 17 April to change our reservation dates\" → ông đổi/hủy lịch ngay trong ngày đến. Trang web: \"The deposit will only be refunded if the reservation is cancelled or changed more than 24 hours prior to arrival.\" → ông báo chưa tới 24 tiếng trước khi đến nên mất tiền cọc → (A). (B) giường phụ miễn phí; (C), (D) ông chưa hề đến ở nên không thể trả phòng muộn hay dùng business center.\n(A) Ông ấy hủy đặt phòng chưa đầy một ngày trước khi đến.\n(B) Ông ấy yêu cầu giường phụ cho phòng.\n(C) Ông ấy trả phòng sau buổi trưa.\n(D) Ông ấy đặt chỗ làm việc ở trung tâm dịch vụ văn phòng."},{"n":180,"q":"What does Mr. Ramon request?","qvi":"Ông Ramon yêu cầu điều gì?","opts":["A credit to his account","A discount on a future hotel stay","A room upgrade to a family suite","An extension of a hotel stay"],"ans":"A","xp":"Câu hỏi chi tiết. E-mail: \"I should be reimbursed. I would appreciate having the money credited to my account.\" (Tôi rất mong số tiền được hoàn vào tài khoản) → (A). Ông không xin giảm giá, nâng hạng phòng hay ở thêm ngày.\n(A) Hoàn tiền vào tài khoản của ông ấy\n(B) Giảm giá cho lần lưu trú sau\n(C) Nâng hạng lên phòng suite gia đình\n(D) Gia hạn thời gian lưu trú"}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following e-mail and Web page.","passages":["<div class=\"hdr\"><p><b>From:</b> Dexter Abbott</p><p><b>To:</b> Nina Sosa</p><p><b>Date:</b> 20 August</p><p><b>Subject:</b> Next steps</p></div><p>Dear Ms. Sosa,</p><p>I have good news. The plans for the layout of the new Fountain Road office building have just been approved by Lanfei Chan at our corporate office. We now need to start thinking about the artwork for the main open-plan office area on the third floor of the building. This is one of our last tasks before the office opens in October.</p><p>I have heard that Red Starling Art has a good reputation for helping with office interiors. Could you look at the company’s Web site today and find out if any of its services might be suitable for us? I am wondering whether photography or paintings would look best in the space. What do you think? I am still waiting to hear back from Maxwell Willis in Finance about the budget for art, so please do not agree to anything with Red Starling Art until we know more.</p><p>Thank you,</p><p>Dexter Abbott, Facilities Manager<br>KLX Accountancy</p>","<p><i>https://www.redstarlingart.co.uk/offices/</i></p><p>Home | About Us | <b>Services</b> | Contact Us</p><p>Red Starling Art offers a range of consultancy services for office buildings:</p><ul><li><b>Remake:</b> For clients who want a complete redesign of the interior of their office, we work with you to create a layout and decoration scheme that meets your needs.</li><li><b>Align:</b> For clients looking to incorporate artwork into a new office, we help you find the right pieces (paintings, photographs, prints, or sculptures) for your space.</li><li><b>Connect:</b> For clients who want to add a local touch to their offices, we collaborate with area artists and photographers to bring their unique perspective to you.</li><li><b>Reframe:</b> For clients who want to update but keep their existing artwork, we suggest new framing, new lighting, or new arrangements for a fresh look.</li></ul><p>Our work is always tailored to the specific needs of our clients, so we cannot provide fixed prices. Please e-mail Birgit Lowenbruck at blowenbruck@redstarlingart.co.uk to book a free consultation. After the consultation, she will provide you with an estimate for the agreed-upon services.</p>"],"vi":"Người gửi: Dexter Abbott\nNgười nhận: Nina Sosa\nNgày: 20 tháng 8\nTiêu đề: Các bước tiếp theo\n\nChị Sosa thân mến,\n\nTôi có tin vui. Bản thiết kế bố trí cho tòa nhà văn phòng mới trên đường Fountain vừa được chị Lanfei Chan ở văn phòng tổng công ty phê duyệt. Giờ chúng ta cần bắt đầu tính đến tác phẩm nghệ thuật cho khu văn phòng mở chính ở tầng ba của tòa nhà. Đây là một trong những việc cuối cùng của chúng ta trước khi văn phòng khai trương vào tháng Mười.\n\nTôi nghe nói Red Starling Art có tiếng tốt trong việc hỗ trợ trang trí nội thất văn phòng. Chị có thể xem trang web của công ty đó ngay hôm nay và tìm hiểu xem có dịch vụ nào phù hợp với chúng ta không? Tôi đang phân vân không biết ảnh chụp hay tranh vẽ sẽ hợp nhất với không gian đó. Chị nghĩ sao? Tôi vẫn đang chờ anh Maxwell Willis bên phòng Tài chính phản hồi về ngân sách cho nghệ thuật, vì vậy xin chị đừng đồng ý bất cứ điều gì với Red Starling Art cho đến khi chúng ta biết thêm.\n\nCảm ơn chị,\n\nDexter Abbott, Quản lý cơ sở vật chất\nKLX Accountancy\n\nhttps://www.redstarlingart.co.uk/offices/\nTrang chủ | Giới thiệu | Dịch vụ | Liên hệ\n\nRed Starling Art cung cấp nhiều dịch vụ tư vấn cho các tòa nhà văn phòng:\n• Remake: Dành cho khách hàng muốn thiết kế lại toàn bộ nội thất văn phòng, chúng tôi cùng bạn tạo ra cách bố trí và phương án trang trí đáp ứng nhu cầu của bạn.\n• Align: Dành cho khách hàng muốn đưa tác phẩm nghệ thuật vào văn phòng mới, chúng tôi giúp bạn tìm những tác phẩm phù hợp (tranh vẽ, ảnh chụp, tranh in hoặc tượng điêu khắc) cho không gian của bạn.\n• Connect: Dành cho khách hàng muốn thêm nét địa phương cho văn phòng, chúng tôi hợp tác với các nghệ sĩ và nhiếp ảnh gia trong khu vực để mang góc nhìn độc đáo của họ đến với bạn.\n• Reframe: Dành cho khách hàng muốn làm mới nhưng vẫn giữ tác phẩm nghệ thuật hiện có, chúng tôi đề xuất khung mới, ánh sáng mới hoặc cách sắp xếp mới để có diện mạo tươi mới.\n\nCông việc của chúng tôi luôn được điều chỉnh theo nhu cầu cụ thể của từng khách hàng, vì vậy chúng tôi không thể đưa ra giá cố định. Vui lòng gửi e-mail cho chị Birgit Lowenbruck theo địa chỉ blowenbruck@redstarlingart.co.uk để đặt lịch tư vấn miễn phí. Sau buổi tư vấn, chị ấy sẽ gửi bạn bảng báo giá cho các dịch vụ đã thống nhất.","qs":[{"n":181,"q":"What is suggested about the Fountain Road office building?","qvi":"Có thể suy ra điều gì về tòa nhà văn phòng trên đường Fountain?","opts":["It opened last October.","It is the corporate headquarters of KLX Accountancy.","It has more than one floor.","It has a conference center."],"ans":"C","xp":"Câu hỏi suy luận. E-mail: \"the main open-plan office area on the third floor of the building\" → tòa nhà có ít nhất ba tầng → nhiều hơn một tầng → (C). (A) sai: văn phòng sẽ khai trương \"in October\" (sắp tới), chưa mở. (B) sai: trụ sở là \"our corporate office\" nơi chị Chan làm việc, khác với tòa nhà mới. (D) không được nhắc tới.\n(A) Nó khai trương vào tháng Mười năm ngoái.\n(B) Nó là trụ sở chính của KLX Accountancy.\n(C) Nó có nhiều hơn một tầng.\n(D) Nó có trung tâm hội nghị."},{"n":182,"q":"In the e-mail, what does Mr. Abbott ask Ms. Sosa to do?","qvi":"Trong e-mail, ông Abbott yêu cầu chị Sosa làm gì?","opts":["Finish a task she started last week","Approve plans for the layout of an office","Agree to a price for purchasing artwork","Research interior design options online"],"ans":"D","xp":"Câu hỏi chi tiết. E-mail: \"Could you look at the company's Web site today and find out if any of its services might be suitable for us?\" → xem trang web của công ty trang trí nội thất để tìm dịch vụ phù hợp = tìm hiểu các lựa chọn thiết kế nội thất trên mạng → (D). (B) sai: bản bố trí đã được chị Chan duyệt rồi. (C) sai: ông dặn \"please do not agree to anything\". (A) không được nhắc tới.\n(A) Hoàn thành công việc chị ấy bắt đầu tuần trước\n(B) Phê duyệt bản bố trí văn phòng\n(C) Đồng ý một mức giá để mua tác phẩm nghệ thuật\n(D) Tìm hiểu các lựa chọn thiết kế nội thất trên mạng"},{"n":183,"q":"Who is responsible for the budget for artwork?","qvi":"Ai chịu trách nhiệm về ngân sách cho tác phẩm nghệ thuật?","opts":["Mr. Abbott","Ms. Chan","Mr. Willis","Ms. Sosa"],"ans":"C","xp":"Câu hỏi chi tiết. E-mail: \"I am still waiting to hear back from Maxwell Willis in Finance about the budget for art\" → anh Willis ở phòng Tài chính phụ trách ngân sách cho nghệ thuật → (C). Chị Chan chỉ duyệt bản bố trí; ông Abbott là quản lý cơ sở vật chất; chị Sosa là người được nhờ tìm hiểu.\n(A) Ông Abbott\n(B) Chị Chan\n(C) Anh Willis\n(D) Chị Sosa"},{"n":184,"q":"What Red Starling Art service would be most suitable for the Fountain Road office building?","qvi":"Dịch vụ nào của Red Starling Art phù hợp nhất với tòa nhà văn phòng trên đường Fountain?","opts":["Remake","Align","Connect","Reframe"],"ans":"B","xp":"Câu hỏi suy luận (liên kết 2 văn bản). E-mail: đây là tòa nhà văn phòng mới (\"the new Fountain Road office building\"), bố trí đã được duyệt, giờ chỉ cần chọn \"artwork\" và ông phân vân giữa \"photography or paintings\". Trang web: \"Align: For clients looking to incorporate artwork into a new office, we help you find the right pieces (paintings, photographs, prints, or sculptures)\" → khớp hoàn toàn → (B). Remake là thiết kế lại toàn bộ (không cần vì đã có bố trí); Connect nhấn mạnh nghệ sĩ địa phương (không được yêu cầu); Reframe dành cho tác phẩm đã có sẵn.\n(A) Remake (Thiết kế lại)\n(B) Align (Chọn tác phẩm phù hợp)\n(C) Connect (Kết nối nghệ sĩ địa phương)\n(D) Reframe (Làm mới tác phẩm sẵn có)"},{"n":185,"q":"According to the Web page, how can someone learn the cost of Red Starling Art's services?","qvi":"Theo trang web, làm thế nào để biết chi phí dịch vụ của Red Starling Art?","opts":["By submitting information through the Contact Us page","By going to a Web page with cost information","By submitting a document to Ms. Lowenbruck","By attending a consultation with Ms. Lowenbruck"],"ans":"D","xp":"Câu hỏi chi tiết. Trang web: \"we cannot provide fixed prices. Please e-mail Birgit Lowenbruck ... to book a free consultation. After the consultation, she will provide you with an estimate\" → muốn biết giá thì phải tham gia buổi tư vấn với chị Lowenbruck, sau đó chị ấy báo giá (estimate) → (D). (B) sai vì không có giá cố định; (A), (C) không được nhắc tới (chỉ cần e-mail để đặt lịch, không phải nộp tài liệu).\n(A) Bằng cách gửi thông tin qua trang Liên hệ\n(B) Bằng cách vào trang web có thông tin giá\n(C) Bằng cách nộp tài liệu cho chị Lowenbruck\n(D) Bằng cách tham dự buổi tư vấn với chị Lowenbruck"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following e-mail and memos.","passages":["<div class=\"hdr\"><p><b>To:</b> jdixon@milkalenterprises.com</p><p><b>From:</b> humanresources@milkalenterprises.com</p><p><b>Date:</b> April 28</p><p><b>Subject:</b> Employee survey responses</p></div><p>Dear Ms. Dixon,</p><p>I read through all the responses to the semiannual employee survey, and I want to highlight a few points that were repeatedly raised. We can use this list of suggestions to help determine our priorities.</p><p>Suggestion 1. A more flexible policy for working from home<br>Suggestion 2. An expanded in-office recycling strategy<br>Suggestion 3. More financial rewards for excellent work<br>Suggestion 4. More opportunities for technical training</p><p>Also, if you approve, I would like to simplify the survey form before we administer it again. The open-ended questions make the data difficult to analyze. I propose incorporating more yes-no questions or rating scales to determine how much a colleague agrees or disagrees with a statement.</p><p>Kind regards,</p><p>Judith Hathaway, Human Resources</p>","<h3>MEMO</h3><div class=\"hdr\"><p><b>To:</b> All Staff</p><p><b>From:</b> Jenna Dixon, General Manager</p><p><b>Date:</b> May 8</p><p><b>Subject:</b> Volunteers needed</p></div><p>I am seeking volunteers to form a committee that will launch an office recycling program. Having such a program was one of the most frequently identified needs mentioned on the recent employee survey. This program will prevent recyclables, including plastics, glass, metal, paper, and cardboard, from ending up in landfills.</p><p>Also, we need a volunteer to be the coordinator of this committee. I will be happy to meet with this coordinator to discuss first steps. Note that time spent on coordination tasks would be in addition to your regular work duties. A small amount of funds will be made available to be spent on program setup costs.</p>","<h3>MEMO</h3><div class=\"hdr\"><p><b>To:</b> All Staff</p><p><b>From:</b> Mohammad Asghari</p><p><b>Date:</b> June 13</p><p><b>Subject:</b> Bins are here</p></div><p>As chairperson of the In-office Recycling Committee, I am happy to report that we now have recycling bins in the kitchen for glass bottles, soda cans, and cardboard and paper. It took us some time to get this program started because finding containers narrow enough to squeeze three between the door and the refrigerator proved challenging. But I was finally able to purchase some.</p><p>Please note that the recycling facility we are working with has stringent guidelines on what they accept, so I am creating illustrated instructions to hang above each bin. Those will be up tomorrow, and committee members will be monitoring our collection system to make sure the program is going smoothly. Please contact me with any questions, concerns, or feedback.</p>"],"vi":"Người nhận: jdixon@milkalenterprises.com\nNgười gửi: humanresources@milkalenterprises.com\nNgày: 28 tháng 4\nTiêu đề: Phản hồi khảo sát nhân viên\n\nChị Dixon thân mến,\n\nTôi đã đọc hết các phản hồi của cuộc khảo sát nhân viên định kỳ nửa năm một lần, và tôi muốn nêu bật một vài điểm được nhắc đi nhắc lại nhiều lần. Chúng ta có thể dùng danh sách đề xuất này để giúp xác định các ưu tiên của mình.\n\nĐề xuất 1. Chính sách làm việc tại nhà linh hoạt hơn\nĐề xuất 2. Mở rộng chiến lược tái chế trong văn phòng\nĐề xuất 3. Thêm phần thưởng tài chính cho thành tích xuất sắc\nĐề xuất 4. Thêm cơ hội đào tạo kỹ thuật\n\nNgoài ra, nếu chị đồng ý, tôi muốn đơn giản hóa mẫu khảo sát trước khi tiến hành lại. Các câu hỏi mở khiến dữ liệu khó phân tích. Tôi đề nghị đưa vào nhiều câu hỏi có/không hoặc thang đánh giá hơn để xác định mức độ một đồng nghiệp đồng ý hay không đồng ý với một nhận định.\n\nTrân trọng,\n\nJudith Hathaway, phòng Nhân sự\n\nBẢN GHI NHỚ\nGửi: Toàn thể nhân viên\nTừ: Jenna Dixon, Tổng Giám đốc\nNgày: 8 tháng 5\nTiêu đề: Cần tình nguyện viên\n\nTôi đang tìm tình nguyện viên để thành lập một ủy ban sẽ triển khai chương trình tái chế tại văn phòng. Có một chương trình như vậy là một trong những nhu cầu được nêu ra thường xuyên nhất trong cuộc khảo sát nhân viên gần đây. Chương trình này sẽ ngăn các vật liệu có thể tái chế, gồm nhựa, thủy tinh, kim loại, giấy và bìa các-tông, bị đưa đến bãi chôn lấp.\n\nNgoài ra, chúng tôi cần một tình nguyện viên làm điều phối viên của ủy ban này. Tôi sẵn lòng gặp điều phối viên để bàn các bước đầu tiên. Lưu ý rằng thời gian dành cho công việc điều phối sẽ là thêm vào ngoài nhiệm vụ công việc thường ngày của bạn. Một khoản kinh phí nhỏ sẽ được cấp để chi cho chi phí thiết lập chương trình.\n\nBẢN GHI NHỚ\nGửi: Toàn thể nhân viên\nTừ: Mohammad Asghari\nNgày: 13 tháng 6\nTiêu đề: Thùng rác đã có\n\nVới tư cách chủ tịch Ủy ban Tái chế trong Văn phòng, tôi vui mừng thông báo rằng chúng ta đã có các thùng tái chế trong nhà bếp dành cho chai thủy tinh, lon nước ngọt, và bìa các-tông cùng giấy. Chúng tôi mất một thời gian mới khởi động được chương trình này vì việc tìm được những thùng đủ hẹp để nhét vừa ba cái vào khoảng giữa cửa ra vào và tủ lạnh hóa ra rất khó khăn. Nhưng cuối cùng tôi cũng mua được.\n\nXin lưu ý rằng cơ sở tái chế mà chúng ta hợp tác có quy định nghiêm ngặt về những gì họ nhận, vì vậy tôi đang làm các bảng hướng dẫn có minh họa để treo phía trên mỗi thùng. Chúng sẽ được treo lên vào ngày mai, và các thành viên ủy ban sẽ theo dõi hệ thống thu gom để đảm bảo chương trình diễn ra suôn sẻ. Vui lòng liên hệ tôi nếu có bất kỳ câu hỏi, băn khoăn hoặc góp ý nào.","qs":[{"n":186,"q":"In the e-mail, how does Ms. Hathaway suggest improving future surveys?","qvi":"Trong e-mail, chị Hathaway đề xuất cải thiện các cuộc khảo sát sau này bằng cách nào?","opts":["By changing the format of some questions","By collecting the responses anonymously","By conducting them more frequently","By using specialized software"],"ans":"A","xp":"Câu hỏi chi tiết. E-mail: \"The open-ended questions make the data difficult to analyze. I propose incorporating more yes-no questions or rating scales\" → thay câu hỏi mở bằng câu hỏi có/không hoặc thang đánh giá = thay đổi hình thức một số câu hỏi → (A). Ẩn danh, khảo sát thường xuyên hơn, phần mềm chuyên dụng đều không được nhắc tới.\n(A) Bằng cách thay đổi hình thức của một số câu hỏi\n(B) Bằng cách thu thập câu trả lời ẩn danh\n(C) Bằng cách tiến hành khảo sát thường xuyên hơn\n(D) Bằng cách dùng phần mềm chuyên dụng"},{"n":187,"q":"What suggestion from the survey results is Ms. Dixon acting on?","qvi":"Chị Dixon đang thực hiện đề xuất nào từ kết quả khảo sát?","opts":["Suggestion 1","Suggestion 2","Suggestion 3","Suggestion 4"],"ans":"B","xp":"Câu hỏi liên kết 2 văn bản. Bản ghi nhớ của chị Dixon: \"I am seeking volunteers to form a committee that will launch an office recycling program. Having such a program was one of the most frequently identified needs mentioned on the recent employee survey.\" E-mail: \"Suggestion 2. An expanded in-office recycling strategy\" → chương trình tái chế tương ứng với Đề xuất 2 → (B).\n(A) Đề xuất 1 (làm việc tại nhà linh hoạt)\n(B) Đề xuất 2 (tái chế trong văn phòng)\n(C) Đề xuất 3 (thưởng tài chính)\n(D) Đề xuất 4 (đào tạo kỹ thuật)"},{"n":188,"q":"According to Mr. Asghari, why was a new program delayed?","qvi":"Theo anh Asghari, vì sao chương trình mới bị chậm trễ?","opts":["Some orders took a long time to be processed.","Some equipment needed to be moved.","A coordinator needed to approve it.","A room had space limitations."],"ans":"D","xp":"Câu hỏi chi tiết. Bản ghi nhớ thứ hai: \"It took us some time to get this program started because finding containers narrow enough to squeeze three between the door and the refrigerator proved challenging.\" → khó tìm thùng đủ hẹp để nhét vừa giữa cửa và tủ lạnh = căn bếp bị hạn chế về không gian → (D). Không nhắc đến đơn hàng xử lý chậm, di chuyển thiết bị hay chờ điều phối viên duyệt.\n(A) Một số đơn hàng mất nhiều thời gian để xử lý.\n(B) Một số thiết bị cần được di chuyển.\n(C) Một điều phối viên cần phê duyệt nó.\n(D) Một căn phòng bị hạn chế về không gian."},{"n":189,"q":"What is suggested about Mr. Asghari?","qvi":"Có thể suy ra điều gì về anh Asghari?","opts":["He has led a training series on recycling.","He paid for some items using the company's money.","He meets with Ms. Dixon on a weekly basis.","He was acknowledged in a company newsletter."],"ans":"B","xp":"Câu hỏi suy luận (liên kết 2 văn bản). Bản ghi nhớ của chị Dixon: \"A small amount of funds will be made available to be spent on program setup costs.\" (công ty cấp một khoản kinh phí nhỏ cho chi phí thiết lập chương trình). Bản ghi nhớ của anh Asghari (chủ tịch ủy ban): \"I was finally able to purchase some\" (containers) → anh đã mua thùng bằng kinh phí công ty cấp → (B). Không có thông tin về chuỗi đào tạo, họp hằng tuần hay bản tin công ty.\n(A) Anh ấy đã dẫn dắt một loạt buổi đào tạo về tái chế.\n(B) Anh ấy đã dùng tiền của công ty để mua một số đồ.\n(C) Anh ấy gặp chị Dixon hằng tuần.\n(D) Anh ấy được ghi nhận trong bản tin công ty."},{"n":190,"q":"What is Mr. Asghari planning to do?","qvi":"Anh Asghari dự định làm gì?","opts":["Recruit volunteers","Contact suppliers","Display signs","Take inventory"],"ans":"C","xp":"Câu hỏi chi tiết. Bản ghi nhớ: \"I am creating illustrated instructions to hang above each bin. Those will be up tomorrow\" → anh sẽ treo bảng hướng dẫn có minh họa phía trên mỗi thùng = trưng bày biển báo → (C). Việc tìm tình nguyện viên là của chị Dixon trước đó; liên hệ nhà cung cấp, kiểm kê không được nhắc tới.\n(A) Tuyển tình nguyện viên\n(B) Liên hệ nhà cung cấp\n(C) Treo biển báo\n(D) Kiểm kê hàng hóa"}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following job advertisement, Web page, and review.","passages":["<p>Kooper’s Vision is seeking an optician for its eyewear department. Must have a valid Massachusetts optician license and at least three years of relevant experience. The position requires excellent customer service skills and a strong awareness of current fashion trends in the industry. Responsibilities include helping clients choose frames, ordering eyeglasses, and filing insurance claims.</p><p>This full-time position is available at Kooper’s Vision at Danvers Mall. Contact store manager Tanisha Mosley at 978-555-0101. Must be available to start during the last week of August.</p>","<p><i>https://www.koopersvision.com</i></p><h3>Kooper’s Vision at Danvers Mall</h3><h4>Hours:</h4><table><tr><td>Monday</td><td>10 A.M.–7 P.M.</td></tr><tr><td>Tuesday</td><td>10 A.M.–7 P.M.</td></tr><tr><td>Wednesday</td><td>10 A.M.–7 P.M.</td></tr><tr><td>Thursday</td><td>10 A.M.–7 P.M.</td></tr><tr><td>Friday</td><td>10 A.M.–7 P.M.</td></tr><tr><td>Saturday</td><td>10 A.M.–6 P.M.</td></tr><tr><td>Sunday</td><td>10 A.M.–4 P.M.</td></tr></table><p>During the month of August, enjoy 50% off the second pair of eyeglasses.</p><p>Kooper’s Vision is your local optical center for all your eye-care needs in Danvers, Massachusetts. We are located on the upper level of the Danvers Mall next to Eight Days Sporting Goods. Call 978-555-0101 today to schedule your annual eye exam. Exams by appointment only.</p>","<p>Optical Centers Reviews</p><p>Rating: 5 stars ★★★★★</p><p>I have been wearing eyeglasses since I was ten years old. I now have five children, and four of them wear glasses, so I have visited many opticians over the years. My recent visit to Kooper’s Vision on August 31 was, by far, the best.</p><p>Ms. Palmer offered her help when she saw that I was overwhelmed by the eyeglass selection at Kooper’s Vision. She looked at the shape of my face and steered me toward a few pairs of glasses that were perfect for me! She knew exactly what looked best on me and advised me about the size, color, quality, and cost of the frames I considered. Ms. Palmer also explained the different types of lenses and lens coatings available. I could not decide which was my favorite pair of eyeglasses, so I bought two pairs! I was incredulous when she told me it was her first day working at the store—she was the best optician I have ever had!</p><p>Melvin Drake</p>"],"vi":"Kooper's Vision đang tuyển một chuyên viên quang học (optician) cho bộ phận kính mắt. Ứng viên phải có giấy phép hành nghề quang học còn hiệu lực của bang Massachusetts và ít nhất ba năm kinh nghiệm liên quan. Vị trí này đòi hỏi kỹ năng chăm sóc khách hàng xuất sắc và am hiểu sâu về các xu hướng thời trang hiện nay trong ngành. Nhiệm vụ bao gồm giúp khách hàng chọn gọng kính, đặt kính và nộp hồ sơ yêu cầu bảo hiểm.\n\nVị trí toàn thời gian này làm việc tại Kooper's Vision ở trung tâm thương mại Danvers. Liên hệ quản lý cửa hàng Tanisha Mosley theo số 978-555-0101. Phải có thể bắt đầu làm việc trong tuần cuối cùng của tháng Tám.\n\nhttps://www.koopersvision.com\nKooper's Vision tại trung tâm thương mại Danvers\nGiờ mở cửa:\nThứ Hai – Thứ Sáu: 10 giờ sáng – 7 giờ tối\nThứ Bảy: 10 giờ sáng – 6 giờ chiều\nChủ Nhật: 10 giờ sáng – 4 giờ chiều\n\nTrong tháng Tám, được giảm 50% cho cặp kính thứ hai.\n\nKooper's Vision là trung tâm quang học địa phương đáp ứng mọi nhu cầu chăm sóc mắt của bạn tại Danvers, Massachusetts. Chúng tôi nằm ở tầng trên của trung tâm thương mại Danvers, cạnh cửa hàng đồ thể thao Eight Days. Hãy gọi 978-555-0101 ngay hôm nay để đặt lịch khám mắt định kỳ hằng năm. Chỉ khám mắt theo lịch hẹn.\n\nĐánh giá các trung tâm quang học\nXếp hạng: 5 sao\n\nTôi đeo kính từ năm mười tuổi. Hiện tôi có năm người con, và bốn đứa trong số đó đeo kính, nên tôi đã đến rất nhiều tiệm kính trong những năm qua. Lần đến Kooper's Vision gần đây của tôi vào ngày 31 tháng 8 là lần tuyệt vời nhất, hơn hẳn các lần khác.\n\nChị Palmer đã đề nghị giúp đỡ khi thấy tôi bị choáng ngợp trước quá nhiều mẫu kính ở Kooper's Vision. Chị ấy nhìn khuôn mặt tôi và hướng tôi đến vài cặp kính hoàn hảo dành cho tôi! Chị ấy biết chính xác kiểu nào hợp với tôi nhất và tư vấn cho tôi về kích cỡ, màu sắc, chất lượng và giá của những chiếc gọng tôi cân nhắc. Chị Palmer còn giải thích các loại tròng kính và lớp phủ tròng kính hiện có. Tôi không thể quyết định cặp nào mình thích nhất, nên tôi đã mua hai cặp! Tôi không thể tin nổi khi chị ấy nói đó là ngày đầu tiên chị làm việc ở cửa hàng — chị ấy là chuyên viên quang học giỏi nhất tôi từng gặp!\n\nMelvin Drake","qs":[{"n":191,"q":"According to the job advertisement, what is true about the open position?","qvi":"Theo quảng cáo tuyển dụng, điều gì đúng về vị trí đang tuyển?","opts":["It comes with health insurance.","It starts at the end of August.","It includes a fashionable company uniform.","It requires that candidates work on a team."],"ans":"B","xp":"Câu hỏi chi tiết. Quảng cáo: \"Must be available to start during the last week of August.\" (bắt đầu làm trong tuần cuối tháng Tám) → bắt đầu vào cuối tháng Tám → (B). (A) bẫy: quảng cáo nhắc \"filing insurance claims\" (nộp hồ sơ bảo hiểm cho khách) chứ không phải nhân viên được bảo hiểm y tế. (C) bẫy: \"fashion trends\" là am hiểu xu hướng thời trang, không phải đồng phục. (D) không được nhắc tới.\n(A) Vị trí này có bảo hiểm y tế.\n(B) Vị trí này bắt đầu vào cuối tháng Tám.\n(C) Vị trí này có đồng phục công ty thời trang.\n(D) Vị trí này yêu cầu ứng viên làm việc theo nhóm."},{"n":192,"q":"What is indicated about Kooper's Vision on the Web page?","qvi":"Trang web cho biết điều gì về Kooper's Vision?","opts":["It stays open later on Saturday.","It is located on the lower level of a mall.","It offers a selection of sports eyeglasses.","It requires an appointment for an eye exam."],"ans":"D","xp":"Câu hỏi chi tiết. Trang web: \"Call 978-555-0101 today to schedule your annual eye exam. Exams by appointment only.\" → khám mắt phải đặt lịch hẹn → (D). (A) sai: thứ Bảy đóng cửa lúc 6 giờ, sớm hơn các ngày thường (7 giờ). (B) sai: cửa hàng ở \"upper level\" (tầng trên). (C) bẫy: \"Eight Days Sporting Goods\" chỉ là cửa hàng thể thao bên cạnh.\n(A) Cửa hàng mở cửa muộn hơn vào thứ Bảy.\n(B) Cửa hàng nằm ở tầng dưới của trung tâm thương mại.\n(C) Cửa hàng có nhiều loại kính thể thao.\n(D) Cửa hàng yêu cầu đặt lịch hẹn để khám mắt."},{"n":193,"q":"What is most likely true about Ms. Palmer?","qvi":"Điều gì nhiều khả năng đúng về chị Palmer?","opts":["She works with Ms. Mosley.","She previously worked at a fashion shop.","She earned an optician license two years ago.","She is the new owner of Kooper's Vision."],"ans":"A","xp":"Câu hỏi suy luận (liên kết 3 văn bản). Bài đánh giá: ngày 31/8 là \"her first day working at the store\" và chị là \"optician\". Quảng cáo: Kooper's Vision ở Danvers Mall tuyển optician, bắt đầu \"during the last week of August\", liên hệ \"store manager Tanisha Mosley\" → chị Palmer chính là người được tuyển vào vị trí đó, làm việc tại cửa hàng do chị Mosley quản lý → làm việc cùng chị Mosley → (A). (C) sai: quảng cáo yêu cầu ít nhất ba năm kinh nghiệm nên khó có chuyện mới có giấy phép hai năm. (B), (D) không có căn cứ.\n(A) Chị ấy làm việc cùng chị Mosley.\n(B) Chị ấy từng làm ở một cửa hàng thời trang.\n(C) Chị ấy có giấy phép hành nghề quang học từ hai năm trước.\n(D) Chị ấy là chủ mới của Kooper's Vision."},{"n":194,"q":"According to the review, how did Ms. Palmer help Mr. Drake?","qvi":"Theo bài đánh giá, chị Palmer đã giúp ông Drake như thế nào?","opts":["By recommending frames that fit his face","By extending the length of his appointment","By choosing glasses for his children","By upgrading the coating on his eyeglass lenses"],"ans":"A","xp":"Câu hỏi chi tiết. Bài đánh giá: \"She looked at the shape of my face and steered me toward a few pairs of glasses that were perfect for me!\" → chị gợi ý những gọng kính hợp với khuôn mặt ông → (A). (D) bẫy: chị chỉ \"explained the different types of lenses and lens coatings\" (giải thích), không nâng cấp. (C) bẫy: ông có con đeo kính nhưng chị không chọn kính cho con ông. (B) không được nhắc tới.\n(A) Bằng cách gợi ý gọng kính hợp với khuôn mặt ông ấy\n(B) Bằng cách kéo dài thời gian cuộc hẹn của ông ấy\n(C) Bằng cách chọn kính cho các con ông ấy\n(D) Bằng cách nâng cấp lớp phủ trên tròng kính của ông ấy"},{"n":195,"q":"What is suggested about Mr. Drake?","qvi":"Có thể suy ra điều gì về ông Drake?","opts":["He thinks his prescription has changed.","He started wearing eyeglasses recently.","He frequently shops at Danvers Mall.","He received a discount on his purchase."],"ans":"D","xp":"Câu hỏi suy luận (liên kết 2 văn bản). Bài đánh giá: ông đến cửa hàng \"on August 31\" và \"I bought two pairs!\". Trang web: \"During the month of August, enjoy 50% off the second pair of eyeglasses.\" → mua hai cặp trong tháng Tám nên cặp thứ hai được giảm 50% → ông được giảm giá → (D). (B) sai: ông đeo kính \"since I was ten years old\". (A), (C) không được nhắc tới.\n(A) Ông ấy nghĩ độ kính của mình đã thay đổi.\n(B) Ông ấy mới bắt đầu đeo kính gần đây.\n(C) Ông ấy thường xuyên mua sắm ở trung tâm thương mại Danvers.\n(D) Ông ấy được giảm giá khi mua hàng."}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following Web page and e-mails.","passages":["<p><i>https://www.hellosnackvending.com/services</i></p><h3>Our Services</h3><p>Hello Snack Vending offers a variety of vending and coffee services for company break rooms and vending machines.</p><p><b>Service 1 (Micromarket)</b>—We set up a small market in your break room, with customized products available on open shelves. Micromarkets are self-service and feature electronic payments. Shelving and fixtures are provided.</p><p><b>Service 2 (Pantry)</b>—We stock your break room cabinets with a variety of products that you select. Pantry service is paid for in advance, freeing users from paying per item.</p><p><b>Service 3 (Coffee)</b>—We keep your break room stocked with coffee, tea, and all related essentials. We supply you with group-sized coffee makers, coffee, and individually sized creamer and sugar varieties.</p><p><b>Service 4 (Traditional Vending)</b>—We regularly stock your vending machine with a customized selection of carbonated beverages, juice, and water.</p><p><b>Service 5 (Healthy Vending)</b>—We regularly stock your vending machine with a wide selection of healthy snacks.</p>","<div class=\"hdr\"><p><b>To:</b> customercare@hellosnackvending.com</p><p><b>From:</b> dlewis@kivowitzcompany.com</p><p><b>Date:</b> November 14</p><p><b>Subject:</b> Vending service</p></div><p>Hello,</p><p>My company recently bought a gently used nonrefrigerated vending machine, which has been placed in our employee break room. I am looking for a stocking service to fill it so that the staff can start using it.</p><p>Does your company only stock vending machines that you own, or do you also offer a stocking service for other machines? If you can service ours, I would like to know more about the snacks you have available to fill the machine. Could you please send me a list of the products you offer?</p><p>Thank you for your assistance.</p><p>Best regards,</p><p>Denikia Lewis<br>Kivowitz Company</p>","<div class=\"hdr\"><p><b>To:</b> Denikia Lewis &lt;dlewis@kivowitzcompany.com&gt;</p><p><b>From:</b> Customer Care &lt;customercare@hellosnackvending.com&gt;</p><p><b>Date:</b> November 15</p><p><b>Subject:</b> Re: Vending service</p><p><b>Attachment:</b> List</p></div><p>Dear Ms. Lewis,</p><p>Thank you for your e-mail. We would be happy to stock your machine even if it is not owned by our company. However, if your machine is old, it can be difficult to obtain parts for it, and older machines break more often. The cost of repairs can get high, making it more cost-effective for you to use one of our vending machines. Can you provide me with the model number?</p><p>I have attached the list you requested. We can accommodate special requests if you have any. I also recommend renting a drink machine from us, because we find that employees usually enjoy having a cold drink with their snacks.</p><p>Please contact me if you have additional questions.</p><p>Sincerely,</p><p>Dominik Scheibler<br>Customer Care Representative</p>"],"vi":"https://www.hellosnackvending.com/services\nDịch vụ của chúng tôi\n\nHello Snack Vending cung cấp nhiều dịch vụ bán hàng tự động và cà phê cho phòng nghỉ của công ty và máy bán hàng tự động.\n\nDịch vụ 1 (Siêu thị mini) — Chúng tôi lập một khu chợ nhỏ trong phòng nghỉ của bạn, với các sản phẩm theo yêu cầu bày trên kệ mở. Siêu thị mini là hình thức tự phục vụ và có thanh toán điện tử. Kệ và thiết bị cố định được cung cấp sẵn.\n\nDịch vụ 2 (Tủ đồ ăn) — Chúng tôi chất đầy tủ trong phòng nghỉ của bạn với nhiều sản phẩm do bạn chọn. Dịch vụ tủ đồ ăn được thanh toán trước, giúp người dùng không phải trả tiền cho từng món.\n\nDịch vụ 3 (Cà phê) — Chúng tôi đảm bảo phòng nghỉ của bạn luôn có cà phê, trà và mọi thứ thiết yếu liên quan. Chúng tôi cung cấp máy pha cà phê cỡ dùng cho nhóm, cà phê, cùng các loại kem pha cà phê và đường đóng gói cỡ cá nhân.\n\nDịch vụ 4 (Máy bán hàng truyền thống) — Chúng tôi thường xuyên bổ sung cho máy bán hàng tự động của bạn các loại nước có ga, nước ép và nước uống được chọn theo yêu cầu.\n\nDịch vụ 5 (Máy bán đồ ăn lành mạnh) — Chúng tôi thường xuyên bổ sung cho máy bán hàng tự động của bạn nhiều loại đồ ăn vặt lành mạnh.\n\nNgười nhận: customercare@hellosnackvending.com\nNgười gửi: dlewis@kivowitzcompany.com\nNgày: 14 tháng 11\nTiêu đề: Dịch vụ máy bán hàng tự động\n\nXin chào,\n\nCông ty tôi vừa mua một chiếc máy bán hàng tự động không có ngăn lạnh đã qua sử dụng nhưng còn tốt, và nó đã được đặt trong phòng nghỉ của nhân viên. Tôi đang tìm một dịch vụ bổ sung hàng để lấp đầy máy để nhân viên có thể bắt đầu sử dụng.\n\nCông ty của quý vị chỉ bổ sung hàng cho các máy do quý vị sở hữu, hay có cung cấp dịch vụ bổ sung hàng cho các máy khác? Nếu quý vị có thể phục vụ máy của chúng tôi, tôi muốn biết thêm về các loại đồ ăn vặt quý vị có để cho vào máy. Quý vị có thể gửi cho tôi danh sách các sản phẩm quý vị cung cấp được không?\n\nCảm ơn sự hỗ trợ của quý vị.\n\nTrân trọng,\n\nDenikia Lewis\nCông ty Kivowitz\n\nNgười nhận: Denikia Lewis <dlewis@kivowitzcompany.com>\nNgười gửi: Bộ phận Chăm sóc khách hàng <customercare@hellosnackvending.com>\nNgày: 15 tháng 11\nTiêu đề: Re: Dịch vụ máy bán hàng tự động\nTệp đính kèm: Danh sách\n\nKính gửi chị Lewis,\n\nCảm ơn chị đã gửi e-mail. Chúng tôi rất sẵn lòng bổ sung hàng cho máy của chị ngay cả khi máy không thuộc sở hữu của công ty chúng tôi. Tuy nhiên, nếu máy của chị đã cũ, có thể khó tìm linh kiện cho nó, và máy cũ thường hay hỏng hơn. Chi phí sửa chữa có thể trở nên cao, khiến việc sử dụng một trong các máy bán hàng của chúng tôi sẽ tiết kiệm hơn cho chị. Chị có thể cho tôi biết số model của máy không?\n\nTôi đã đính kèm danh sách chị yêu cầu. Chúng tôi có thể đáp ứng các yêu cầu đặc biệt nếu chị có. Tôi cũng khuyên chị nên thuê một máy bán đồ uống của chúng tôi, vì chúng tôi nhận thấy nhân viên thường thích có đồ uống lạnh đi kèm đồ ăn vặt.\n\nVui lòng liên hệ tôi nếu chị có thêm câu hỏi.\n\nTrân trọng,\n\nDominik Scheibler\nNhân viên Chăm sóc khách hàng","qs":[{"n":196,"q":"What is mentioned about Service 1 ?","qvi":"Điều gì được nhắc đến về Dịch vụ 1?","opts":["It comes with a fixed product selection.","It allows users to pay electronically.","It requires an annual contract.","It includes shelving for an extra fee."],"ans":"B","xp":"Câu hỏi chi tiết. Trang web: \"Micromarkets are self-service and feature electronic payments.\" (có thanh toán điện tử) → người dùng có thể trả tiền điện tử → (B). (A) sai: sản phẩm là \"customized\" (theo yêu cầu), không cố định. (D) sai: \"Shelving and fixtures are provided\" — kệ được cung cấp sẵn, không nói tính thêm phí. (C) không được nhắc tới.\n(A) Dịch vụ có danh mục sản phẩm cố định.\n(B) Dịch vụ cho phép người dùng thanh toán điện tử.\n(C) Dịch vụ yêu cầu hợp đồng hằng năm.\n(D) Dịch vụ bao gồm kệ với phụ phí."},{"n":197,"q":"What does Ms. Lewis suggest about her company's vending machine?","qvi":"Chị Lewis ngụ ý điều gì về máy bán hàng tự động của công ty chị?","opts":["It is in poor condition.","It was recently serviced.","It was overpriced.","It is currently empty."],"ans":"D","xp":"Câu hỏi suy luận. E-mail của chị Lewis: \"I am looking for a stocking service to fill it so that the staff can start using it.\" → cần người cho hàng vào máy để nhân viên bắt đầu dùng → hiện máy đang trống → (D). (A) sai: máy là \"gently used\" (đã dùng nhưng còn tốt). (B), (C) không được nhắc tới.\n(A) Máy đang trong tình trạng tồi.\n(B) Máy vừa được bảo dưỡng.\n(C) Máy bị mua với giá quá cao.\n(D) Máy hiện đang trống."},{"n":198,"q":"What does Mr. Scheibler ask Ms. Lewis to send him?","qvi":"Anh Scheibler đề nghị chị Lewis gửi cho anh ấy cái gì?","opts":["A signed contract for the service","A picture of her vending machine","A list of needed parts","A model number"],"ans":"D","xp":"Câu hỏi chi tiết. E-mail thứ hai: \"Can you provide me with the model number?\" (Chị có thể cho tôi biết số model không?) → (D). (C) bẫy: e-mail nhắc \"difficult to obtain parts\" nhưng không xin danh sách linh kiện; \"list\" trong e-mail là danh sách sản phẩm anh gửi cho chị.\n(A) Hợp đồng dịch vụ đã ký\n(B) Ảnh chụp máy bán hàng của chị ấy\n(C) Danh sách linh kiện cần thiết\n(D) Số model"},{"n":199,"q":"What is included in the list Mr. Scheibler attached to his e-mail?","qvi":"Danh sách anh Scheibler đính kèm trong e-mail có nội dung gì?","opts":["The snacks that his company offers","The dates that his company can make deliveries","The brand of vending machines that his company uses","The costs involved with vending services"],"ans":"A","xp":"Câu hỏi liên kết 2 văn bản. Anh Scheibler: \"I have attached the list you requested.\" Danh sách chị Lewis yêu cầu: \"I would like to know more about the snacks you have available to fill the machine. Could you please send me a list of the products you offer?\" → danh sách các đồ ăn vặt/sản phẩm công ty anh cung cấp → (A). Ngày giao hàng, nhãn hiệu máy, chi phí đều không được yêu cầu.\n(A) Các loại đồ ăn vặt mà công ty anh ấy cung cấp\n(B) Những ngày công ty anh ấy có thể giao hàng\n(C) Nhãn hiệu máy bán hàng mà công ty anh ấy dùng\n(D) Các chi phí liên quan đến dịch vụ bán hàng tự động"},{"n":200,"q":"What additional service does Mr. Scheibler suggest?","qvi":"Anh Scheibler gợi ý dịch vụ bổ sung nào?","opts":["Service 2","Service 3","Service 4","Service 5"],"ans":"C","xp":"Câu hỏi liên kết 2 văn bản. E-mail thứ hai: \"I also recommend renting a drink machine from us, because ... employees usually enjoy having a cold drink with their snacks.\" → gợi ý thêm máy bán đồ uống. Trang web: \"Service 4 (Traditional Vending)—We regularly stock your vending machine with a customized selection of carbonated beverages, juice, and water.\" → dịch vụ cho máy bán đồ uống là Dịch vụ 4 → (C). Dịch vụ 5 là đồ ăn vặt lành mạnh (chính là thứ chị Lewis cần cho máy của mình, không phải dịch vụ bổ sung); Dịch vụ 3 là cà phê/trà cho phòng nghỉ, không phải đồ uống lạnh trong máy.\n(A) Dịch vụ 2 (Tủ đồ ăn)\n(B) Dịch vụ 3 (Cà phê)\n(C) Dịch vụ 4 (Máy bán hàng truyền thống – đồ uống)\n(D) Dịch vụ 5 (Đồ ăn vặt lành mạnh)"}]}]}};
